import socket
import time
import signal
import sys
import threading
import random
import logging

try:
    from gpiozero import DigitalOutputDevice, PWMOutputDevice, MCP3008
except Exception as e:
    MCP3008 = None
    DigitalOutputDevice = None
    PWMOutputDevice = None
    gpiozero = None
    logging.warning(f"gpiozero unavailable: {e}")

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

SERVER_PORT = 12345
MOTOR_A_FORWARD_PIN = 27
MOTOR_A_BACKWARD_PIN = 22
MOTOR_B_CLOCKWISE_PIN = 24
MOTOR_B_COUNTERCLOCKWISE_PIN = 25
MOTOR_A_ENABLE_PIN = 17
MOTOR_B_ENABLE_PIN = 23
SPI_CLK_PIN = 11
SPI_MOSI_PIN = 10
SPI_MISO_PIN = 9
SPI_CS_1_PIN = 8
SPI_CS_2_PIN = 7

motor_a_forward = None
motor_a_backward = None
motor_b_clockwise = None
motor_b_counter = None
motor_a_pwm = None
motor_b_pwm = None
sensor1 = None
sensor2 = None
spi_clk = None
spi_mosi = None
spi_miso = None
spi_cs_1 = None
spi_cs_2 = None
server_socket = None
shutdown_event = threading.Event()

def init_hardware():
    global motor_a_forward, motor_a_backward, motor_b_clockwise, motor_b_counter, motor_a_pwm, motor_b_pwm, sensor1, sensor2, spi_clk, spi_mosi, spi_miso, spi_cs_1, spi_cs_2
    if gpiozero is None:
        logger.error("gpiozero library not available; hardware initialization skipped.")
        return False
    try:
        motor_a_forward = DigitalOutputDevice(MOTOR_A_FORWARD_PIN)
        motor_a_backward = DigitalOutputDevice(MOTOR_A_BACKWARD_PIN)
        motor_b_clockwise = DigitalOutputDevice(MOTOR_B_CLOCKWISE_PIN)
        motor_b_counter = DigitalOutputDevice(MOTOR_B_COUNTERCLOCKWISE_PIN)
        motor_a_pwm = PWMOutputDevice(MOTOR_A_ENABLE_PIN, frequency=1000)
        motor_b_pwm = PWMOutputDevice(MOTOR_B_ENABLE_PIN, frequency=1000)
        sensor1 = MCP3008(channel=0, clock_pin=spi_clk, mosi_pin=spi_mosi, miso_pin=spi_miso, select_pin=spi_cs_1)
        sensor2 = MCP3008(channel=1, clock_pin=spi_clk, mosi_pin=spi_mosi, miso_pin=spi_miso, select_pin=spi_cs_2)
        logger.info("Hardware initialization complete.")
        return True
    except Exception as e:
        logger.error(f"Hardware initialization failed: {e}")
        return False

def read_moisture(sensor, sensor_id):
    if sensor is None:
        logger.error(f"Sensor {sensor_id} not initialized.")
        return -1
    for i in range(5):
        try:
            time.sleep(0.02)
            return sensor.read()
        except Exception as e:
            logger.error(f"Error reading sensor {sensor_id} (attempt {i+1}): {e}")
            time.sleep(0.02)
    logger.error(f"Failed to read sensor {sensor_id} after 5 attempts.")
    return -1

def control_motor(motor, direction, enable, duration):
    if motor is None:
        logger.error("Motor not initialized.")
        return
    try:
        if direction == "forward":
            motor_a_forward.on()
            motor_a_backward.off()
            motor_b_clockwise.on()
            motor_b_counter.off()
            enable.on()
            logger.info(f"Motor {motor} moving forward for {duration} seconds.")
            time.sleep(duration)
            enable.off()
        elif direction == "backward":
            motor_a_forward.off()
            motor_a_backward.on()
            motor_b_clockwise.off()
            motor_b_counter.on()
            enable.on()
            logger.info(f"Motor {motor} moving backward for {duration} seconds.")
            time.sleep(duration)
            enable.off()
        else:
            logger.warning(f"Invalid motor direction: {direction}")
    except Exception as e:
        logger.error(f"Error controlling motor {motor}: {e}")

def water_plant(motor, duration):
    logger.info(f"Watering plant {motor} for {duration} seconds.")
    control_motor(motor, "forward", motor_a_pwm, duration)
    control_motor(motor, "backward", motor_a_pwm, duration)
    logger.info(f"Watering plant {motor} complete.")

def get_sensor_data():
    data = {"sensor1": read_moisture(sensor1, 1), "sensor2": read_moisture(sensor2, 2)}
    for key, value in data.items():
        if value == -1:
            data[key] = "Error"
    return data

def set_threshold(value):
    global threshold1, threshold2
    if 0 <= value <= 1000:
        threshold1 = value
        threshold2 = value
        logger.info(f"Threshold set to {value} for both sensors.")
    else:
        logger.warning(f"Invalid threshold value: {value}. Keeping previous thresholds.")

def set_watering_duration(value):
    global watering_duration
    if 1 <= value <= 300:
        watering_duration = value
        logger.info(f"Watering duration set to {value} seconds.")
    else:
        logger.warning(f"Invalid watering duration: {value}. Keeping previous duration.")

def handle_client(conn, addr):
    global threshold1, threshold2, watering_duration
    try:
        data = conn.recv(1024).decode().strip()
        if not data:
            return
        logger.info(f"Received command from {addr}: {data}")
        if "WATER_PLANT_1" in data:
            water_plant("motor_a", watering_duration)
        elif "WATER_PLANT_2" in data:
            water_plant("motor_b", watering_duration)
        elif "GET_SENSOR_DATA" in data:
            data = get_sensor_data()
            conn.sendall(data.encode())
        elif "SET_THRESHOLD" in data:
            set_threshold(data.split("=", 1)[1])
        elif "SET_WATERING_DURATION" in data:
            set_watering_duration(data.split("=", 1)[1])
        else:
            logger.warning(f"Unknown command from {addr}: {data}")
    except socket.error as e:
        logger.error(f"Socket error handling client {addr}: {e}")
    except Exception as e:
        logger.error(f"Error handling client {addr}: {e}")
    finally:
        try:
            conn.close()
        except Exception:
            pass

def cleanup(signum=None, frame=None):
    logger.info("Cleaning up resources...")
    shutdown_event.set()
    if server_socket:
        try:
            server_socket.close()
        except Exception:
            pass
    if spi_clk:
        try:
            spi_clk.close()
        except Exception:
            pass
    if spi_mosi:
        try:
            spi_mosi.close()
        except Exception:
            pass
    if spi_miso:
        try:
            spi_miso.close()
        except Exception:
            pass
    if spi_cs_1:
        try:
            spi_cs_1.close()
        except Exception:
            pass
    if spi_cs_2:
        try:
            spi_cs_2.close()
        except Exception:
            pass
    logger.info("Cleanup complete. Exiting.")
    sys.exit(0)

def main():
    global threshold1, threshold2, watering_duration, server_socket
    if not init_hardware():
        logger.error("Hardware initialization failed. Exiting.")
        sys.exit(1)
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind(("", SERVER_PORT))
        server_socket.listen(5)
        logger.info(f"Server listening on port {SERVER_PORT}")
        while not shutdown_event.is_set():
            try:
                conn, addr = server_socket.accept()
                client_thread = threading.Thread(target=handle_client, args=(conn, addr))
                client_thread.daemon = True
                client_thread.start()
            except socket.error as e:
                logger.error(f"Accept error: {e}")
            except Exception as e:
                logger.error(f"Unexpected error in main loop: {e}")
            for _ in range(60):
                if shutdown_event.is_set():
                    break
                time.sleep(1)
    except Exception as e:
        logger.error(f"Server error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    main()

