import time
import logging
import signal
import sys
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False
    logging.info(f"Signal {signum} received, shutting down...")


class Oscilloscope:
    """
    Object-oriented oscilloscope using an ADS1115 ADC on I2C.
    """

    def __init__(self, i2c_address=0x48, gain=1, channels=['ch0', 'ch1']):
        self.i2c_address = i2c_address
        self.gain = gain
        self.channels = channels
        self.adc = None
        self.channels = []
        self._initialize()

    def _initialize(self):
        """Open I2C bus, configure ADS1115, and create AnalogIn objects."""
        try:
            i2c = busio.I2C(board.SCL, board.SDA)
            self.adc = ADS.ADS1115(i2c, address=self.i2c_address)
            self.adc.gain = self.gain
            self.channels = [
                AnalogIn(self.adc, ADS.P0),
                AnalogIn(self.adc, ADS.P1),
            ]
            logging.info(
                f"ADS1115 initialized at 0x{self.i2c_address:02X}, "
                f"gain={self.gain}, channels={self.channels}"
            )
        except Exception as e:
            logging.error(f"Initialization failed: {e}")
            self.close()
            raise

    def run(self):
        """Continuously sample channels and print CSV rows."""
        if not self.channels:
            logging.error("No channels configured; cannot run.")
            return
        logging.info("Starting sampling loop (10 Hz, Ctrl-C to stop).")
        try:
            while _running:
                try:
                    v0 = self.channels[0].value
                    v1 = self.channels[1].value
                    ts = time.monotonic()
                    print(
                        f"{ts:.3f},{v0:.3f},{v1:.3f}\n",
                        flush=True,
                    )
                except OSError as e:
                    logging.error(f"I2C bus error during read: {e}")
                    break
                except Exception as e:
                    logging.error(f"Unexpected read error: {e}")
                    break
                time.sleep(0.1)
        except KeyboardInterrupt:
            logging.info("Sampling stopped by user.")
        finally:
            self.close()

    def close(self):
        """Release ADC, channels, and I2C bus resources."""
        if self.adc is not None:
            try:
                self.adc.deinit()
            except Exception as e:
                logging.error(f"Error deinitializing ADS1115: {e}")
            self.adc = None
        for ch in self.channels:
            try:
                ch.close()
            except Exception as e:
                logging.error(f"Error closing channel: {e}")
            self.channels.clear()
        try:
            busio.deinit(board.SCL, board.SDA)
        except Exception as e:
            logging.error(f"Error releasing I2C bus: {e}")


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    osc = Oscilloscope()
    try:
        osc.run()
    except Exception as e:
        logging.error(f"Fatal error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

