import time
import logging
import argparse
import threading
import queue
import spidev
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed, log_queue):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.sound_detected = False
        self.debounce_time = 0.1
        self.spi = None
        self.gpio_initialized = False
        self._lock = threading.Lock()

        if self.sensor_type == 'digital':
            self.gpio_available = True
            self.gpio_pins = [int(pin) for pin in gpio_pins]
            if not self.gpio_pins:
                raise ValueError("gpio_pins list cannot be empty")
            self.gpio_initialized = self._setup_gpio()
        elif self.sensor_type == 'analog':
            self.gpio_available = False
            if self.gpio_pins:
                raise ValueError("gpio_pins not supported for analog sensors")
            self.spi_available = True
            if not channels:
                raise ValueError("channels list cannot be empty")
            self.spi = self._setup_spi()
        else:
            raise ValueError("Invalid sensor_type. Must be 'digital' or 'analog'.")

    def _setup_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            for pin in self.gpio_pins:
                GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logger.info(f"GPIO setup complete for {self.sensor_id}")
