import time
import signal
import sys
import logging
from smbus2 import SMBus, i2c_msg

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

ADS1115_ADDRESS = 0x48
I2C_BUS_NUMBER = 3
REG_CONVERSION = 0x00
REG_CONFIG = 0x01

CONFIG_BASE = 0x83E0
CONFIG_AIN0_GND = 0x83E0
CONFIG_AIN0_GND_6_144V = 0x83E0

R1 = 2000
R2 = 1000
C = 0.99

CHARGE_MIN = 0.0
CHARGE_MAX = 100.0
CHANGE_THRESHOLD = 1.0
READ_INTERVAL = 1.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _to_signed(raw: int) -> int:
    return raw - 0x10000 if raw & 0x8000 else raw


def _voltage(raw: int) -> float:
    return (raw / 32767.0) * 6.144 * (R1 + R2) / R2 * C


def _charge(v: float) -> float:
    return ((v - 10.5) / (13.8 - 10.5)) * 100.0


def _write_config(bus: SMBus, config: int) -> None:
    bus.write_word_data(ADS1115_ADDRESS, REG_CONFIG, config)


def _read_conversion(bus: SMBus) -> int:
    return bus.read_word_data(ADS1115_ADDRESS, REG_CONVERSION)


def _init_sensor(bus: SMBus) -> None:
    _write_config(bus, CONFIG_AIN0_GND)


def _read_and_process(bus: SMBus) -> float:
    time.sleep(0.1)
    raw = _read_conversion(bus)
    return _to_signed(raw)


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    bus = None
    try:
        bus = SMBus(I2C_BUS_NUMBER)
        _init_sensor(bus)
        last_charge = None

        while _running:
            try:
                voltage = _read_and_process(bus)
                charge = _charge(voltage)

                if last_charge is None or abs(charge - last_charge) >= CHANGE_THRESHOLD:
                    last_charge = charge
                    print(f"Battery Voltage: {voltage:.2f} V | Charge: {last_charge:.2f}%")

                time.sleep(READ_INTERVAL)
            except OSError as e:
                logger.warning("I2C bus error: %s", e)
                time.sleep(READ_INTERVAL)
            except Exception as e:
                logger.error("Unexpected error: %s", e)
                time.sleep(READ_INTERVAL)

    except OSError as e:
        logger.error("Failed to open I2C bus %d: %s", I2C_BUS_NUMBER, e)
    except Exception as e:
        logger.error("Fatal error: %s", e)
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass


if __name__ == '__main__':
    main()

