import time
import signal
import sys
import board
import busio
import adafruit_max30102

LOG_FILE = 'heart_rate_log.txt'
SAMPLE_INTERVAL = 1.0
WINDOW_SECONDS = 4.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_heart_rate(sensor):
    """Return (bpm, spo2) or (None, None) on error."""
    try:
        ir_values = sensor.get_ir_values()
        red_values = sensor.get_red_values()
    except Exception as exc:
        print(f"[ERROR] Sensor read failed: {exc}", file=sys.stderr)
        return None, None

    if ir_values is None or red_values is None:
        print("[ERROR] Sensor returned None values", file=sys.stderr)
        return None, None

    # Peak detection over a short window for a rough BPM estimate
    window = []
    for _ in range(WINDOW_SECONDS):
        if not _running:
            return None, None
        window.append(ir_values)
        window.append(red_values)

    if not window:
        return None, None

    ir_peaks = []
    red_peaks = []
    for i in range(len(window) - 1):
        if not _running:
            return None, None
        ir = window[i]
        red = window[i + 1]
        if ir > red:
            ir_peaks.append(i)
        if red > ir:
            red_peaks.append(i)

    if not ir_peaks:
        return None, None

    # Simple peak-to-peak timing estimate
    if len(ir_peaks) < 2:
        return None, None

    delta = (ir_peaks[-1] - ir_peaks[0]) % len(window)
    if delta < 0:
        delta += len(window)

    # Guard against division by zero
    if delta == 0:
        return None, None

    bpm = (1.0 / (delta * 60.0)) + 60.0
    spo2 = 100.0 - (red_peaks[-1] - ir_peaks[-1]) * 2.0
    spo2 = max(0.0, spo2)

    return round(bpm, 1), round(spo2, 1)

def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    i2c = None
    sensor = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c, address=0x57)
        print("MAX30102 initialized at I2C address 0x57.")
    except Exception as exc:
        print(f"[ERROR] Failed to initialize MAX30102: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            hr, spo2 = read_heart_rate(sensor)
            timestamp = time.strftime('%Y-%m-%dT%H:%M:%S')
            line = f"{timestamp} - HR: {hr} bpm, SpO2: {spo2}%\n"
            try:
                with open(LOG_FILE, 'a') as f:
                    f.write(line)
            except OSError as exc:
                print(f"[ERROR] Failed to write log: {exc}", file=sys.stderr)
            print(line, end='')

            # Sleep in small increments so SIGINT is responsive
            elapsed = 0.0
            while _running and elapsed < SAMPLE_INTERVAL:
                time.sleep(0.1)
                elapsed += 0.1
    finally:
        if sensor is not None:
            try:
                sensor.deinit()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        print("\nResources cleaned up. Exiting.")

if __name__ == '__main__':
    main()

