import io
import time
import json
import signal
import threading
import queue
import logging
import os
import RPi.GPIO as GPIO
from picamera2 import Picamera2
from gpiozero import LED

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class MotionDetector:
    def __init__(self, threshold):
        self.threshold = threshold
        self.last_frame = None

    def detect_motion(self, image_array):
        if self.last_frame is None:
            self.last_frame = image_array
            return False
        if self.last_frame is None:
            return True
        diff = abs(image_array.astype(int) - self.last_frame.astype(int))
        changed_pixels = (diff > self.threshold).sum()
        self.last_frame = image_array
        return changed_pixels > 0

class CameraHandler:
    def __init__(self, config):
        self.config = config
        self.camera = None
        self.image_queue = queue.Queue(maxsize=config['max_queue_size'])
        self.running = True
        self.lock = threading.Lock()
        self.led = None
        self._init_camera()

    def _init_camera(self):
        try:
            self.camera = Picamera2()
            w, h = self.camera.camera_config['main']['size']
            self.camera.configure(self.camera.create_still_configuration(main={"size": (w, h)}))
            self.camera.start()
            time.sleep(self.config['warmup_time'])
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            self.camera = None

    def capture_and_enqueue(self):
        while self.running:
            try:
                if self.camera is None:
                    time.sleep(0.1)
                    continue
                frame = self.camera.capture_array()
                if frame is None:
                    continue
                with self.lock:
