import cv2
import time
import signal
import sys
import os
from gpiozero import LED, Button, AngularServo
from gpiozero.exc import GPIOZeroError

# Constants
LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
SERVO_MIN_ANGLE = 0
SERVO_MAX_ANGLE = 180
SERVO_INCREMENT = 20
SERVO_FREQUENCY = 50
SERVO_MIN_DUTY = 2.0
SERVO_MAX_DUTY = 12.0
CAMERA_INDEX = 0
CASCADE_PATH = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
WINDOW_NAME = 'Human Detection'
RESIZE_WIDTH = 320
RESIZE_HEIGHT = 240

# Global resources for cleanup
camera = None
window_open = False
led = None
button = None
servo = None
running = True


def cleanup():
    """Release all resources cleanly."""
    global camera, window_open, led, button, servo, running
    running = False
    if camera is not None:
        try:
            camera.release()
        except Exception:
            pass
        camera = None
    cv2.destroyAllWindows()
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None
    if button is not None:
        try:
            button.close()
        except Exception:
            pass
        button = None
    if servo is not None:
        try:
            servo.close()
        except Exception:
            pass
        servo = None


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def init_gpio():
    """Initialize GPIO devices. Returns True on success, False on failure."""
    global led, button, servo
    try:
        led = LED(LED_PIN)
        button = Button(BUTTON_PIN, pull_up=True)
        servo = AngularServo(
            SERVO_PIN,
            initial_angle=SERVO_MIN_ANGLE,
            min_angle=SERVO_MIN_ANGLE,
            max_angle=SERVO_MAX_ANGLE,
            min_duty_cycle=SERVO_MIN_DUTY,
            max_duty_cycle=SERVO_MAX_DUTY,
            frame_width=1.0 / SERVO_FREQUENCY,
        )
        return True
    except GPIOZeroError as e:
        print(f"GPIO initialization error: {e}")
        return False
    except Exception as e:
        print(f"Unexpected GPIO initialization error: {e}")
        return False


def init_camera():
    """Initialize the camera. Returns True on success, False on failure."""
    global camera
    try:
        camera = cv2.VideoCapture(CAMERA_INDEX, cv2.CAP_V4L2)
        if not camera.isOpened():
            print("Error: Could not open camera.")
            return False
        return True
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return False


def init_classifier():
    """Initialize the face detector. Returns True on success, False on failure."""
    global cascade
    try:
        cascade = cv2.CascadeClassifier(CASCADE_PATH)
        if cascade.empty():
            print(f"Error: Could not load cascade classifier from {CASCADE_PATH}")
            return False
        return True
    except Exception as e:
        print(f"Error initializing classifier: {e}")
        return False


def detect_faces(frame, cascade):
    """Detect faces in a frame using the provided cascade classifier."""
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    return cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))


def control_led(face_count):
    """Control the LED based on the number of detected faces."""
    if led is not None:
        if face_count > 0:
            led.on()
        else:
            led.off()


def control_servo(angle):
    """Control the servo to the specified angle (0-180 degrees)."""
    if servo is not None:
        try:
            servo.angle = angle
        except Exception as e:
            print(f"Servo control error: {e}")


def main():
    """Main function to run the human detection and control system."""
    global running, window_open

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not init_classifier():
        print("Failed to initialize classifier. Exiting.")
        cleanup()
        sys.exit(0)

    if not init_camera():
        print("Failed to initialize camera. Exiting.")
        cleanup()
        sys.exit(0)

    if not init_gpio():
        print("Warning: GPIO initialization failed. Continuing without GPIO control.")

    try:
        while running:
            ret, frame = camera.read()
            if not ret:
                print("Error: Could not read frame from camera.")
                break

            resized_frame = cv2.resize(frame, (RESIZE_WIDTH, RESIZE_HEIGHT))
            faces = detect_faces(resized_frame, cascade)

            face_count = len(faces)

            if face_count > 0:
                if face_count > 1:
                    print("Multiple faces detected!")
                else:
                    print(f"Face detected! Angle: {int(angle) if servo is not None else 0}")
            else:
                print("No face detected.")

            control_led(face_count)

            if button is not None:
                try:
                    if button.is_pressed:
                        print("Button pressed!")
                except Exception as e:
                    print(f"Button read error: {e}")

            if window_open:
                try:
                    cv2.imshow(WINDOW_NAME, resized_frame)
                    if cv2.waitKey(1) & 0xFF == ord('q'):
                        running = False
                except Exception as e:
                    print(f"Display error: {e}")
                    window_open = False

            if face_count > 0:
                angle = (int(angle) + 1 if (faces[0][2] + faces[0][3]) > RESIZE_WIDTH / 2 else (int(angle) - 1))
                angle = max(SERVO_MIN_ANGLE, min(SERVO_MAX_ANGLE, angle))
                control_servo(angle)
                time.sleep(0.02)
            else:
                if servo is not None:
                    try:
                        servo.angle = SERVO_MIN_ANGLE
                    except Exception as e:
                        print(f"Servo reset error: {e}")
                time.sleep(0.1)

    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

