import os
import sys
import time
import signal
import logging
import numpy as np
import mxnet as mx
from mxnet import image, nd
from mxnet.gluon.model_zoo import vision as models
from mxnet.gluon.utils import download
from picamera2 import Picamera2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

IMAGE_DIR = 'images'
NUM_TOP_PREDICTIONS = 5
MODEL_NAME = 'resnet50_v2'
SYNSET_URL = 'http://data.mxnet.io/models/imagenet/synset.txt'

_running = True

def signal_handler(sig, frame):
    global _running
    logger.info("Interrupt received, shutting down gracefully...")
    _running = False

def download_synset_file(url=SYNSET_URL):
    try:
        fname = download(url)
        with open(fname, 'r') as f:
            return [' '.join(l.split()[1:]) for l in f]
    except Exception as e:
        logger.error(f"Error downloading synset file: {e}")
        return None

def load_model(model_name=MODEL_NAME):
    try:
        net = models.get_model(model_name, pretrained=True, context=mx.cpu())
        net.hybridize()
        return net
    except Exception as e:
        logger.error(f"Error loading model: {e}")
        return None

def preprocess_image(img, image_width=224, image_height=224):
    try:
        img = image.resize_short(img, max(image_width, image_height))
        img, _ = image.center_crop(img, (image_width, image_height))
        arr = img.asnumpy()
        if arr.ndim == 3 and arr.shape[2] == 3:
            arr = np.transpose(arr, (2, 0, 1))
        elif arr.ndim == 2:
            arr = np.expand_dims(arr, axis=0)
        elif arr.ndim == 1:
            arr = np.expand_dims(arr, axis=0)
        arr = (arr.astype('float32') / 255.0 - np.array([103.939, 116.779, 123.684], dtype='float32')) * 0.007843
        return arr
    except Exception as e:
        logger.error(f"Error preprocessing image: {e}")
        return None

def predict(net, img, synsets, top_k=NUM_TOP_PREDICTIONS):
    try:
        prob = net(img).softmax()
        top_idx = prob.topk(k=top_k)[0]
        for i in top_idx:
            i = int(i.asscalar())
            if 0 <= i < len(synsets):
                print(f"{synsets[i]}: {prob[0, i].asscalar() * 100:.4f}%")
            else:
                print(f"Unknown: {prob[0, i].asscalar() * 100:.4f}%")
    except Exception as e:
        logger.error(f"Error during prediction: {e}")

def main():
    global _running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
    except Exception as e:
        logger.error(f"Error creating image directory: {e}")
        sys.exit(1)

    try:
        synsets = download_synset_file()
        if not synsets:
            sys.exit(1)

        net = load_model()
        if not net:
            sys.exit(1)

        picam2 = Picamera2()
        try:
            picam2.start()
            time.sleep(2)
            logger.info("Camera started successfully.")
        except Exception as e:
            logger.error(f"Error starting camera: {e}")
            sys.exit(1)

        try:
            frame = picam2.capture_array()
            if frame is None:
                logger.error("Failed to capture image from camera.")
                sys.exit(1)
        except Exception as e:
            logger.error(f"Error capturing image: {e}")
            sys.exit(1)

        img = image.imread(frame)
        if img is None:
            logger.error("Failed to load image from capture.")
            sys.exit(1)

        preprocessed_img = preprocess_image(img)
        if preprocessed_img is None:
            sys.exit(1)

        start_time = time.time()
        predict(net, preprocessed_img, synsets)
        end_time = time.time()
        logger.info(f"Prediction completed in {end_time - start_time:.4f} seconds.")

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        try:
            picam2.stop()
            logger.info("Camera stopped.")
        except Exception as e:
            logger.error(f"Error stopping camera: {e}")

if __name__ == '__main__':
    main()

