    try:
        prob = net(img).softmax()
        top_idx = prob.topk(k=top_k)[0]
        for i in top_idx:
            i = int(i.asscalar())
            if 0 <= i < len(synsets):
                print(f"{synsets[i]}: {prob[0, i].asscalar() * 100:.4f}%")
            else:
                print(f"Unknown: {prob[0, i].asscalar() * 100:.4f}%")
    except Exception as e:
        logger.error(f"Error during prediction: {e}")

