            self.picam2.start()
            logger.info('Camera initialized successfully (640x480, vflip=0, hflip=0).')
        except Exception as exc:
            logger.error('Failed to initialize camera: %s', exc)
            self.picam2 = None

    def get_frame(self) -> Optional[bytes]:
        """Capture a single JPEG frame; return bytes or None on error."""
        if self.picam2 is None:
            logger.error('Camera not initialized.')
            return None
        try:
            with self._lock:
                # capture_array returns a numpy array; encode to JPEG
                array = self.picam2.capture_array()
                if array is None:
                    logger.error('capture_array returned None.')
                    return None
                from PIL import Image
                img = Image.fromarray(array)
                buf = io.BytesIO()
                img.save(buf, format='JPEG', quality=85)
                return buf.getvalue()
        except Exception as exc:
            logger.error('Error capturing frame: %s', exc)
            return None

    def get_object(self, classifier: Config) -> Tuple[Optional[bytes], bool]:
        """Return (jpeg_bytes, detected) using the configured classifier."""
        if classifier is None:
