import json
import logging
import signal
import sys
import time
from datetime import datetime

try:
    from gpiozero import DigitalOutputDevice, DigitalInputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(0)

DEFAULT_CONFIG = {
    "sensor_config": [
        {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
        {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    ],
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning("Configuration file not found. Creating default config.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in configuration file: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()


def setup_logging(log_file):
    logging.basicConfig(
        filename=log_file,
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
    )


def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    try:
        trigger = DigitalOutputDevice(trigger_pin)
        echo = DigitalInputDevice(echo_pin)
        trigger.off()
        time.sleep(0.00001)
        trigger.on()
        time.sleep(0.00001)
        trigger.off()

        timeout = time.time() + 0.05
        while echo.value == 0:
            if time.time() > timeout:
                logging.error(f"Timeout waiting for echo rising edge on pin {echo_pin}")
                return None
            if not _running:
                return None
            time.sleep(0.0001)

        pulse_start = time.time()
        timeout = pulse_start + 0.05
        while echo.value == 1:
            if time.time() > timeout:
                logging.error(f"Timeout waiting for echo falling edge on pin {echo_pin}")
                return None
            if not _running:
                return None
            time.sleep(0.0001)

        pulse_end = time.time()
        pulse_duration = pulse_end - pulse_start
        distance = (pulse_duration * 34300) / 2 + offset
        distance = max(0.0, min(distance, max_distance))
        return distance
    except (GPIOZeroError, DeviceClosed) as e:
        logging.error(f"GPIO error measuring distance on pins {trigger_pin}/{echo_pin}: {e}")
        return None
    except Exception as e:
        logging.error(f"Unexpected error measuring distance on pins {trigger_pin}/{echo_pin}: {e}")
        return None


def get_average_water_level(sensor_config, alert_threshold_low, alert_threshold_high, alert_repeat_delay):
    readings = []
    for cfg in sensor_config:
        distance = measure_distance(
            cfg["trigger_pin"],
            cfg["echo_pin"],
            cfg["offset"],
            cfg["max_distance"],
        )
        if distance is not None:
            readings.append(distance)
        else:
            logging.warning(f"Skipping sensor on pins {cfg['trigger_pin']}/{cfg['echo_pin']} due to error.")
    if not readings:
        logging.error("No valid sensor readings obtained.")
        return None
    average_water_level = sum(readings) / len(readings)
    return average_water_level


def check_alerts(average_water_level, alert_threshold_low, alert_threshold_high, alert_repeat_delay):
    alerts = []
    for alert_type, threshold in [("low", alert_threshold_low), ("high", alert_threshold_high)]:
        if average_water_level is not None:
            if average_water_level < threshold:
                if alert_type not in alerts or (alerts[-1] is None or time.time() - alerts[-1]["time"] > alert_repeat_delay):
                    logging.warning(f"Alert: Water level is too low ({average_water_level:.2f} cm). Threshold: {threshold} cm")
                    alerts.append({"type": alert_type, "time": time.time()})
    return alerts


def log_data(average_water_level, alert_messages):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_message = f"Timestamp: {timestamp}, Average Water Level: {average_water_level:.2f} cm, Alerts: {alert_messages}"
    logging.info(log_message)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    config = load_config()
    setup_logging(config["log_file"])

    sensor_config = config.get("sensor_config", [])
    alert_threshold_low = config.get("alert_threshold_low", 10.0)
    alert_threshold_high = config.get("alert_threshold_high", 180.0)
    alert_repeat_delay = config.get("alert_repeat_delay", 60)
    log_file = config.get("log_file", "water_level.log")

    logging.info("Starting water level monitoring system...")
    logging.info(f"Configuration: {config}")

    sensors = []
    for cfg in sensor_config:
        trigger_pin = cfg["trigger_pin"]
        echo_pin = cfg["echo_pin"]
        offset = cfg.get("offset", 0.0)
        max_distance = cfg.get("max_distance", 200.0)
        sensors.append((trigger_pin, echo_pin, offset, max_distance))

    try:
        while _running:
            valid_readings = []
            for trigger_pin, echo_pin, offset, max_distance in sensors:
                distance = measure_distance(trigger_pin, echo_pin, offset, max_distance)
                if distance is not None:
                    valid_readings.append(distance)
                else:
                    logging.warning(f"Sensor on pins {trigger_pin}/{echo_pin} failed.")

            if valid_readings:
                average_water_level = get_average_water_level(valid_readings, alert_threshold_low, alert_threshold_high, alert_repeat_delay)
                if average_water_level is not None:
                    alert_messages = check_alerts(average_water_level, alert_threshold_low, alert_threshold_high, alert_repeat_delay)
                    log_data(average_water_level, alert_messages)
            else:
                logging.warning("No valid sensor readings obtained.")

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        for trigger_pin, echo_pin, offset, max_distance in sensors:
            try:
                trigger.close()
                echo.close()
            except Exception:
                pass
        logging.info("GPIO cleanup completed. Exiting program.")
        logging.shutdown()


if __name__ == "__main__":
    main()

