#!/usr/bin/env python3
"""
Greenhouse Control System for Raspberry Pi
Controls lights via GPIO, reads temperature from DHT11, captures images with PiCamera2,
and listens for voice commands via speech_recognition.
Falls back to simulation if hardware is unavailable.
"""

import time
import datetime
import signal
import sys
import random
import speech_recognition as sr
from picamera2 import Picamera2
import RPi.GPIO as GPIO
import adafruit_dht

# Configuration
GPIO_PIN_LIGHTS = 17
DHT_PIN = 4
WAKE_WORD = "Greenhouse"
CAMERA_RESOLUTION = (640, 480)

# Global state
running = True
camera = None
dht_device = None
gpio_initialized = False

def signal_handler(sig, frame):
    global running
    print(f"\nReceived signal {sig}, shutting down...")
    running = False

def simulate_gpio():
    """Simulate GPIO functionality for testing."""
    global gpio_initialized
    gpio_initialized = True
    print("Simulated GPIO initialized.")

def init_gpio():
    """Initialize GPIO with error handling."""
    global gpio_initialized
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GPIO_PIN_LIGHTS, GPIO.OUT, initial=GPIO.LOW)
        gpio_initialized = True
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"GPIO initialization failed: {e}")
        simulate_gpio()
        return False
    return True

def cleanup_gpio():
    """Clean up GPIO resources."""
    global gpio_initialized
    if gpio_initialized:
        try:
            GPIO.cleanup()
            print("GPIO cleaned up.")
        except Exception as e:
            print(f"GPIO cleanup error: {e}")
        gpio_initialized = False

def init_camera():
    """Initialize PiCamera2 with error handling."""
    global camera
    try:
        camera = Picamera2()
        config = camera.create_still_configuration(main={"size": CAMERA_RESOLUTION})
        camera.configure(config)
        camera.start()
        print("Camera initialized successfully.")
        return True
    except Exception as e:
        print(f"Camera initialization failed: {e}")
        camera = None
        return False

def cleanup_camera():
    """Clean up camera resources."""
    global camera
    if camera:
        try:
            camera.stop()
            camera.close()
            print("Camera resources released.")
        except Exception as e:
            print(f"Camera cleanup error: {e}")
        camera = None

def init_dht():
    """Initialize DHT11 sensor with error handling."""
    global dht_device
    try:
        dht_device = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
        print("DHT11 sensor initialized.")
        return True
    except Exception as e:
        print(f"DHT11 initialization failed: {e}")
        dht_device = None
        return False

def cleanup_dht():
    """Clean up DHT11 sensor resources."""
    global dht_device
    if dht_device:
        try:
            dht_device.exit()
            print("DHT11 sensor resources released.")
        except Exception as e:
            print(f"DHT11 cleanup error: {e}")
        dht_device = None

def read_temperature():
    """Read temperature from DHT11 sensor with fallback to simulation."""
    global dht_device
    if dht_device:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                return temperature
            else:
                print("DHT11 returned None temperature.")
        except RuntimeError as e:
            print(f"DHT11 read error (checksum/timeout): {e}")
        except Exception as e:
            print(f"DHT11 unexpected error: {e}")
    # Fallback to simulation
    return round(random.uniform(15, 35), 1)

def turn_lights_on():
    """Turn lights on using GPIO or simulation."""
    if gpio_initialized:
        GPIO.output(GPIO_PIN_LIGHTS, GPIO.HIGH)
        print("Lights turned on.")
    else:
        print("Lights turned on (simulated).")

def turn_lights_off():
    """Turn lights off using GPIO or simulation."""
    if gpio_initialized:
        GPIO.output(GPIO_PIN_LIGHTS, GPIO.LOW)
        print("Lights turned off.")
    else:
        print("Lights turned off (simulated).")

def take_picture():
    """Capture an image using PiCamera2."""
    if camera:
        try:
            timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"greenhouse_{timestamp}.jpg"
            camera.capture(filename)
            print(f"Picture saved as {filename}")
        except Exception as e:
            print(f"Camera capture error: {e}")
    else:
        print("Camera unavailable, cannot take picture.")

def listen_for_command():
    """Listen for voice command with wake word detection."""
    r = sr.Recognizer()
    try:
        with sr.Microphone() as source:
            print("Listening for command...")
            r.adjust_for_ambient_noise(source, duration=0.5)
            audio = r.listen(source, timeout=5, phrase_time_limit=5)
    except sr.WaitTimeoutError:
        print("No speech detected within timeout.")
        return None
    except Exception as e:
        print(f"Microphone error: {e}")
        return None

    try:
        words = r.recognize_google(audio)
        print(f"You said: {words}")
        return words.lower()
    except sr.UnknownValueError:
        print("Could not understand audio.")
        return None
    except sr.RequestError as e:
        print(f"Speech recognition service error: {e}")
        return None

def process_command(command):
    """Process recognized command."""
    if not command:
        return
    parts = command.split()
    if len(parts) < 2:
        return
    if parts[0] == WAKE_WORD:
        if len(parts) == 3:
            if parts[1] == "turn on the lights":
                turn_lights_on()
            elif parts[1] == "turn off the lights":
                turn_lights_off()
            elif parts[1] == "what is the temperature":
                temperature = read_temperature()
                print(f"Temperature: {temperature}°C")
            elif parts[1] == "take a picture":
                take_picture()
            else:
                print("Unknown command.")
        else:
            print("Invalid command format.")
    else:
        print("Wake word not detected.")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not init_gpio():
        print("Falling back to simulated GPIO mode.")
        simulate_gpio()
    if not init_camera():
        print("Falling back to simulated camera mode.")
    if not init_dht():
        print("Falling back to simulated temperature sensor.")

    try:
        while running:
            command = listen_for_command()
            if command:
                process_command(command)
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        cleanup_gpio()
        cleanup_camera()
        cleanup_dht()
        print("Cleanup complete. Exiting.")

if __name__ == "__main__":
    main()

