import time
import numpy as np
from picamera2 import Picamera2
from picamera2.encoders import JpegEncoder
from picamera2.outputs import FileOutput

# Configuration
RESOLUTION = (640, 480)
FRAMERATE = 15
MOTION_THRESHOLD = 10
WARMUP_TIME = 2
CAPTURE_INTERVAL = 2

def initialize_camera():
    """Initializes the Raspberry Pi camera using picamera2."""
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": RESOLUTION, "format": "RGB888"},
            controls={"FrameRate": FRAMERATE}
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(WARMUP_TIME)  # Camera warm-up time
        return picam2
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_image(picam2):
    """Captures an image from the camera and returns it as a numpy array."""
    try:
        # capture_array returns a numpy array in RGB format
        return picam2.capture_array()
    except Exception as e:
        print(f"Error capturing image: {e}")
        return None

def calculate_average(picam2):
    """Calculates the average pixel value of the image."""
    try:
        image = capture_image(picam2)
        if image is None:
            return None
        return np.mean(image)
    except Exception as e:
        print(f"Error calculating average: {e}")
        return None

def detect_motion(picam2, baseline_average):
    """Detects motion by comparing the current average to the baseline."""
    current_average = calculate_average(picam2)
    if current_average is None:
        return False, baseline_average
    if abs(current_average - baseline_average) > MOTION_THRESHOLD:
        print("Motion detected!")
        return True, current_average
    return False, baseline_average

def save_motion_image(picam2):
    """Saves the current image as motion.jpg."""
    try:
        image = capture_image(picam2)
        if image is None:
            return
        # picamera2 uses FileOutput for saving images directly
        encoder = JpegEncoder()
        output = FileOutput("motion.jpg")
        picam2.start_encoder(encoder, output)
        picam2.capture_file("motion.jpg")
        picam2.stop_encoder()
    except Exception as e:
        print(f"Error saving motion image: {e}")

def main():
    """Main function to run the motion detection."""
    picam2 = initialize_camera()
    if picam2 is None:
        return

    try:
        baseline_average = calculate_average(picam2)
        if baseline_average is None:
            print("Failed to capture initial baseline image. Exiting.")
            return

        while True:
            motion_detected, baseline_average = detect_motion(picam2, baseline_average)
            if motion_detected:
                save_motion_image(picam2)
            time.sleep(CAPTURE_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # Ensure camera resources are released
        try:
            picam2.stop()
            picam2.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

