import os
import time
import signal
import logging
import threading
import configparser
import datetime
import numpy as np
import cv2
import smbus
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class SecurityCamera:
    def __init__(self, config_file="config.ini"):
        self.config = configparser.ConfigParser()
        self.config.read(config_file)
        self.motion_threshold = float(self.config["DEFAULT"]["motion_threshold"])
        self.motion_sensitivity = float(self.config["DEFAULT"]["motion_sensitivity"])
        self.debounce_time = float(self.config["DEFAULT"]["debounce_time"])
        self.recording_duration = int(self.config["DEFAULT"]["recording_duration"])
        self.disk_space_limit = int(self.config["DEFAULT"]["disk_space_limit"])
        self.camera_resolution = tuple(map(int, self.config["DEFAULT"]["camera_resolution"].split("x")))
        self.camera_fps = int(self.config["DEFAULT"]["camera_fps"])
        self.i2c_address = int(self.config["DEFAULT"]["i2c_address"])
        self.i2c_bus = None
        self.light_sensor_initialized = False
        self.light_sensor = None
        self.camera = None
        self.frame_buffer = []
        self.lock = threading.Lock()
        self.running = True
        self._stop_event = threading.Event()
        self._recording_thread = None
        self._light_thread = None
        self._init_gpio()
        self._init_camera()
        self._init_light_sensor()

    def _init_gpio(self):
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(17, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logger.info("GPIO 17 initialized as input with pull-down.")
        except Exception as e:
            logger.warning(f"GPIO initialization failed: {e}")

    def _init_camera(self):
        try:
            from picamera2 import Picamera2
            self.camera = Picamera2()
            config = self.camera.create_video_configuration(
                main={"size": self.camera_resolution, "format": "YUV420"},
                controls={"FrameRate": self.camera_fps}
            )
            self.camera.configure(config)
            self.camera.start()
            logger.info("Camera initialized successfully.")
        except Exception as e:
            logger.error(f"Camera initialization failed: {e}")
            raise

    def _init_light_sensor(self):
        try:
            self.i2c_bus = smbus.SMBus(1)
            self.i2c_bus.write_byte(self.i2c_address, 0x10)
            time.sleep(0.1)
            data = self.i2c_bus.read_i2c_block_data(self.i2c_address, 0x00, 2)
            lux = (data[1] + 256 * data[0]) / 1.2
            self.light_sensor_initialized = True
            logger.info(f"Light sensor initialized at address 0x{self.i2c_address:02X}.")
        except Exception as e:
            logger.warning(f"Light sensor initialization failed: {e}. Continuing without light sensor.")

    def _read_light_level(self):
        if not self.light_sensor_initialized:
            return None
        try:
            data = self.i2c_bus.read_i2c_block_data(self.i2c_address, 0x00, 2)
            lux = (data[1] + 256 * data[0]) / 1.2
            return lux
        except Exception as e:
            logger.error(f"Error reading light sensor: {e}")
            return None

    def _capture_frame(self):
        try:
            frame = self.camera.capture_array()
            if frame is None:
                return None
            return frame
        except Exception as e:
            logger.error(f"Error capturing frame: {e}")
            return None

    def _detect_motion(self, frame1, frame2):
        if frame1 is None or frame2 is None:
            return False
        try:
            diff = cv2.absdiff(frame1, frame2)
            gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
            _, thresh = cv2.threshold(gray, 25, 255, cv2.THRESH_BINARY)
            thresh = cv2.dilate(thresh, None, iterations=2)
            contours, _ = cv2.findContours(thresh, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
            changed_pixels = float(np.count_nonzero(thresh))
            total_pixels = frame1.shape[0] * frame1.shape[1]
            motion_percentage = (changed_pixels / total_pixels) * 100
            return motion_percentage > self.motion_sensitivity and (cv2.countourArea(max(contours, key=cv2.contourArea)) > self.motion_threshold)
        except Exception as e:
            logger.error(f"Error detecting motion: {e}")
            return False

    def _save_recording(self, filename):
        try:
            os.makedirs(os.path.dirname(filename), exist_ok=True)
            fourcc = cv2.VideoWriter_fourcc(*'avc1')
            out = cv2.VideoWriter(filename, fourcc, 24.0, (640, 480))
            start_time = time.time()
            while self._stop_event.is_set() == False:
                frame = self._capture_frame()
                if frame is None:
                    break
                with self.lock:
                    self.frame_buffer.append(frame)
                if len(self.frame_buffer) > 72:
                    self.frame_buffer.pop(0)
                if len(self.frame_buffer) == 0:
                    logger.warning("Frame buffer is empty. Cannot prepend frames for recording.")
                    break
                pre_frames = self.frame_buffer[-72:]
                all_frames = list(pre_frames) + [frame]
                all_frames = np.array(all_frames, dtype=np.uint8)
                _, jpeg = cv2.imencode('.jpg', all_frames)
                _, jpeg2 = cv2.imencode('.jpg', all_frames)
                out.write(jpeg2.tobytes())
                out.write(jpeg.tobytes())
                elapsed = time.time() - start_time
                if elapsed >= self.recording_duration:
                    break
                time.sleep(1.0 / 24.0)
            out.release()
            logger.info(f"Recording saved: {filename}")
        except Exception as e:
            logger.error(f"Error saving recording: {e}")

    def _manage_disk_space(self):
        try:
            total_size = sum(os.path.getsize(f) for f in os.listdir(self.disk_space_limit_mb_path) if os.path.isfile(os.path.join(self.disk_space_limit_mb_path, f)))
            if total_size > self.disk_space_limit * 1024 * 1024:
                logger.warning(f"Disk space limit reached: {total_size / 1024 / 1024:.1f} MB. Deleting oldest files.")
                files_to_delete = []
                for filename in os.listdir(self.disk_space_limit_mb_path):
                    file_path = os.path.join(self.disk_space_limit_mb_path, filename)
                    try:
                        if os.path.isfile(file_path):
                            size = os.path.getsize(file_path)
                            age = os.path.getmtime(file_path)
                            files_to_delete.append((filename, size, age))
                    except Exception:
                        pass
                files_to_delete.sort(key=lambda x: x[1], reverse=True)
                for filename, size, age in files_to_delete:
                    try:
                        os.remove(file_path)
                        logger.info(f"Deleted old file: {filename}")
                    except Exception as e:
                        logger.error(f"Error deleting file {filename}: {e}")
        except Exception as e:
            logger.error(f"Error managing disk space: {e}")

    def _light_monitoring_loop(self):
        while self.running:
            light_level = self._read_light_level()
            if light_level is not None:
                logger.info(f"Light level: {light_level:.2f} lux")
            self._stop_event.wait(5)

    def _recording_loop(self):
        while self.running:
            frame1 = self._capture_frame()
            if frame1 is None:
                continue
            time.sleep(self.debounce_time)
            frame2 = self._capture_frame()
            if frame2 is None:
                continue
            if self._detect_motion(frame1, frame2):
                timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
                filename = f"camera1_{timestamp}.h264"
                self._save_recording(filename)
                self._manage_disk_space()
                logger.info("Motion detected and recording triggered.")
            time.sleep(0.1)

    def run(self):
        self._recording_thread = threading.Thread(target=self._recording_loop, daemon=True)
        self._light_thread = threading.Thread(target=self._light_monitoring_loop, daemon=True)
        self._recording_thread.start()
        self._light_thread.start()
        try:
            while self.running:
                time.sleep(1)
        except KeyboardInterrupt:
            logger.info("Shutting down...")
        finally:
            self.stop()

    def stop(self):
        self.running = False
        self._stop_event.set()
        if self._recording_thread and self._recording_thread.is_alive():
            self._recording_thread.join(timeout=2)
        if self._light_thread and self._light_thread.is_alive():
            self._light_thread.join(timeout=2)
        if self.camera:
            try:
                self.camera.stop()
            except Exception:
                pass
        if self.i2c_bus:
            try:
                self.i2c_bus.close()
            except Exception:
                pass
        try:
            GPIO.cleanup()
        except Exception:
            pass
        logger.info("Security camera system stopped.")

def signal_handler(signum, frame, camera):
    logger.info(f"Signal {signum} received, shutting down...")
    camera.stop()

if __name__ == "__main__":
    camera = SecurityCamera()
    signal.signal(signal.SIGINT, lambda s, f: signal_handler(s, f, camera))
    signal.signal(signal.SIGTERM, lambda s, f: signal_handler(s, f, camera))
    camera.run()

