logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

CAMERA_RESOLUTION = (320, 240)
CAMERA_FRAMERATE = 10
ROI = slice(10, 150, 40, 280)
OUTPUT_WINDOW_NAME = "Output Image"
GPIO_PIN = 17

running = True

def signal_handler(signum, frame):
    global running
    logging.info(f"Signal {signum} received, shutting down...")
    running = False

def initialize_camera():
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": CAMERA_RESOLUTION, "format": "BGR888"},
            controls={"FrameRate": CAMERA_FRAMERATE}
        )
        picam2.configure(config)
        picam2.start()
        logging.info("Camera initialized successfully.")
        return picam2
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return None

def initialize_gpio():
    try:
        led = LED(GPIO_PIN)
        led.on()
        logging.info(f"GPIO pin {GPIO_PIN} initialized as output, HIGH.")
        return led
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return None

def process_frame(frame):
    try:
        if frame is None:
            return None
        return frame[ROI]
    except Exception as e:
        logging.error(f"Frame processing failed: {e}")
        return None

def display_frame(frame):
    try:
        cv2.imshow(OUTPUT_WINDOW_NAME, frame)
    except Exception as e:
        logging.error(f"Display failed: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

