import cv2
import time
import signal
import sys
import config
import face
import hardware

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)

    box = hardware.Box()
    box.lock()

    recognizer = cv2.face.EigenFaceRecognizer_create()
    try:
        recognizer.read(config.TRAINING_FILE)
    except cv2.error as exc:
        print(f"Error loading training data: {exc}", file=sys.stderr)
        return

    cascade = cv2.CascadeClassifier(config.CASCADE_FILE)
    if cascade.empty():
        print(f"Error: could not load cascade classifier from {config.CASCADE_FILE}", file=sys.stderr)
        return

    try:
        from picamera2 import Picamera2
    except ImportError:
        print("picamera2 is not installed. Install with: pip install picamera2", file=sys.stderr)
        return

    picam2 = Picamera2()
    try:
        picam2.configure(picam2.create_preview_configuration(
            main={"format": 'XRGB8888', "size": (640, 480)}
        ))
        picam2.start()
    except Exception as exc:
        print(f"Error initializing camera: {exc}", file=sys.stderr)
        return

    try:
        while _running:
            try:
                frame = picam2.capture_array()
            except Exception as exc:
                print(f"Error capturing frame: {exc}", file=sys.stderr)
                time.sleep(0.1)
                continue

            if frame is None:
                time.sleep(0.1)
                continue

            try:
                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
            except cv2.error as exc:
                print(f"Error converting frame to grayscale: {exc}", file=sys.stderr)
                time.sleep(0.1)
                continue

            try:
                faces = cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
            except cv2.error as exc:
                print(f"Error during face detection: {exc}", file=sys.stderr)
                time.sleep(0.1)
                continue

            if len(faces) == 0:
                time.sleep(0.1)
                continue

            x, y, w, h = faces[0]
            crop = gray[y:y + h, x:x + w]
            if crop.size == 0:
                time.sleep(0.1)
                continue

            try:
                resized = cv2.resize(crop, (100, 100))
            except cv2.error as exc:
                print(f"Error resizing face: {exc}", file=sys.stderr)
                time.sleep(0.1)
                continue

            try:
                label, confidence = recognizer.predict(resized)
            except cv2.error as exc:
                print(f"Error during recognition: {exc}", file=sys.stderr)
                time.sleep(0.1)
                continue

            if label == config.POSITIVE_LABEL and config.POSITIVE_THRESHOLD > confidence > 1500:
                box.unlock()
            elif not box.is_locked:
                box.lock()

            if box.is_button_up():
                time.sleep(0.1)
            else:
                time.sleep(0.1)

    finally:
        try:
            box.lock()
        except Exception:
            pass
        try:
            picam2.stop()
        except Exception:
            pass
        print("Exiting...")

if __name__ == "__main__":
    main()

