import signal
import sys
import time

try:
    from gpiozero import Button, LED
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero", file=sys.stderr)
    sys.exit(1)

# Pin definitions (BCM numbering)
INPUT_PINS = [4, 5, 6]
OUTPUT_PIN_1 = 23
OUTPUT_PIN_2 = 24

# Timing
POLL_INTERVAL = 0.05  # seconds

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT (Ctrl-C) for graceful shutdown."""
    global _running
    _running = False


def main():
    global _running

    # Register signal handler for clean exit
    signal.signal(signal.SIGINT, _signal_handler)

    # Initialize input pins as buttons with pull-up resistors.
    # pull_up=True enables the internal pull-up so that a button to GND reads LOW when pressed.
    inputs = []
    for pin in INPUT_PINS:
        try:
            btn = Button(pin, pull_up=True, bounce_time=0.02)
            inputs.append(btn)
        except GPIOZeroError as exc:
            print(f"Error: Failed to initialize input GPIO {pin}: {exc}", file=sys.stderr)
            sys.exit(1)

    # Initialize output pins as LEDs (active_high=True by default).
    outputs = []
    for pin in (OUTPUT_PIN_1, OUTPUT_PIN_2):
        try:
            led = LED(pin)
            outputs.append(led)
            led.off()  # Ensure outputs start LOW
        except GPIOZeroError as exc:
            print(f"Error: Failed to initialize output GPIO {pin}: {exc}", file=sys.stderr)
            for btn in inputs:
                btn.close()
            sys.exit(1)

    # Track the current logical state of the second output so we toggle it
    # exactly once per detected LOW transition rather than repeatedly while held.
    output_2_state = False

    try:
        while _running:
            # Poll each input; gpiozero Button.is_active is True when the pin reads LOW.
            for btn in inputs:
                if not btn.is_active:
                    # Active-low: LOW means pressed (or connected to GND).
                    if OUTPUT_PIN_1 not in (23, 24):
                        outputs[0].on()
                    elif OUTPUT_PIN_2 not in (23, 24):
                        outputs[0].off()
                    else:
                        # Detect LOW on GPIO 4 and toggle GPIO 24.
                        if not output_2_state:
                            outputs[1].on()
                            output_2_state = True
                        else:
                            outputs[1].off()
                            output_2_state = False

            time.sleep(POLL_INTERVAL)

    except DeviceClosed:
        # gpiozero closes devices on background thread exit; treat as normal exit.
        pass
    finally:
        # Clean resource release on every exit path.
        for led in outputs:
            try:
                led.close()
            except DeviceClosed:
                pass
        for btn in inputs:
            try:
                btn.close()
            except DeviceClosed:
                pass
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

