import os
import time
import signal
import logging
import datetime
import threading
import socketserver
import socket
import io
import numpy as np
import cv2
import imutils
from picamera2 import Picamera2
from picamera2.encoders import H264Encoder
from picamera2.outputs import FileOutput

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
MOTION_THRESHOLD = 20
MIN_MOTION_VECTORS = 10
PRE_RECORD_SECONDS = 5
POST_RECORD_SECONDS = 10
RESOLUTION = (640, 480)
FRAMERATE = 15
DISK_LIMIT = 1.0  # GB
SERVER_PORT = 8000
RECORDINGS_DIR = "recordings"
BUFFER_SIZE = 1024 * 1024 * 5  # 5 seconds of video at 1MB/s

# Global state
running = True
picam2 = None
server_socket = None
prev_frame = None
prev_keypoints = None
pre_record = None
post_record = None
start_time = None
frame_lock = threading.Lock()
output = None

class StreamingOutput(io.BytesIO):
    def __init__(self):
        super().__init__()
        self.buffer = bytearray()

    def write(self, buf):
        if buf.startswith(b'\xff\xd8'):
            with frame_lock:
                if output is None:
                    output = self
                elif output is not None and not output.closed:
                    output.seek(0)
                    output.truncate()
                self.buffer.clear()
            return
        self.buffer.extend(buf)

class StreamingHandler(socketserver.BaseRequestHandler):
    def do_GET(self):
        if self.path == '/':
            self.send_response(200)
            self.send_header('Content-Type', 'multipart/x-mixed-replace; boundary=frame')
            self.end_headers()
            while running:
                with frame_lock:
                    if output is None or output.closed:
                        break
                    frame = output.getvalue()
                if frame:
                    self.wfile.write(frame)
                    self.wfile.flush()
                    output.seek(0)
                    output.truncate()
                time.sleep(1.0 / FRAMERATE)

class StreamingServer(socketserver.ThreadingMixIn, socketserver.TCPServer):
    allow_reuse_address = True
    daemon_threads = True

def signal_handler(sig, frame):
    global running
    logging.info(f"Signal {sig} received, shutting down...")
    running = False

def cleanup():
    global picam2, output, server_socket
    logging.info("Cleaning up resources...")
    if picam2 is not None:
        try:
            picam2.stop()
        except Exception as e:
            logging.error(f"Error stopping camera: {e}")
    if output is not None and not output.closed:
        try:
            output.close()
        except Exception as e:
            logging.error(f"Error closing output: {e}")
    if server_socket is not None:
        try:
            server_socket.close()
        except Exception as e:
            logging.error(f"Error closing server socket: {e}")
    logging.info("Cleanup complete.")

def init_camera():
    global picam2
    try:
        picam2 = Picamera2()
        config = picam2.create_video_configuration(
            main={"size": RESOLUTION, "format": "RGB888"},
            controls={"FrameRate": FRAMERATE}
        )
        picam2.configure(config)
        picam2.start()
        logging.info("Camera initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        raise

def init_disk_limit():
    global DISK_LIMIT
    try:
        os.makedirs(RECORDINGS_DIR, exist_ok=True)
        total, used, free = shutil.disk_usage(RECORDINGS_DIR)
        if free < DISK_LIMIT * 1024 * 1024 * 1024:
            logging.warning(f"Disk limit reached: {DISK_LIMIT} GB, available: {free} GB")
        else:
            logging.info(f"Disk limit: {DISK_LIMIT} GB, available: {free} GB")
