import cv2
import pyzbar.pyzbar as pyzbar
import time
import datetime
import threading
import queue
import configparser
import os
import logging
import signal
import sys

# Configuration file path
CONFIG_FILE = 'config.ini'

# Default configuration values
DEFAULT_CONFIG = {
    'DEFAULT': {
        'motion_threshold': '10',
        'redundancy_time_window': '5.0',
        'cloud_upload_interval': '60',
        'frame_buffer_size': '10',
        'reinit_delay': '2.0',
        'watchdog_timeout': '30'
    }
}

# Global variables
config = configparser.ConfigParser()
inventory = []
last_scan_time = {}
last_cloud_upload_time = 0
running = True
camera1 = None
camera2 = None
frame_buffer1 = queue.Queue(maxsize=config.getint('DEFAULT', 'frame_buffer_size'))
frame_buffer2 = queue.Queue(maxsize=config.getint('DEFAULT', 'frame_buffer_size'))
camera1_lock = threading.Lock()
camera2_lock = threading.Lock()
camera1_thread = None
camera2_thread = None
camera1_event = threading.Event()
camera2_event = threading.Event()

# Logging setup
logging.basicConfig(
    filename='inventory.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
backup_logger = logging.FileHandler('backup_inventory.log')
backup_logger.setFormatter(logging.Formatter('%(asctime)s - %(levelname)s - %(message)s'))
backup_logger.setLevel(logging.INFO)
logging.getLogger().addHandler(backup_logger)

def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False

def load_config():
    global config
    config.read(CONFIG_FILE)
    for section, key, value in DEFAULT_CONFIG.items():
        if section not in config:
            config[section] = {}
        config[section][key] = value

def initialize_camera(camera_id):
    try:
        cap = cv2.VideoCapture(camera_id)
        if not cap.isOpened():
            logging.error(f"Failed to open camera {camera_id}")
            return None
        return cap
    except Exception as e:
        logging.error(f"Error initializing camera {camera_id}: {e}")
        return None

def read_frame(camera):
    try:
        ret, frame = camera.read()
        if not ret or frame is None:
            logging.error(f"Failed to read frame from camera {camera}")
            return None
        return frame
    except Exception as e:
        logging.error(f"Error reading frame from camera {camera}: {e}")
        return None

def decode_qr_code(frame):
    try:
        decoded_objects = pyzbar.decode(frame)
        for obj in decoded_objects:
            return obj.data.decode('utf-8')
        return None
    except Exception as e:
        logging.error(f"Error decoding QR code: {e}")
        return None

def detect_motion(frame1, frame2, threshold):
    try:
        gray1 = cv2.cvtColor(frame1, cv2.COLOR_BGR2GRAY)
        gray2 = cv2.cvtColor(frame2, cv2.COLOR_BGR2GRAY)
        if frame1 is None or frame2 is None:
            return False
        diff = cv2.absdiff(gray1, gray2)
        _, thresh = cv2.threshold(diff, threshold, 255, cv2.THRESH_BINARY)
        return cv2.countNonZero(thresh) > 0
    except Exception as e:
        logging.error(f"Error detecting motion: {e}")
        return False

def process_frame(camera_id, frame, frame_buffer, last_frame, last_motion):
    global last_scan_time, last_cloud_upload_time
    try:
        if frame is None:
            return
        if frame not in frame_buffer:
            frame_buffer[frame] = []
        frame_buffer[frame].append(frame)
        if len(frame_buffer[frame]) > 2:
            frame_buffer[frame].pop(0)

        if last_frame is None or last_motion is None:
            last_frame = frame.copy()
            last_motion = detect_motion(last_frame, frame, config.getint('DEFAULT', 'motion_threshold'))
        else:
            last_motion = detect_motion(last_frame, frame, config.getint('DEFAULT', 'motion_threshold'))

        if last_motion and not any(t >= time.time() for t in last_scan_time.values()):
            now = time.time()
            if now - last_scan_time[camera_id] > config.getfloat('DEFAULT', 'redundancy_time_window'):
                data = decode_qr_code(frame)
                if data:
                    last_scan_time[camera_id] = now
                    logging.info(f"QR Code detected on camera {camera_id}: {data}")
                    print(f"QR Code detected on camera {camera_id}: {data}")
                    try:
                        with open('inventory.log', 'a') as f:
                            f.write(f"QR Code detected on camera {camera_id}: {data}\n")
                        print("QR Code data logged to inventory.log")
                    except Exception as e:
                        logging.error(f"Error writing to inventory.log: {e}")
                        try:
                            with open('backup_inventory.log', 'a') as f:
                                f.write(f"QR Code detected on camera {camera_id}: {data}\n")
                            print("QR Code data logged to backup_inventory.log")
                        except Exception as e2:
                            logging.error(f"Error writing to backup_inventory.log: {e2}")
                    last_cloud_upload_time = now
        elif now - last_scan_time[camera_id] > config.getfloat('DEFAULT', 'watchdog_timeout'):
            logging.warning(f"No QR code detected for {camera_id} in the last {config.getfloat('DEFAULT', 'watchdog_timeout')} seconds. Restarting...")
            os.execv(sys.executable, [sys.executable] + sys.argv)

def camera_thread(camera_id, frame_buffer, last_frame, last_motion):
    global running
    while running:
        try:
            frame = read_frame(camera_id)
            if frame is not None:
                process_frame(camera_id, frame, frame_buffer, last_frame, last_motion)
                camera2_event.wait()
            else:
                camera2_event.wait(timeout=1)
        except Exception as e:
            logging.error(f"Error in camera thread for {camera_id}: {e}")
            camera2_event.wait(timeout=1)

def camera1_thread_func():
    global camera1, camera1_thread
    camera1_thread = threading.Thread(target=camera_thread, args=(0, frame_buffer1, None, None), daemon=True)
    camera1_thread.start()

def camera2_thread_func():
    global camera2, camera2_thread
    camera2_thread = threading.Thread(target=camera_thread, args=(2, frame_buffer2, None, None), daemon=True)
    camera2_thread.start()

def simulate_cloud_upload():
    global last_cloud_upload_time
    now = time.time()
    if now - last_cloud_upload_time > config.getint('DEFAULT', 'cloud_upload_interval'):
        try:
            with open('inventory.log', 'r') as f:
                lines = f.readlines()
            print("Simulating cloud upload...")
            for line in lines:
