import io
import os
import time
import signal
import threading
import zmq
from gps3 import gps3
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import Output

DEFAULT_GPS_LAT = "22.483425"
DEFAULT_GPS_LON = "88.455463"
GPS_RESTART_COMMAND = "sudo systemctl restart gpsd"

shutdown_event = threading.Event()
gps_lock = threading.Lock()
gps_lat = DEFAULT_GPS_LAT
gps_lon = DEFAULT_GPS_LON
gps_mag = 0.0
gps_alt = 0.0
gps_fix = False
gps_socket = None
camera = None
zmq_socket = None


def restart_gpsd():
    """Attempt to restart gpsd; log and return False on failure."""
    try:
        ret = os.system(GPS_RESTART_COMMAND)
        if ret != 0:
            print(f"Warning: {GPS_RESTART_COMMAND} exited with status {ret}")
            return False
        print("gpsd restarted successfully.")
        return True
    except Exception as e:
        print(f"Error restarting gpsd: {e}")
        return False


def get_gps_data():
    """Poll gpsd for TPV data; return (lat, lon) or None on failure."""
    global gps_lat, gps_lon, gps_mag, gps_alt, gps_fix

    if gps_socket is None:
        return None

    try:
        data = gps_socket.next()
    except StopIteration:
        return None
    except Exception as e:
        print(f"Error reading from gpsd: {e}")
        return None

    if not data.get('class') or data['class'] != 'TPV':
        return None

    lat = data.get('lat')
    lon = data.get('lon')
    if lat is None or lon is None:
        return None

    try:
        gps_lat = float(lat)
        gps_lon = float(lon)
        gps_fix = True
    except ValueError:
        print("Warning: Invalid GPS data received (non-numeric).")
        gps_fix = False

    return (gps_lat, gps_lon)


def send_frame_with_metadata(socket, frame_data, metadata):
    """Send a two-part message: metadata string + frame bytes."""
    try:
        socket.send_string(metadata, zmq.SNDMORE)
        socket.send(frame_data)
    except zmq.ZMQError as e:
        print(f"ZMQError sending frame: {e}")
    except Exception as e:
        print(f"Unexpected error sending frame: {e}")


def camera_thread():
    """Capture MJPEG frames and publish them with GPS metadata."""
    global camera, zmq_socket

    try:
        camera = Picamera2()
        config = camera.create_video_configuration(
            main={"size": (640, 480), "format": "MJPEG"},
            controls={"FrameRate": 100}
        )
        camera.configure(config)
        camera.set_controls({"Rotation": 180})
        camera.start()
        print("Camera started successfully.")
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return

    try:
        zmq_socket = zmq.PUB('tcp://192.168.1.4:5555', lingers=0)
        print("ZMQ PUB socket connected to 192.168.1.4:5555.")
    except zmq.ZMQError as e:
        print(f"ZMQError creating socket: {e}")
        return

    try:
        while not shutdown_event.is_set():
            try:
                frame = camera.capture_array()
            except Exception as e:
                print(f"Error capturing frame: {e}")
                time.sleep(0.1)
                continue

            if frame is None:
                continue

            try:
                metadata = f"{gps_lat},{gps_lon},{gps_mag},{gps_alt}"
            except Exception as e:
                print(f"Error generating metadata: {e}")
                continue

            try:
                send_frame_with_metadata(zmq_socket, frame, metadata)
            except zmq.ZMQError:
                continue

    except KeyboardInterrupt:
        print("Camera thread stopped by user.")
    finally:
        try:
            zmq_socket.close()
        except Exception:
            pass
        try:
            camera.stop()
            camera.close()
        except Exception:
            pass
        print("Camera resources released.")


def gps_thread():
    """Poll gpsd for TPV data and update shared variables."""
    global gps_lat, gps_lon, gps_mag, gps_alt, gps_fix

    while not shutdown_event.is_set():
        gps_data = get_gps_data()
        if gps_data is not None:
            lat, lon = gps_data
            try:
                gps_mag = float(gps_socket.TPV['mag'])
                gps_alt = float(gps_socket.TPV['alt'])
            except Exception:
                gps_mag = 0.0
                gps_alt = 0.0

        shutdown_event.wait(0.5)

    print("GPS thread stopped.")


def signal_handler(signum, frame):
    print(f"Signal {signum} received, shutting down...")
    shutdown_event.set()


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not restart_gpsd():
        print("Warning: gpsd unavailable; using default coordinates.")

    gps_thread_target = threading.Thread(target=gps_thread, daemon=True)
    camera_thread_target = threading.Thread(target=camera_thread, daemon=True)

    gps_thread_target.start()
    camera_thread_target.start()

    try:
        while not shutdown_event.is_set():
            shutdown_event.wait(1.0)
    except KeyboardInterrupt:
        print("KeyboardInterrupt received.")
    finally:
        shutdown_event.set()
        gps_thread_target.join(timeout=2.0)
        camera_thread_target.join(timeout=2.0)
        if gps_socket:
            try:
                gps_socket.close()
            except Exception:
                pass
        print("Program finished.")


if __name__ == "__main__":
    main()

