import asyncio
import logging
import signal
import threading
from typing import Callable, Optional

import cv2
import numpy as np

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

try:
    from picamera2 import Picamera2
except ImportError:
    logger.error("picamera2 library is not installed. Install with: pip install picamera2")
    raise


class WebSocketHandler:
    """Manages WebSocket connections and broadcasts JPEG frames to connected clients."""

    def __init__(self):
        self.connections: set = set()
        self._lock = threading.Lock()
        self._stop_event = threading.Event()

    def has_connections(self) -> bool:
        with self._lock:
            return bool(self.connections)

    def broadcast(self, data: bytes) -> None:
        """Broadcasts data to all connected WebSocket clients."""
        with self._lock:
            if not self.connections:
                return
            for connection in self.connections:
                try:
                    connection.send(data)
                except Exception as e:
                    logger.warning("Error sending data to WebSocket connection: %s", e)

    def close(self) -> None:
        """Closes all WebSocket connections."""
        self._stop_event.set()
        for connection in list(self.connections):
            try:
                connection.close()
            except Exception as e:
                logger.warning("Error closing WebSocket connection: %s", e)
        self.connections.clear()


def _make_camera_loop(camera: Picamera2, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]) -> asyncio.AbstractEventLoop:
    """Creates and returns an asyncio event loop bound to the camera thread."""
    loop = asyncio.new_event_loop()
    asyncio.set_event_loop(loop)
    return loop


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    logger.info("Received signal %s, shutting down...", signum)
    raise SystemExit(0)


def _init_camera(resolution: tuple[int, int] = (640, 480), framerate: int = 10) -> Picamera2:
    """Initializes the Picamera2 with the specified resolution and framerate."""
    try:
        camera = Picamera2()
        config = camera.create_video_configuration(
            main={"size": resolution, "format": "RGB888"},
            lores={"size": resolution, "format": "YUV420"},
        )
        camera.configure(config)
        camera.start()
        camera.set_controls({"FrameRate": framerate})
        logger.info("Camera initialized at %s @ %d fps", resolution, framerate)
        return camera
    except Exception as e:
        logger.error("Failed to initialize camera: %s", e)
        raise


def _decode_frame(data: bytes) -> Optional[np.ndarray]:
    """Decodes JPEG bytes into an OpenCV frame.

    Returns None if the data is empty, invalid, or the decoder fails.
    """
    try:
        if not data:
            return None
        if len(data) < 2:
            return None
        if data[0] != 0xFF or data[1] != 0xD8:
            return None
        frame = cv2.imdecode(np.frombuffer(data, np.uint8), cv2.IMREAD_COLOR)
        if frame is None:
            return None
        return frame
    except Exception as e:
        logger.error("Error decoding frame: %s", e)
        return None


def _detect_motion(prev_frame: Optional[np.ndarray], curr_frame: Optional[np.ndarray], detect_motion_function: Callable[[np.ndarray, np.ndarray], None]) -> None:
    """Detects motion between consecutive frames and invokes the provided callback."""
    if prev_frame is None or curr_frame is None:
        return
    try:
        detect_motion_function(prev_frame, curr_frame)
    except Exception as e:
        logger.error("Error in motion detection callback: %s", e)


def _process_frame(camera: Picamera2, detect_motion_function: Callable[[np.ndarray, np.ndarray], None], loop: asyncio.AbstractEventLoop) -> None:
    """Processes frames from the camera, decodes them, and detects motion."""
    buffer = bytearray()
    while not camera._stop_event.is_set():
        try:
            frame = camera.capture_array("lores")
            if frame is None:
                logger.warning("Captured frame is None, skipping...")
                continue
            buffer = buffer + frame.tobytes()
            if len(buffer) >= 2 and buffer[0] == 0xFF and buffer[1] == 0xD8:
                frame_data = buffer[: len(buffer) - 2]
                buffer = buffer[len(frame_data):]
                frame = _decode_frame(frame_data)
                if frame is not None:
                    prev_frame = curr_frame
                    curr_frame = frame
                    _detect_motion(prev_frame, curr_frame, detect_motion_function)
            buffer = buffer[:camera._lores_size]
        except Exception as e:
            logger.error("Error processing frame: %s", e)
            break


def _run_camera(camera: Picamera2, detect_motion_function: Callable[[np.ndarray, np.ndarray], None], loop: asyncio.AbstractEventLoop) -> None:
    """Runs the camera in a separate thread, processing frames and broadcasting JPEG frames to connected WebSocket clients."""
    def broadcast_jpeg():
        while not camera._stop_event.is_set():
            try:
                frame = camera.capture_array("lores")
                if frame is None:
                    continue
                buffer = bytearray()
                for _ in range(100):
                    try:
                        chunk = camera.capture_array("lores")
                        if chunk is None:
                            break
                        buffer += chunk.tobytes()
                        if len(buffer) >= 2 and buffer[0] == 0xFF and buffer[1] == 0xD8:
                            break
                    except Exception as e:
                        logger.error("Error capturing chunk: %s", e)
                        break
                if len(buffer) >= 2 and buffer[0] == 0xFF and buffer[1] == 0xD8:
                    frame_data = buffer[: len(buffer) - 2]
                    buffer = buffer[len(frame_data):]
                    frame = _decode_frame(frame_data)
                    if frame is not None:
                        prev_frame = curr_frame
                        curr_frame = frame
                        _detect_motion(prev_frame, curr_frame, detect_motion_function)
                        if WebSocketHandler().has_connections():
                            WebSocketHandler().broadcast_jpeg(frame)
            except Exception as e:
                logger.error("Error in broadcast_jpeg loop: %s", e)
                break

    thread = threading.Thread(target=broadcast_jpeg, daemon=True)
    thread.start()
    try:
        _process_frame(camera, detect_motion_function, loop)
    except asyncio.CancelledError:
        logger.info("Camera thread cancelled.")
    except Exception as e:
        logger.error("Error in camera thread: %s", e)
    finally:
        thread.join(timeout=5)
        if camera:
            try:
                camera.stop()
            except Exception as e:
                logger.error("Error stopping camera: %s", e)


async def run_camera(camera: Picamera2, detect_motion_function: Callable[[np.ndarray, np.ndarray], None]) -> None:
    """Runs the camera and WebSocket broadcasting in an asyncio event loop."""
    loop = _make_camera_loop(camera, detect_motion_function)
    try:
        await loop.run_forever()
    except asyncio.CancelledError:
        logger.info("Camera loop cancelled.")
    finally:
        loop.close()


def main():
    """Entry point: initialize camera, register signal handlers, and run."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    camera = None
    try:
        camera = _init_camera()
        detect_motion_function = lambda prev_frame: None, curr_frame: None
        await run_camera(camera, detect_motion_function)
    except SystemExit:
        pass
    except Exception as e:
        logger.error("Fatal error: %s", e)
    finally:
        if camera is not None:
            try:
                camera.stop()
            except Exception as e:
                logger.error("Error stopping camera: %s", e)
        logger.info("Shutdown complete.")


if __name__ == "__main__":
    main()

