import argparse
import json
import logging
import logging.handlers
import os
import signal
import sys
import threading
import time
from collections import deque

import numpy as np
import matplotlib.pyplot as plt
from smbus2 import SMBus
from picamera2 import Picamera2

try:
    import adafruit_amg88xx
except ImportError:
    adafruit_amg88xx = None

DEFAULT_CONFIG = {
    "sampling_rate": 5,
    "motion_detection_threshold": 1.0,
    "logging_file_path": "beehive.log",
    "log_max_size": 1048576,
    "enable_camera": False,
}

running = True
bus = None
camera = None
log_handler = None


def signal_handler(signum, frame):
    global running
    running = False


def load_config(config_file):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logging.warning(f"Config file not found: {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logging.error(f"Invalid JSON in config file: {config_file}: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()


def setup_logging(log_file_path):
    global log_handler
    log_handler = logging.handlers.RotatingFileHandler(
        log_file_path, maxBytes=log_handler.log_max_size, backupCount=1
    )
    log_handler.setFormatter(logging.Formatter("%(asctime)s - %(levelname)s - %(message)s"))
    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s - %(levelname)s - %(message)s",
        handlers=[log_handler],
    )


def init_camera():
    global camera
    try:
        camera = Picamera2()
        camera.configure(camera.create_still_configuration())
        camera.start()
        logging.info("Camera initialized successfully.")
        return True
    except Exception as e:
        logging.warning(f"Camera initialization failed: {e}. Continuing without camera.")
        return False


def init_sensor():
    global bus
    if adafruit_amg88xx is None:
        logging.error("adafruit_amg88xx library not installed. Cannot initialize sensor.")
        return False
    for attempt in range(3):
        try:
            bus = SMBus(1)
            sensor = adafruit_amg88xx.AMG88XX(bus, addr=0x69)
            logging.info("Sensor initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Sensor init attempt {attempt + 1}/3 failed: {e}")
            if attempt < 2:
                time.sleep(2)
    logging.error("Sensor initialization failed after 3 attempts.")
    return False


def read_thermal_data():
    global bus
    if bus is None:
        logging.error("I2C bus not initialized.")
        return None
    try:
        data = bus.read_i2c_block_data(0x69, 0x00, 512)
        return np.frombuffer(data, dtype=np.int16).reshape(8, 8)
    except Exception as e:
        logging.error(f"Error reading thermal data: {e}")
        return None


def detect_motion(frame1, frame2, threshold):
    if frame1 is None or frame2 is None:
        return False
    diff = np.abs(frame1.astype(np.int16) - frame2.astype(np.int16))
    mean_diff = float(np.mean(diff))
    return mean_diff > threshold


def capture_image():
    global camera
    if camera is None:
        logging.warning("Camera not available; skipping image capture.")
        return None
    try:
        array = camera.capture_array()
        return array
    except Exception as e:
        logging.error(f"Error capturing image: {e}")
        return None


