    ax.imshow(frame, cmap="jet", interpolation="nearest", vmin=20, vmax=40)
    ax.set_title("Thermal Heatmap")
    ax.colorbar(label="Temperature (°C)")
    im.savefig(ax.figure, format="png")
    ax.clear()


