    motion_threshold = config.get("motion_detection_threshold", 1.0)
    enable_camera = config.get("enable_camera", False)
    log_file_path = config.get("logging_file_path", "beehive.log")
    log_max_size = config.get("log_max_size", 1048576)

    log_file = open(log_file_path, "a")
    log_file.write(f"Timestamp: {time.strftime('%Y-%m-%d %H:%M:%S')}\n")
    log_file.flush()

    last_frame = None
    motion_detected = False
    last_motion_time = 0.0
    last_heatmap_time = 0.0
    frame_buffer = deque(maxlen=300)

    def read_loop():
        while running:
            try:
                frame = read_thermal_data()
                if frame is not None:
                    frame_buffer.append(frame)
                    if len(frame_buffer) > 300:
                        frame_buffer.popleft()
                if len(frame_buffer) > 0:
                    last_frame = frame_buffer[-1]
                    if last_frame is not None:
                        if last_frame != last_frame:
                            motion_detected = True
                            last_motion_time = time.time()
                        if time.time() - last_motion_time > 5:
                            if enable_camera and camera is not None:
                                capture_image()
                            last_heatmap_time = time.time()
                            if last_heatmap_time - time.time() > 5:
                                render_heatmap(last_frame, plt.gcf().gca(), log_file)
                            last_heatmap_time = 0
            except Exception as e:
                log_error(f"Error in read loop: {e}")
            time.sleep(1.0 / sampling_rate)

    def camera_loop():
        while running:
            try:
                if enable_camera and camera is not None:
                    array = camera.capture_array()
                    if array is not None:
                        log_event(f"Captured image: {array.shape}")
            except Exception as e:
                log_error(f"Error in camera loop: {e}")
            time.sleep(1.0)

    def log_loop():
        while running:
            try:
                log_file.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')}\n")
                log_file.flush()
                if log_file.tell() >= log_max_size:
                    log_file.close()
                    log_file = open(log_file_path, "a")
                log_event("Logging data...")
            except Exception as e:
                log_error(f"Error in log loop: {e}")
            time.sleep(5)

    threads = [
        threading.Thread(target=read_loop, daemon=True),
        threading.Thread(target=camera_loop, daemon=True),
        threading.Thread(target=log_loop, daemon=True),
    ]
    for t in threads:
        t.start()

    try:
        while running:
            time.sleep(0.5)
    except KeyboardInterrupt:
        running = False
    finally:
        log_event("Shutting down...")
        running = False
        for t in threads:
            t.join(timeout=2)
        if camera is not None:
            try:
                camera.stop()
            except Exception:
                pass
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        if log_file is not None:
            log_file.close()
        logging.info("Program finished.")


def parse_args():
    parser = argparse.ArgumentParser(description="Beehive Thermal Monitor")
    parser.add_argument("--config", default="config.json", help="Path to configuration file")
    return parser.parse_args()


if __name__ == "__main__":
    main()

