import os
import sys
import signal
import time
import mxnet as mx
from mxnet import image, nd
from mxnet.gluon.model_zoo import vision as models
from mxnet.gluon.utils import download
from picamera2 import Picamera2

IMAGE_DIR = 'images'
MODEL_NAME = 'resnet50_v2'
NUM_TOP_PREDICTIONS = 3
CAMERA_INDEX = 0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def setup_camera():
    try:
        picam2 = Picamera2(camera_num=CAMERA_INDEX)
        config = picam2.create_still_configuration(main={"size": (640, 480), "format": "RGB888"})
        picam2.configure(config)
        picam2.start()
        time.sleep(2)
        return picam2
    except Exception as e:
        print(f"Error setting up camera: {e}", file=sys.stderr)
        return None

def capture_image(picam2, image_dir):
    timestamp = time.strftime("%Y%m%d_%H%M%S")
    image_path = os.path.join(image_dir, f"{timestamp}.jpg")
    try:
        picam2.capture_file(image_path)
        if not os.path.exists(image_path) or os.path.getsize(image_path) == 0:
            raise IOError(f"Failed to capture image: {image_path}")
        return image_path
    except Exception as e:
        print(f"Error capturing image: {e}", file=sys.stderr)
        return None

def transform_image(image_path, model):
    try:
        img = image.imread(image_path)
        if img is None:
            raise ValueError(f"Could not read image at {image_path}")
        img = image.resize_short(img, 256)
        img, _ = image.center_crop(img, (224, 224))
        img = img.transpose((2, 0, 1)).expand_dims(axis=0)
        img = img.astype('float32')
        img = (img - 123.104) / 58.782
        return img
    except Exception as e:
        print(f"Error transforming image: {e}", file=sys.stderr)
        return None

def predict_image(transformed_img, model, num_predictions=3):
    try:
        prob = model(transformed_img).softmax()
        top_indices = prob.topk(k=num_predictions)[0]
        for i in top_indices:
            print(f"prob={prob[0, i]:.4f}, {top_indices[i]}")
    except Exception as e:
        print(f"Error during prediction: {e}", file=sys.stderr)

def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
    except OSError as e:
        print(f"Error creating image directory: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        picam2 = setup_camera()
        if picam2 is None:
            sys.exit(1)

        try:
            model = models.get_model(MODEL_NAME, pretrained=True)
            model.load_parameters('model.net')
            layer_names = [l.name for l in model.layers()]
            for name in layer_names:
                if 'data' in name:
                    model.data = nd.array(image.imread(image_path))
        except Exception as e:
            print(f"Error loading model: {e}", file=sys.stderr)
            sys.exit(1)

        image_path = capture_image(picam2, IMAGE_DIR)
        if image_path is None:
            sys.exit(1)

        transformed_img = transform_image(image_path, model)
        if transformed_img is None:
            sys.exit(1)

        predict_image(transformed_img, model, NUM_TOP_PREDICTIONS)

    except Exception as e:
        print(f"An unexpected error occurred: {e}", file=sys.stderr)
    finally:
        try:
            picam2.stop()
            picam2.close()
        except Exception:
            pass

if __name__ == "__main__":
    main()

