            raise TypeError("camera must be a Picamera2 instance")
        if not hasattr(websocket_handler, 'has_connections') or not callable(
                websocket_handler.has_connections
        ):
            raise TypeError("websocket_handler must expose has_connections()")
        self.camera = camera
        self.websocket_handler = websocket_handler
        self.buffer = io.BytesIO()
        self._lock = threading.Lock()
        self._stop_event = threading.Event()

    def write(self, data: bytes) -> int:
        if not data:
            return 0
        with self._lock:
            if self._stop_event.is_set():
                return 0
            try:
                self.buffer.write(data)
                return len(data)
            except Exception as e:
                logging.error(f"Error writing to buffer: {e}")
                return 0

