                    return
                try:
                    self.buffer.seek(0)
                    jpeg_bytes = self.buffer.getvalue()
                    if not jpeg_bytes:
                        return
                    frame = self.camera.capture_array()
                    if frame is None:
                        logging.warning("capture_array returned None")
                        return
                    if frame.shape[2] == 3:
                        frame = cv2.cvtColor(frame, cv2.COLOR_RGB2BGR)
                    ok, encoded = cv2.imencode('.jpg', frame)
                    if not ok:
                        logging.error("Failed to encode JPEG frame")
                        return
                    self.buffer.seek(0)
                    self.buffer.truncate()
                    self.buffer.write(jpeg_bytes)
                    self._broadcast_frame(encoded.tobytes())
                except Exception as e:
                    logging.error(f"Error processing JPEG frame: {e}")
            self.buffer.seek(0)
            self.buffer.truncate()

    def _broadcast_frame(self, frame_data: bytes) -> None:
        if not self.websocket_handler.has_connections():
            return
        try:
            self.websocket_handler.broadcast(frame_data)
        except Exception as e:
            logging.error(f"Error broadcasting frame: {e}")

