import sys
import time
import signal
import pygame.mixer
import cv2
import numpy as np
from picamera2 import Picamera2
from gpiozero import Button, OutputDevice

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
CONFIG = {
    "POSITIVE_LABEL": 2,
    "POSITIVE_THRESHOLD": 0.5,
    "TRAINING_FILE": "eigenface_train.dat",
    "SOUND_WELCOME": "welcome.wav",
    "SOUND_WAIT": "wait.wav",
    "SOUND_LATER": "later.wav",
    "DOOR_PIN": 18,
    "BUTTON_PIN": 17,
    "CAMERA_INDEX": 0,
    "CAMERA_WIDTH": 640,
    "CAMERA_HEIGHT": 480,
    "CAMERA_FRAMERATE": 30,
    "MIXER_FREQUENCY": 48000,
    "LOOP_DELAY": 0.1,
}

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_door = None
_button = None
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _door, _button
    if _door is not None:
        _door.close()
        _door = None
    if _button is not None:
        _button.close()
        _button = None
    try:
        pygame.mixer.quit()
    except Exception:
        pass


def _load_mixer():
    try:
        pygame.mixer.init(frequency=CONFIG["MIXER_FREQUENCY"])
        return True
    except pygame.error as exc:
        print(f"Error initializing pygame mixer: {exc}", file=sys.stderr)
        return False


def _load_sounds():
    sounds = {}
    for name, path in (
        ("welcome", CONFIG["SOUND_WELCOME"]),
        ("wait", CONFIG["SOUND_WAIT"]),
        ("later", CONFIG["SOUND_LATER"]),
    ):
        try:
            sounds[name] = pygame.mixer.Sound(path)
        except (pygame.error, FileNotFoundError) as exc:
            print(f"Error loading sound '{name}': {exc}", file=sys.stderr)
            return False
    return sounds


def _load_model():
    try:
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(CONFIG["TRAINING_FILE"])
        return model
    except cv2.error as exc:
        print(f"Error loading EigenFaceRecognizer model: {exc}", file=sys.stderr)
        return None


def _init_camera():
    try:
        cam = Picamera2(CONFIG["CAMERA_INDEX"])
        cam.configure(
            cam.create_preview_configuration(
                main={"size": (CONFIG["CAMERA_WIDTH"], CONFIG["CAMERA_HEIGHT"]),
                     "format": "BGR888"}
            )
        )
        cam.start()
        return cam
    except Exception as exc:
        print(f"Error initializing camera: {exc}", file=sys.stderr)
        return None


def _init_gpio():
    global _door, _button
    try:
        _door = OutputDevice(CONFIG["DOOR_PIN"], active_high=True, initial_value=False)
        _button = Button(CONFIG["BUTTON_PIN"], pull_up=True)
    except Exception as exc:
        print(f"Error initializing GPIO: {exc}", file=sys.stderr)
        return False
    return True


def _is_button_up():
    try:
        return _button.is_pressed
    except Exception as exc:
        print(f"Error reading button state: {exc}", file=sys.stderr)
        return False


def _capture_frame(cam):
    try:
        frame = cam.capture_array()
        if frame is None or frame.size == 0:
            print("Warning: empty frame captured", file=sys.stderr)
            return None
        return frame
    except Exception as exc:
        print(f"Error capturing frame: {exc}", file=sys.stderr)
        return None


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    if not _load_mixer():
        sys.exit(1)

    sounds = _load_sounds()
    if not sounds:
        sys.exit(1)

    model = _load_model()
    if model is None:
        sys.exit(1)

    cam = _init_camera()
    if cam is None:
        sys.exit(1)

    if not _init_gpio():
        _cleanup()
        sys.exit(1)

    print("Door lock system running. Press Ctrl+C to exit.")

    try:
        while _running:
            frame = _capture_frame(cam)
            if frame is None:
                time.sleep(CONFIG["LOOP_DELAY"])
                continue

            try:
                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                faces = cv2.face.findFaces(gray)
            except cv2.error as exc:
                print(f"OpenCV error during face detection: {exc}", file=sys.stderr)
                time.sleep(CONFIG["LOOP_DELAY"])
                continue

            if len(faces) == 0:
                if not sounds.get("later"):
                    print("Warning: 'later.wav' not loaded; skipping sound.", file=sys.stderr)
                else:
                    try:
                        sounds["later"].play()
                    except pygame.error as exc:
                        print(f"Error playing 'later.wav': {exc}", file=sys.stderr)
            else:
                x, y, w, h = faces[0]
                crop = gray[y:y + h, x:x + w]
                try:
                    label, confidence = model.predict(crop)
                except cv2.error as exc:
                    print(f"Error during face recognition: {exc}", file=sys.stderr)
                    time.sleep(CONFIG["LOOP_DELAY"])
                    continue

                if label == CONFIG["POSITIVE_LABEL"] and confidence < CONFIG["POSITIVE_THRESHOLD"]:
                    print("Recognized face! Unlocking...")
                    try:
                        _door.off()
                    except Exception as exc:
                        print(f"Error unlocking door: {exc}", file=sys.stderr)
                    try:
                        sounds["welcome"].play()
                    except pygame.error as exc:
                        print(f"Error playing 'welcome.wav': {exc}", file=sys.stderr)
                else:
                    print("Face not recognized.")
                    try:
                        sounds["wait"].play()
                    except pygame.error as exc:
                        print(f"Error playing 'wait.wav': {exc}", file=sys.stderr)
            time.sleep(CONFIG["LOOP_DELAY"])
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

