import signal
import sys
import threading
import time

import smbus2
from smbus2 import i2c_msg

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is required. Install with: pip install gpiozero")
    sys.exit(1)

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------
LED_PINS = [17, 18, 23, 27, 22]
LCD_I2C_ADDR = 0x27
LCD_I2C_BUS = 1
LCD_WIDTH = 16
LCD_CHR = 1
LCD_CMD = 0
LCD_LINE_1 = 0x80
LCD_LINE_2 = 0xC0
LCD_BACKLIGHT = 0x08
ENABLE = 0x04

# ---------------------------------------------------------------------------
# Global state
# ---------------------------------------------------------------------------
leds = []
bus = None
running = True


def cleanup(signum=None, frame=None):
    """Stop threads, clear LCD, release GPIO, and exit."""
    global running, bus
    running = False
    time.sleep(0.2)  # allow threads to notice the flag

    for led in leds:
        try:
            led.close()
        except Exception:
            pass

    if bus is not None:
        try:
            bus.write_byte(LCD_I2C_ADDR, 0x00)
            bus.write_byte(LCD_I2C_ADDR, 0x00)
        except Exception:
            pass
        try:
            bus.close()
        except Exception:
            pass

    if signum is not None:
        sys.exit(0)


def init_lcd():
    """Initialize the PCF8574 I2C LCD backpack."""
    global bus
    try:
        bus = smbus2.SMBus(LCD_I2C_BUS)
    except Exception as e:
        print(f"Error: cannot open I2C bus {LCD_I2C_BUS}: {e}")
        sys.exit(1)

    try:
        bus.write_byte(LCD_I2C_ADDR, LCD_BACKLIGHT | ENABLE)
        time.sleep(0.05)
        bus.write_byte(LCD_I2C_ADDR, LCD_BACKLIGHT)
        time.sleep(0.05)
    except Exception as e:
        print(f"Error: LCD initialization failed: {e}")
        cleanup()
        sys.exit(1)


def lcd_write_line(line):
    """Write a 16-character string to a specific LCD line (1 or 2)."""
    try:
        bus.write_byte(LCD_I2C_ADDR, LCD_LINE_1 if line == 1 else LCD_LINE_2)
        msg = line + "   "
        for ch in msg.ljust(LCD_WIDTH)[:LCD_WIDTH]:
            bus.write_byte(LCD_I2C_ADDR, ord(ch) & 0xFF)
    except Exception as e:
        print(f"Warning: LCD write error: {e}")


def cpu_temp():
    """Read CPU temperature from sysfs; return None on failure."""
    try:
        with open("/sys/class/thermal/thermal_zone0/temp", "r") as f:
            return float(f.read().strip()) / 1000.0
    except (IOError, OSError, ValueError):
        return None


def cpu_usage():
    """Read CPU usage percentage from /proc/stat; return None on failure."""
    try:
        with open("/proc/stat", "r") as f:
            parts = f.read().strip().split()
            if len(parts) < 2:
                return None
            user = int(parts[1])
            sys = int(parts[2])
            idle = int(parts[3])
            return (1.0 - (user + sys) / (user + sys + idle)) * 100.0
    except (IOError, OSError, ValueError):
        return None


def display_cpu():
    """Background thread: read CPU stats every 1 s and update LCD."""
    global running
    while running:
        try:
            cpu = cpu_usage()
            temp = cpu_temp()
            if cpu is not None and temp is not None:
                lcd_write_line(f"CPU  : {cpu:5.1f}%")
                lcd_write_line(f"Temp : {temp:4.1f}C")
            else:
                lcd_write_line("CPU  : --   ")
                lcd_write_line("Temp : --   ")
        except Exception as e:
            print(f"Warning: CPU display error: {e}")
        time.sleep(1)


def set_led(cls):
    """Activate the LED for the given class index (0-4) for 1 second."""
    if cls < 0 or cls >= len(LED_PINS):
        print(f"Error: class index {cls} out of range (0-{len(LED_PINS)-1})")
        return
    led = leds[cls]
    try:
        led.on()
        time.sleep(1)
        led.off()
    except GPIOZeroError as e:
        print(f"Error: GPIO error setting LED {LED_PINS[cls]}: {e}")
    except Exception as e:
        print(f"Error: unexpected LED error: {e}")


def main():
    global leds
    signal.signal(signal.SIGINT, cleanup)

    # Initialize LEDs
    for pin in LED_PINS:
        try:
            led = LED(pin)
            leds.append(led)
        except GPIOZeroError as e:
            print(f"Error: failed to initialize LED on GPIO{pin}: {e}")
            cleanup()
            sys.exit(1)

    # Initialize LCD
    init_lcd()

    # Start CPU display thread
    cpu_thread = threading.Thread(target=display_cpu, daemon=True)
    cpu_thread.start()

    # Main loop: user can trigger a specific LED
    try:
        while running:
            print("Enter the class number (0-4) to light the corresponding LED.")
            try:
                user_input = input("Enter class number: ")
                cls = int(user_input)
            except ValueError:
                print("Invalid input. Please enter an integer.")
                continue

            if 0 <= cls < len(LED_PINS):
                set_led(cls)
            else:
                print("Invalid class number. Must be between 0 and", len(LED_PINS) - 1)

    except EOFError:
        pass
    finally:
        cleanup()


if __name__ == "__main__":
    main()

