import smbus2
import time
import signal
import sys
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306
from luma.core.render import canvas

# Constants
I2C_BUS = 1
BH1750_ADDR = 0x23
SSD1306_ADDR = 0x3C
BH1750_ONE_TIME_HIGH_RES = 0x20
CONTRAST_MIN = 0
CONTRAST_MAX = 255
BH1750_CONV_MS = 0.12
UPDATE_INTERVAL = 1.0

# Global state
running = True
bus = None
display = None
last_contrast = 128


def signal_handler(signum, frame):
    global running
    running = False


def init_display():
    try:
        serial = i2c(port=I2C_BUS, address=SSD1306_ADDR)
        return ssd1306(serial)
    except Exception as e:
        print(f"Error initializing OLED display at 0x{SSD1306_ADDR:02X}: {e}")
        return None


def init_sensor():
    global bus
    try:
        bus = smbus2.SMBus(I2C_BUS)
        return True
    except Exception as e:
        print(f"Error initializing I2C bus {I2C_BUS}: {e}")
        return False


def read_light_level():
    if bus is None:
        return None
    try:
        bus.write_byte(BH1750_ADDR, BH1750_ONE_TIME_HIGH_RES)
        time.sleep(BH1750_CONV_MS)
        data = bus.read_i2c_block_data(BH1750_ADDR, 0x00, 2)
        raw = (data[0] << 8) | data[1]
        return raw / 1.2
    except Exception as e:
        print(f"Error reading BH1750 sensor: {e}")
        return None


def calculate_contrast(light_level):
    if light_level is None:
        return last_contrast
    clamped = max(CONTRAST_MIN, min(CONTRAST_MAX, int(light_level)))
    return clamped


def update_display(device, contrast):
    try:
        with canvas(device) as draw:
            draw.text((0, 0), f"Contrast: {contrast:3d}", fill="white")
    except Exception as e:
        print(f"Error updating display: {e}")


def cleanup():
    global display
    if display is not None:
        try:
            display.clear()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass


def main():
    global running, last_contrast, display

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    if not init_sensor():
        print("Cannot continue without I2C bus. Exiting.")
        sys.exit(1)

    display = init_display()
    if display is None:
        print("Cannot continue without OLED display. Exiting.")
        sys.exit(1)

    last_contrast = 128

    try:
        while running:
            light_level = read_light_level()
            contrast = calculate_contrast(light_level)
            update_display(display, contrast)
            time.sleep(UPDATE_INTERVAL)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

