import time
import signal
import sys
import board
import busio
import adafruit_character_lcd.character_lcd_i2c as character_lcd
import adafruit_dht
import adafruit_dht.exceptions

# --- Configuration -----------------------------------------------------------
LCD_I2C_ADDRESS = 0x27          # PCF8574 backpack I2C address
DHT_PIN = board.D4              # GPIO4 (board.SDA)
READ_INTERVAL_SECONDS = 2.0

# --- Globals for cleanup -----------------------------------------------------
_lcd = None
_dht_device = None
_running = True


def _cleanup():
    """Clear the LCD and release the DHT device on exit."""
    global _lcd, _dht_device
    if _lcd is not None:
        try:
            _lcd.clear()
        except Exception:
            pass
    if _dht_device is not None:
        try:
            _dht_device.exit()
        except Exception:
            pass


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def initialize_i2c_bus():
    """Initialize the I2C bus; return the bus object or None on failure."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"Error initializing I2C bus: {exc}", file=sys.stderr)
        return None


def initialize_lcd(i2c_bus, address):
    """Initialize the PCF8574 character LCD; return the LCD object or None."""
    try:
        lcd = character_lcd.Character_LCD_I2C(i2c_bus, address=address)
        lcd.clear()
        return lcd
    except Exception as exc:
        print(f"Error initializing LCD at 0x{address:02X}: {exc}", file=sys.stderr)
        return None


def initialize_dht22(pin):
    """Initialize the DHT22 sensor; return the device or None on failure."""
    try:
        return adafruit_dht.DHT22(pin, use_pulseio=False)
    except Exception as exc:
        print(f"Error initializing DHT22 on {pin}: {exc}", file=sys.stderr)
        return None


def read_dht22_data(dht_device):
    """Read temperature (C) and humidity (%) from the DHT22; return (temp, hum) or (None, None)."""
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except adafruit_dht.DHTError as exc:
        print(f"DHT22 read error: {exc}", file=sys.stderr)
        return None, None
    except Exception as exc:
        print(f"Unexpected DHT22 error: {exc}", file=sys.stderr)
        return None, None


def display_data_on_lcd(lcd, temperature, humidity):
    """Display temperature and humidity on the 16x2 LCD."""
    try:
        lcd.message = f"Temp: {temperature:.1f} C"
        lcd.message = f"Humidity: {humidity:.1f}%"
    except Exception as exc:
        print(f"Error writing to LCD: {exc}", file=sys.stderr)


def main():
    global _lcd, _dht_device

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    i2c_bus = initialize_i2c_bus()
    if i2c_bus is None:
        print("Exiting due to I2C bus initialization failure.", file=sys.stderr)
        sys.exit(1)

    _lcd = initialize_lcd(i2c_bus, LCD_I2C_ADDRESS)
    if _lcd is None:
        print("Exiting due to LCD initialization failure.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    _dht_device = initialize_dht22(DHT_PIN)
    if _dht_device is None:
        print("Exiting due to DHT22 initialization failure.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            temperature, humidity = read_dht22_data(_dht_device)
            if temperature is not None and humidity is not None:
                display_data_on_lcd(_lcd, temperature, humidity)
            else:
                print("Skipping display update due to sensor read failure.", file=sys.stderr)
            time.sleep(READ_INTERVAL_SECONDS)
    except Exception as exc:
        print(f"Unexpected runtime error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

