import os
import time
import signal
import logging
from PIL import Image, ImageOps, ImageChops, UnidentifiedImageError
from luma.core.interface.serial import i2c
from luma.core.render import canvas
from luma.oled.device import ssd1306
from luma.core.error import DeviceNotFoundError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

I2C_PORT = 1
I2C_ADDRESS = 0x3C
IMAGE_FOLDER = "images"
DISPLAY_WIDTH = 128
DISPLAY_HEIGHT = 64

running = True

def signal_handler(sig, frame):
    global running
    running = False
    logging.info("Exiting gracefully...")

def load_images(image_folder):
    if not os.path.isdir(image_folder):
        logging.error(f"Image folder not found: {image_folder}")
        return []
    try:
        image_files = [f for f in os.listdir(image_folder) if f.lower().endswith(('.gif', '.png', '.jpg', '.jpeg'))]
        if not image_files:
            logging.warning(f"No image files found in {image_folder}")
            return []
        return [os.path.join(image_folder, f) for f in image_files]
    except OSError as e:
        logging.error(f"Error accessing folder {image_folder}: {e}")
        return []

def initialize_display(i2c_port, i2c_address):
    try:
        serial = i2c(port=i2c_port, address=i2c_address)
        device = ssd1306(serial, width=DISPLAY_WIDTH, height=DISPLAY_HEIGHT)
        logging.info(f"Display initialized at I2C address 0x{i2c_address:02X} on bus {i2c_port}")
        return device
    except DeviceNotFoundError as e:
        logging.error(f"I2C device not found at address 0x{i2c_address:02X}: {e}")
        return None
    except Exception as e:
        logging.error(f"Error initializing display: {e}")
        return None

def play_gif(device, image_path):
    try:
        with Image.open(image_path) as img:
            img = img.convert('RGB')
            frames = []
            for frame in img.sequence:
                if frame is None:
                    continue
                if frame.size != (DISPLAY_WIDTH, DISPLAY_HEIGHT):
                    frame = frame.resize((DISPLAY_WIDTH, DISPLAY_HEIGHT))
                padded = Image.new('RGB', (DISPLAY_WIDTH, DISPLAY_HEIGHT), 'black')
                x, y = (DISPLAY_WIDTH // 2, DISPLAY_HEIGHT // 2)
                padded.paste(frame, (x, y))
                frames.append(padded)
            if not frames:
                logging.warning(f"No valid frames found in {image_path}")
                return
            frame_delay = 1000 / max(1, int(img.info.get('gif', 'loop', 0)))
            if frame_delay <= 0:
                frame_delay = 100
            current_loop = 0
            while running and current_loop < frame_delay:
                frame_index = 0
                while running and frame_index < len(frames):
                    if current_loop >= frame_delay:
                        current_loop = 0
                    frame = frames[frame_index]
                    device.display(frame)
                    time.sleep(1000 / frame_delay)
                    frame_index += 1
                    current_loop += 1
    except FileNotFoundError:
        logging.error(f"Image file not found: {image_path}")
    except UnidentifiedImageError:
        logging.error(f"Could not read image data from {image_path}")
    except Exception as e:
        logging.error(f"Error playing GIF {image_path}: {e}")

def main():
    signal.signal(signal.SIGINT, signal_handler)
    device = initialize_display(I2C_PORT, I2C_ADDRESS)
    if device is None:
        return
    try:
        image_files = load_images(IMAGE_FOLDER)
        if not image_files:
            return
        for image_path in image_files:
            if not running:
                break
            logging.info(f"Playing GIF: {image_path}")
            play_gif(device, image_path)
    finally:
        try:
            device.cleanup()
            logging.info("Display resources released.")
        except Exception as e:
            logging.error(f"Error releasing display resources: {e}")

if __name__ == "__main__":
    main()

