import math
import signal
import sys
import time

from gpiozero import PWMOutputDevice

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LEFT_MOTOR_PIN = 12
LEFT_MOTOR_PIN2 = 13
RIGHT_MOTOR_PIN = 18
RIGHT_MOTOR_PIN2 = 19

GOAL_X, GOAL_Y = 0, 200
BALL_X, BALL_Y = 180, -200
CAR_FRONT_X, CAR_FRONT_Y = 180, -15
CAR_BACK_X, CAR_BACK_Y = 200, -15
EXTENSION = 50
MAX_ITERATIONS = 1000
STEP_DELAY = 0.1

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_running = True
_left_motor = None
_right_motor = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _left_motor, _right_motor
    for m in (_left_motor, _right_motor):
        if m is not None:
            try:
                m.close()
            except Exception:
                pass
    _left_motor = _right_motor = None


def _clamp(value, lo, hi):
    return max(lo, min(hi, value))


def _distance(x1, y1, x2, y2):
    return math.hypot(x2 - x1, y2 - y1)


def _heading(x1, y1, x2, y2):
    dx = x2 - x1
    dy = y2 - y1
    return math.degrees(math.atan2(dy, dx))


def _angle_between(a, b):
    c = _distance(a, b)
    if c == 0:
        return 0.0
    d = _distance(a, c) + _distance(b, c)
    return math.degrees(math.atan2(d, c))


def _move_forward(m1, m2):
    m1.value = 0.5
    m2.value = 0.5


def _turn_right(m1, m2):
    m1.value = 0.5
    m2.value = 0.0


def _turn_left(m1, m2):
    m1.value = 0.0
    m2.value = 0.5


def _stop(m1, m2):
    m1.value = 0.0
    m2.value = 0.0


def _calculate_image_point(ball_x, ball_y, goal_x, goal_y, extension):
    try:
        dx = goal_x - ball_x
        dy = goal_y - ball_y
        if abs(dx) < 1e-6:
            return ball_x, ball_y
        image_x = ball_x + dx * extension
        image_y = ball_y + dy * extension
        return image_x, image_y
    except Exception as exc:
        print(f"Error calculating image point: {exc}", file=sys.stderr)
        return None, None


def _calculate_heading(car_front_x, car_front_y, car_back_x, car_back_y):
    try:
        dx = car_back_x - car_front_x
        dy = car_back_y - car_front_y
        if abs(dx) < 1e-6:
            return 0.0
        return _heading(car_front_x, car_front_y, car_back_x, car_back_y)
    except Exception as exc:
        print(f"Error calculating heading: {exc}", file=sys.stderr)
        return 0.0


def _calculate_distance(x1, y1, x2, y2):
    try:
        return _distance(x1, y1, x2, y2)
    except Exception as exc:
        print(f"Error calculating distance: {exc}", file=sys.stderr)
        return float('inf')


def _control_loop(m1, m2, car_front_x, car_front_y, car_back_x, car_back_y,
                   goal_x, goal_y, image_point_x, image_point_y,
                   extension, max_iterations):
    global _running
    iterations = 0
    while _running and iterations < max_iterations:
        iterations += 1
        try:
            distance_to_image = _calculate_distance(car_front_x, car_front_y, image_point_x, image_point_y)
            distance_to_goal = _calculate_distance(car_front_x, car_front_y, goal_x, goal_y)
            angle_to_image = _angle_between(car_front_x, car_front_y, image_point_x, image_point_y)
            angle_to_goal = _angle_between(car_front_x, car_front_y, goal_x, goal_y)

            if distance_to_image > 10:
                _move_forward(m1, m2)
            elif distance_to_image < 10:
                _turn_right(m1, m2) if angle_to_image < 180 else _turn_left(m1, m2)
            else:
                _stop(m1, m2)

            if distance_to_goal > 10:
                _turn_right(m1, m2) if angle_to_goal < 180 else _turn_left(m1, m2)
            else:
                _stop(m1, m2)

            print(f"Iter {iterations:3d}  dist_to_image={distance_to_image:7.2f} deg_to_image={angle_to_image:7.2f} "
                  f"dist_to_goal={distance_to_goal:7.2f} deg_to_goal={angle_to_goal:7.2f}")
        except Exception as exc:
            print(f"Error in control loop: {exc}", file=sys.stderr)
            _stop(m1, m2)
            break
        time.sleep(STEP_DELAY)
    return _running


def main():
    global _left_motor, _right_motor

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _left_motor = PWMOutputDevice(LEFT_MOTOR_PIN)
        _right_motor = PWMOutputDevice(RIGHT_MOTOR_PIN)
        _left_motor.value = 0.0
        _right_motor.value = 0.0
    except Exception as exc:
        print(f"Failed to initialize motors: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        ball_x, ball_y = _calculate_image_point(BALL_X, BALL_Y, GOAL_X, GOAL_Y, EXTENSION)
        if ball_x is None or ball_y is None:
            print("Error calculating image point; aborting.", file=sys.stderr)
            _cleanup()
            sys.exit(1)

        car_front_x, car_front_y = CAR_FRONT_X, CAR_FRONT_Y
        car_back_x, car_back_y = CAR_BACK_X, CAR_BACK_Y

        _running = _control_loop(_left_motor, _right_motor,
                                 car_front_x, car_front_y, car_back_x, car_back_y,
                                 GOAL_X, GOAL_Y, ball_x, ball_y, EXTENSION, MAX_ITERATIONS)
    except Exception as exc:
        print(f"Fatal error: {exc}", file=sys.stderr)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

