        return _distance(x1, y1, x2, y2)
    except Exception as exc:
        print(f"Error calculating distance: {exc}", file=sys.stderr)
        return float('inf')


def _control_loop(m1, m2, car_front_x, car_front_y, car_back_x, car_back_y,
                   goal_x, goal_y, image_point_x, image_point_y,
                   extension, max_iterations):
    global _running
    iterations = 0
    while _running and iterations < max_iterations:
        iterations += 1
        try:
            distance_to_image = _calculate_distance(car_front_x, car_front_y, image_point_x, image_point_y)
            distance_to_goal = _calculate_distance(car_front_x, car_front_y, goal_x, goal_y)
            angle_to_image = _angle_between(car_front_x, car_front_y, image_point_x, image_point_y)
            angle_to_goal = _angle_between(car_front_x, car_front_y, goal_x, goal_y)

            if distance_to_image > 10:
                _move_forward(m1, m2)
            elif distance_to_image < 10:
                _turn_right(m1, m2) if angle_to_image < 180 else _turn_left(m1, m2)
            else:
                _stop(m1, m2)

            if distance_to_goal > 10:
                _turn_right(m1, m2) if angle_to_goal < 180 else _turn_left(m1, m2)
            else:
                _stop(m1, m2)

            print(f"Iter {iterations:3d}  dist_to_image={distance_to_image:7.2f} deg_to_image={angle_to_image:7.2f} "
