import json
import time
import random
import logging
import paho.mqtt.client as mqtt

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

BROKER = "test.mosquitto.org"
PORT = 1883
KEEPALIVE = 60
TOPIC = "classroom/temperature"
MESSAGE_COUNT = 5
RETRY_DELAY = 2
MAX_RETRIES = 3

class TemperaturePublisher:
    def __init__(self, broker, port, keepalive, topic, message_count, retry_delay, max_retries):
        self.broker = broker
        self.port = port
        self.keepalive = keepalive
        self.topic = topic
        self.message_count = message_count
        self.retry_delay = retry_delay
        self.max_retries = max_retries
        self.client = None
        self.message_index = 0
        self._connected = False
        self._connected_event = threading.Event()

    def connect(self):
        """Connect to the broker with retry logic and on-connect callbacks."""
        for attempt in range(1, self.max_retries + 1):
            try:
                self.client = mqtt.Client(
                    mqtt.CallbackAPIVersion.VERSION2,
                    client_id="classroom-publisher"
                )
                self.client.on_connect = self._on_connect
                self.client.on_publish = self._on_publish
                self.client.on_disconnect = self._on_disconnect
                self.client.on_subscribe = self._on_subscribe

                self.client.connect(self.broker, self.port, self.keepalive)
                self.client.loop_start()
                self._connected_event.set()
                self._connected = True
                logger.info("Connected to broker %s:%d (attempt %d)", self.broker, self.port, attempt)
                return True
            except Exception as e:
                logger.error("Connection attempt %d/%d failed: %s", attempt, self.max_retries, e)
                if attempt < self.max_retries:
                    time.sleep(self.retry_delay)
                else:
                    logger.error("Max connection attempts reached, giving up.")
                    return False

    def _on_connect(self, client, userdata, flags, reason_code, properties):
        if reason_code == 0:
            logger.info("Connected to broker successfully")
            client.subscribe(self.topic)
        else:
            logger.error("Connection failed with reason code %s", reason_code)

    def _on_publish(self, client, userdata, mid, reason_code, properties):
        if reason_code != 0:
            logger.warning("Publish failed with reason code %s", reason_code)

    def _on_subscribe(self, client, userdata, mid, reason_code, properties):
        if reason_code != 0:
            logger.warning("Subscribe failed with reason code %s", reason_code)

    def publish_messages(self):
        """Publish MESSAGE_COUNT temperature readings to the configured topic."""
        if not self._connected:
            logger.error("Cannot publish: not connected to broker")
            return 0

        readings = []
        for i in range(self.message_count):
            temperature = self._generate_temperature()
            payload = json.dumps({"index": self.message_index, "temperature": round(temperature, 2)})
            self.message_index += 1

            try:
                result = self.client.publish(self.topic, payload, qos=0)
                if result.rc == mqtt.MQTT_ERR_SUCCESS:
                    readings.append(payload)
                    logger.info("Published message %d/%d: %s", i + 1, self.message_count, payload)
                else:
                    logger.error("Publish failed for message %d: %s", i + 1, result.rc)
            except Exception as e:
                logger.error("Publish error for message %d: %s", i + 1, e)

        return len(readings)

    def _generate_temperature(self):
        """Return a simulated temperature in Celsius between 19.0 and 26.0."""
        return round(random.uniform(19.0, 26.0), 2)

    def disconnect(self):
        """Cleanly disconnect the client."""
        if self.client:
            try:
                self.client.loop_stop()
                self.client.disconnect()
                logger.info("Disconnected from broker")
            except Exception as e:
                logger.error("Error during disconnect: %s", e)
            finally:
                self.client = None

    def wait_for_connect(self):
        """Wait for on_connect callback or timeout."""
        deadline = time.time() + 10
        while self._connected_event.wait(timeout=1):
            if self._connected:
                return True
            if time.time() > deadline:
                logger.error("Timeout waiting for broker connection")
                return False
        return False


def main():
    publisher = TemperaturePublisher(
        broker=BROKER,
        port=PORT,
        keepalive=KEEPALIVE,
        topic=TOPIC,
        message_count=MESSAGE_COUNT,
        retry_delay=RETRY_DELAY,
        max_retries=MAX_RETRIES
    )

    if not publisher.connect():
        logger.error("Failed to connect to broker after retries")
        return 1

    try:
        if not publisher.wait_for_connect():
            logger.error("Failed to connect to broker")
            return 1

        published = publisher.publish_messages()
        logger.info("Successfully published %d messages", published)
        return 0 if published == MESSAGE_COUNT else 1
    except KeyboardInterrupt:
        logger.info("Interrupted by user")
        return 130
    except Exception as e:
        logger.error("Unexpected error: %s", e)
        return 1
    finally:
        publisher.disconnect()


if __name__ == "__main__":
    raise SystemExit(main())

