import time
import logging
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')


class DHT20:
    """Driver for the Aosong DHT20 temperature and humidity sensor over I2C."""

    I2C_BUS = 1
    I2C_ADDRESS = 0x38
    STATUS_REG = 0x71
    COMMAND_REG = 0xAC
    MEASURE_CMD = [0x33, 0x00]

    def __init__(self, bus_num=I2C_BUS, address=I2C_ADDRESS):
        self.address = address
        self._bus = None
        try:
            self._bus = smbus2.SMBus(bus_num)
        except FileNotFoundError:
            logging.error("I2C bus %d not found. Enable I2C with 'sudo raspi-config'.", bus_num)
            raise
        except PermissionError:
            logging.error("Permission denied on I2C bus %d. Run as root or add user to i2c group.", bus_num)
            raise
        except OSError as e:
            logging.error("Failed to open I2C bus %d: %s", bus_num, e)
            raise

        try:
            time.sleep(0.5)
            status = self._read_register(self.STATUS_REG, 1)[0]
            if (status & 0x18) != 0x18:
                logging.error("DHT20 not detected at address 0x%02X. Status byte 0x%02X does not indicate a measurement in progress.", address, status)
                self.close()
                raise RuntimeError("DHT20 not detected")
            logging.info("DHT20 initialized successfully.")
        except OSError as e:
            logging.error("I2C communication error during init: %s", e)
            self.close()
            raise

    def _read_register(self, reg, length):
        try:
            return self._bus.read_i2c_block_data(self.address, reg, length)
        except OSError as e:
            logging.error("I2C read error at register 0x%02X: %s", reg, e)
            raise

    def _write_register(self, reg, data):
        try:
            self._bus.write_i2c_block_data(self.address, reg, data)
        except OSError as e:
            logging.error("I2C write error at register 0x%02X: %s", reg, e)
            raise

    def get_temperature_and_humidity(self):
        """Trigger a measurement and return (temperature, humidity, crc_error_flag)."""
        for attempt in range(1, 6):
            try:
