import asyncio
import json
import logging
import logging.handlers
import signal
import sys
import time
from datetime import datetime

import RPi.GPIO as GPIO
import board
import adafruit_dht

DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"system_code": "10101", "unit_codes": [1, 2, 3]},
    ],
}

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="greenhouse_config.json"):
    try:
        with open(config_file, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Configuration file not found: {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        print(f"Invalid JSON in {config_file}: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()


def setup_logging(log_file):
    logger = logging.getLogger("greenhouse")
    logger.setLevel(logging.INFO)
    handler = logging.handlers.RotatingFileHandler(
        log_file, maxBytes=1024 * 1024, backupCount=5
    )
    formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    handler.setFormatter(formatter)
    logger.addHandler(handler)
    return logger


def setup_gpio(transmitter_pin):
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(transmitter_pin, GPIO.OUT, initial=GPIO.LOW)


def setup_dht22(pin):
    try:
        dht = adafruit_dht.DHT22(getattr(board, f"D{pin}"), use_pulseio=False)
        return dht
    except Exception as e:
        print(f"Failed to initialize DHT22 on pin {pin}: {e}")
        return None


def read_dht22(dht, logger):
    if dht is None:
        return None, None
    for attempt in range(3):
        try:
            temperature = dht.temperature
            humidity = dht.humidity
            if temperature is not None and humidity is not None:
                logger.info(f"DHT22: Temp={temperature:.1f}C, Humidity={humidity:.1f}%")
                return temperature, humidity
        except RuntimeError as e:
            logger.warning(f"DHT22 read error (attempt {attempt + 1}/3): {e}")
        except Exception as e:
            logger.error(f"DHT22 unexpected error (attempt {attempt + 1}/3): {e}")
        time.sleep(2)
    return None, None


async def control_outlet(outlet_config, system_code, unit_code, state, logger, dht):
    if state not in ("on", "off"):
        logger.error(f"Invalid state '{state}' for outlet {system_code}.{unit_code}")
        return
    if system_code not in outlet_config:
        logger.error(f"Unknown system_code '{system_code}' for outlet {system_code}.{unit_code}")
        return
    if unit_code not in outlet_config[system_code]:
        logger.error(f"Unknown unit_code '{unit_code}' for outlet {system_code}.{unit_code}")
        return
    if state == "on":
        GPIO.output(transmitter_pin, GPIO.HIGH)
        code = self._build_transmit_code(system_code, unit_code, "1", 0)
        for _ in range(3):
            if not _running:
                break
            try:
                GPIO.output(transmitter_pin, GPIO.LOW)
                GPIO.output(transmitter_pin, GPIO.HIGH)
                for bit in code:
                    GPIO.output(transmitter_pin, GPIO.LOW)
                    if bit:
                        GPIO.output(transmitter_pin, GPIO.HIGH)
                    else:
                        GPIO.output(transmitter_pin, GPIO.LOW)
                    time.sleep(0.0003)
                GPIO.output(transmitter_pin, GPIO.LOW)
                time.sleep(0.5)
            except Exception as e:
                logger.error(f"Transmission error for outlet {system_code}.{unit_code}: {e}")
                break
            time.sleep(0.1)
    else:
        GPIO.output(transmitter_pin, GPIO.LOW)
        code = self._build_transmit_code(system_code, unit_code, "0", 0)
        for _ in range(3):
            if not _running:
                break
            try:
                GPIO.output(transmitter_pin, GPIO.LOW)
                GPIO.output(transmitter_pin, GPIO.HIGH)
                for bit in code:
                    GPIO.output(transmitter_pin, GPIO.LOW)
                    if bit:
                        GPIO.output(transmitter_pin, GPIO.HIGH)
                    else:
                        GPIO.output(transmitter_pin, GPIO.LOW)
                    time.sleep(0.0003)
                GPIO.output(transmitter_pin, GPIO.LOW)
                time.sleep(0.5)
            except Exception as e:
                logger.error(f"Transmission error for outlet {system_code}.{unit_code}: {e}")
                break
            time.sleep(0.1)


async def transmit_code(system_code, unit_code, state, transmitter_pin, logger, dht):
    code = self._build_transmit_code(system_code, unit_code, state, 0)
    for _ in range(3):
        if not _running:
            break
        try:
            GPIO.output(transmitter_pin, GPIO.LOW)
            GPIO.output(transmitter_pin, GPIO.HIGH)
            for bit in code:
                GPIO.output(transmitter_pin, GPIO.LOW)
                if bit:
                    GPIO.output(transmitter_pin, GPIO.HIGH)
                else:
                    GPIO.output(transmitter_pin, GPIO.LOW)
                time.sleep(0.0003)
            GPIO.output(transmitter_pin, GPIO.LOW)
            time.sleep(0.5)
        except Exception as e:
            logger.error(f"Transmission error: {e}")
            break
        time.sleep(0.1)


async def main_loop(config, logger, dht):
    global _running
    while _running:
        temperature, humidity = await read_dht22(dht, logger)
        if temperature is not None and humidity is not None:
            logger.info(f"Sensor data: Temperature={temperature:.1f}C, Humidity={humidity:.1f}%")
        for system_code, unit_codes in config["outlet_configurations"]:
            if not _running:
                break
            for unit_code in unit_codes:
                if not _running:
                    break
                await asyncio.gather(
                    control_outlet(config, system_code, unit_code, "on", logger, dht),
                    control_outlet(config, system_code, unit_code, "off", logger, dht),
                )


async def cli_loop(config, logger, dht):
    global _running
    while _running:
        try:
            command = input("Enter command (on/off/status): ").strip().lower()
        except EOFError:
            break
        if not command:
            continue
        if command == "on":
            if not _running:
                break
            outlet = input("Enter outlet number (1-3): ").strip()
            if outlet not in config["outlet_configurations"][0]["unit_codes"]:
                logger.error(f"Invalid outlet number: {outlet}")
                continue
            await asyncio.gather(
                transmit_code(
                    config["outlet_configurations"][0]["system_code"],
                    outlet,
                    "on",
                    config["gpio_transmitter_pin"],
                    logger,
                    dht,
                )
            )
        elif command == "off":
            if not _running:
                break
            outlet = input("Enter outlet number (1-3): ").strip()
            if outlet not in config["outlet_configurations"][0]["unit_codes"]:
                logger.error(f"Invalid outlet number: {outlet}")
                continue
            await asyncio.gather(
                transmit_code(
                    config["outlet_configurations"][0]["system_code"],
                    outlet,
                    "off",
                    config["gpio_transmitter_pin"],
                    logger,
                    dht,
                )
            )
        elif command == "status":
            if not _running:
                break
            for system_code, unit_codes in config["outlet_configurations"]:
                if not _running:
                    break
                for unit_code in unit_codes:
                    if not _running:
                        break
                    state = "on" if GPIO.input(config["gpio_transmitter_pin"]) else "off"
                    logger.info(f"Outlet {system_code}.{unit_code} status: {state}")
        else:
            logger.warning(f"Unknown command: {command}")
        time.sleep(1)


async def main():
    config = load_config()
    logger = setup_logging(config["log_file"])
    logger.info("Greenhouse controller starting")
    logger.info(f"Config: {config}")
    transmitter_pin = config["gpio_transmitter_pin"]
    dht_pin = config["gpio_dht22_pin"]
    dht = setup_dht22(dht_pin)
    setup_gpio(transmitter_pin)
    await main_loop(config, logger, dht)
    await cli_loop(config, logger, dht)
    GPIO.cleanup()
    logger.info("Greenhouse controller stopped")


if __name__ == "__main__":
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        pass

