import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Constants
I2C_ADDRESS_BME280 = 0x76
I2C_ADDRESS_TSL2591 = 0x29
I2C_MUX_ADDR = 0x70
READ_INTERVAL_SECONDS = 2

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_mux(i2c_bus):
    """Initializes the TCA9548A I2C multiplexer."""
    try:
        return adafruit_tca9548a.TCA9548A(i2c_bus, address=I2C_MUX_ADDR)
    except Exception as e:
        print(f"Error initializing TCA9548A multiplexer: {e}")
        return None

def initialize_bme280(i2c_bus, mux):
    """Initializes the BME280 sensor on multiplexer channel 0."""
    try:
        return adafruit_bme280.Adafruit_BME280_I2C(mux[0], address=I2C_ADDRESS_BME280, i2c=i2c_bus)
    except Exception as e:
        print(f"Error initializing BME280 sensor: {e}")
        return None

def initialize_tsl2591(i2c_bus, mux):
    """Initializes the TSL2591 sensor on multiplexer channel 1."""
    try:
        return adafruit_tsl2591.TSL2591(mux[1], address=I2C_ADDRESS_TSL2591, i2c=i2c_bus)
    except Exception as e:
        print(f"Error initializing TSL2591 sensor: {e}")
        return None

def read_sensor_data(bme280_sensor, tsl2591_sensor):
    """Reads data from the BME280 and TSL2591 sensors."""
    try:
        temperature = bme280_sensor.temperature
        humidity = bme280_sensor.humidity
        light_intensity = tsl2591_sensor.lux
        return temperature, humidity, light_intensity
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None, None

def display_sensor_data(temperature, humidity, light_intensity):
    """Displays the sensor data in a formatted manner."""
    print(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %, Light Intensity: {light_intensity:.2f} lux")

def main():
    """Main function to read and display sensor data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    i2c_mux = initialize_mux(i2c_bus)
    if i2c_mux is None:
        return

    bme280_sensor = initialize_bme280(i2c_bus, i2c_mux)
    if bme280_sensor is None:
        return

    tsl2591_sensor = initialize_tsl2591(i2c_bus, i2c_mux)
    if tsl2591_sensor is None:
        return

    try:
        while True:
            temperature, humidity, light_intensity = read_sensor_data(bme280_sensor, tsl2591_sensor)
            if temperature is not None and humidity is not None and light_intensity is not None:
                display_sensor_data(temperature, humidity, light_intensity)
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No explicit cleanup needed for I2C bus or sensor objects in this context
        pass

if __name__ == "__main__":
    main()

