import time
import signal
import sys
import RPi.GPIO as GPIO
import adafruit_dht
import board

# --- Configuration -----------------------------------------------------------
DHT_PIN = board.D4          # DHT11 data line on GPIO4 (BCM)
RED_PIN = 17
GREEN_PIN = 27
BLUE_PIN = 22
PWM_FREQ = 100             # Hz
SAMPLE_INTERVAL = 1.0       # seconds
DHT_RETRY_DELAY = 0.5      # seconds between retries on failure

# --- Globals for cleanup -----------------------------------------------------
_running = True
_pwm = None
_dht = None

def _signal_handler(signum, frame):
    global _running
    _running = False

def _cleanup():
    global _pwm, _dht
    if _pwm is not None:
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    if _dht is not None:
        try:
            _dht.exit()
        except Exception:
            pass
        _dht = None
    try:
        GPIO.cleanup()
    except Exception:
        pass

def _set_leds(red, green, blue):
    GPIO.output(RED_PIN, GPIO.HIGH if red else GPIO.LOW)
    GPIO.output(GREEN_PIN, GPIO.HIGH if green else GPIO.LOW)
    GPIO.output(BLUE_PIN, GPIO.HIGH if blue else GPIO.LOW)

def _map_temp_to_color(temp_c):
    if temp_c < 20:
        return (0, 0, 100)
    elif temp_c <= 25:
        return (0, 100, 0)
    else:
        return (100, 0, 0)

def main():
    global _running, _pwm, _dht

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)

    # Initialize PWM on all three channels
    try:
        _pwm = GPIO.PWM(RED_PIN, PWM_FREQ)
        _pwm.start(0)
        _pwm2 = GPIO.PWM(GREEN_PIN, PWM_FREQ)
        _pwm2.start(0)
        _pwm3 = GPIO.PWM(BLUE_PIN, PWM_FREQ)
        _pwm3.start(0)
    except Exception as e:
        print(f"Failed to initialize PWM: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # Initialize DHT11
    try:
        _dht = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11: {e}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    last_temp = None
    last_color = (0, 0, 0)

    try:
        while _running:
            try:
                temp_c = _dht.temperature
                if temp_c is None:
                    raise RuntimeError("Sensor returned None")
                last_temp = temp_c
                last_color = _map_temp_to_color(temp_c)
                _set_leds(*last_color)
                print(f"Temp: {temp_c:.1f}C  ->  Green")
            except RuntimeError as e:
                # DHT11 checksum / timing errors are common; retry with backoff
                print(f"DHT11 read error: {e}", file=sys.stderr)
                time.sleep(DHT_RETRY_DELAY)
                continue
            except Exception as e:
                print(f"Unexpected sensor error: {e}", file=sys.stderr)
                time.sleep(DHT_RETRY_DELAY)
                continue

            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        pass
    finally:
        _cleanup()

if __name__ == "__main__":
    main()

