import time
import random
import logging
import sqlite3
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

DB_PATH = '/tmp/wearable_health.db'
LED_PIN = 23
SAMPLE_INTERVAL = 0.05
WINDOW_SIZE = 20
LIFE_THRESHOLD = 100.0
LIFE_INIT = 500.0
DEG_FACTOR = 0.6
TEMP_FACTOR = 0.4
EXP_COEFF = 3.0

running = True
led = None
conn = None

def signal_handler(signum, frame):
    global running
    logger.info('Signal %d received, shutting down...', signum)
    running = False

def setup_gpio():
    global led
    try:
        led = LED(LED_PIN)
        led.off()
        logger.info('GPIO %d setup complete (current-limiting via 330Ω resistor).', LED_PIN)
    except GPIOZeroError as e:
        logger.error('GPIO setup failed: %s', e)
        sys.exit(1)

def setup_db():
    global conn
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.execute('''
            CREATE TABLE IF NOT EXISTS alerts (
                remaining_life REAL,
                ts REAL
            )
        ''')
        conn.commit()
        logger.info('Database setup complete: %s', DB_PATH)
    except sqlite3.Error as e:
        logger.error('Database setup failed: %s', e)
        sys.exit(1)

def read_vibration():
    return round(random.uniform(0.1, 0.9), 2)

def read_temperature():
    return round(random.uniform(30.0, 70.0), 2)

def calculate_degradation(vibration, temperature):
    mean_vibration = sum(vibration) / len(vibration)
    mean_temp = sum(temperature) / len(temperature)
    return DEG_FACTOR * mean_vibration + TEMP_FACTOR * (mean_temp / 100.0)

def estimate_remaining_life(degradation):
    return max(0.0, LIFE_INIT * (1.0 - (exp(-EXP_COEFF * degradation) + 1.0) / 2.0))

def store_alert(remaining_life, degradation):
    try:
        ts = time.time()
        conn.execute('''
            INSERT INTO alerts (remaining_life, ts) VALUES (?, ?)
        ''', (remaining_life, ts))
        conn.commit()
        logger.info('Alert stored: remaining=%s, degradation=%.4f', remaining_life, degradation)
    except sqlite3.Error as e:
        logger.error('Database write failed: %s', e)

def blink_alert():
    if led is None:
        return
    try:
        led.on()
        time.sleep(1.0)
        led.off()
        time.sleep(1.0)
    except GPIOZeroError as e:
        logger.error('LED blink failed: %s', e)

def cleanup():
    global led, conn
    if led is not None:
        try:
            led.off()
            led.close()
        except GPIOZeroError:
