LED_PIN = 23
SAMPLE_INTERVAL = 0.05
WINDOW_SIZE = 20
LIFE_THRESHOLD = 100.0
LIFE_INIT = 500.0
DEG_FACTOR = 0.6
TEMP_FACTOR = 0.4
EXP_COEFF = 3.0

