    global running
    logger.info('Signal %d received, shutting down...', signum)
    running = False

def setup_gpio():
    global led
    try:
        led = LED(LED_PIN)
        led.off()
        logger.info('GPIO %d setup complete (current-limiting via 330Ω resistor).', LED_PIN)
    except GPIOZeroError as e:
        logger.error('GPIO setup failed: %s', e)
        sys.exit(1)

def setup_db():
    global conn
    try:
        conn = sqlite3.connect(DB_PATH)
        conn.execute('''
            CREATE TABLE IF NOT EXISTS alerts (
                remaining_life REAL,
                ts REAL
            )
        ''')
        conn.commit()
        logger.info('Database setup complete: %s', DB_PATH)
