#!/usr/bin/env python3
"""
Raspberry Pi 4 Model B CPU Temperature Monitor

Reads the CPU temperature every 5 seconds using gpiozero.CPUTemperature.
Lazily instantiates the sensor so that missing /sys/class/thermal/thermal_zone0/temp
is treated as a per-read error instead of a startup crash.
"""

import time
import sys

try:
    from gpiozero import CPUTemperature
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)


def read_cpu_temperature():
    """
    Reads the CPU temperature and prints it to the console.

    Lazily instantiates the CPUTemperature sensor so that missing
    /sys/class/thermal/thermal_zone0/temp is caught as a per-read
    FileNotFoundError instead of a startup crash.
    """
    try:
        cpu = CPUTemperature()
        temperature = cpu.temperature
        print(f"CPU Temperature: {temperature:.2f} °C")
    except FileNotFoundError:
        print("Error: CPU temperature file not found. Check /sys/class/thermal/thermal_zone0/temp.")
    except Exception as e:
        print(f"Error reading CPU temperature: {e}")


def main():
    """Main loop: read CPU temperature every 5 seconds until interrupted."""
    try:
        while True:
            read_cpu_temperature()
            time.sleep(5)
    except KeyboardInterrupt:
        print("Program terminated")
        sys.exit(0)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

