import time
import logging
import signal
import sys
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class BMP280:
    def __init__(self, bus_id=1, address=0x76):
        self.bus_id = bus_id
        self.address = address
        self.sea_level_pressure = 1013.25
        self.bus = None
        self._running = True

    def begin(self):
        try:
            self.bus = smbus2.SMBus(self.bus_id)
            chip_id = self.bus.read_byte_data(self.address, 0xD0)
            if chip_id != 0x58:
                raise OSError(f"BMP280 not found at 0x{self.address:02X} on bus {self.bus_id}: chip_id=0x{chip_id:02X}")
            logging.info("BMP280 initialized successfully.")
            return True
        except OSError as e:
            logging.error(f"Error initializing BMP280: {e}")
            self.bus = None
            return False

    def get_pressure(self):
        if not self.bus:
            raise OSError("BMP280 not initialized.")
        try:
            data = self.bus.read_i2c_block_data(self.address, 0xF7, 8)
            raw_press = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4)
            raw_press = raw_press >> 4
            if raw_press == 0:
                raise OSError("Invalid pressure reading (raw_press == 0)")
            pressure = raw_press * 100.0 / 65536.0
            return pressure
        except OSError as e:
            logging.error(f"Error reading pressure: {e}")
            raise

    def get_altitude(self):
        pressure = self.get_pressure()
        altitude = 44330.0 * (1.0 - (pressure / self.sea_level_pressure) ** (1.0 / 5.255))
        return altitude

    def cleanup(self):
        if self.bus:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None

def calibrate_sensor(bmp280, num_samples=100, discard_percent=25):
    logging.info("Calibrating sensor...")
    valid_samples = []
    for i in range(num_samples):
        try:
            p = bmp280.get_pressure()
            valid_samples.append(p)
            time.sleep(0.1)
        except OSError as e:
            logging.error(f"Error during calibration sample {i}: {e}")
            continue
    if not valid_samples:
        raise CalibrationError("No valid calibration samples collected.")
    cutoff = int(len(valid_samples) * (1 - discard_percent / 100))
    if cutoff < 1:
        cutoff = 1
    valid_samples = valid_samples[cutoff:]
    if not valid_samples:
        raise CalibrationError("No valid calibration samples after trimming.")
    baseline = sum(valid_samples) / len(valid_samples)
    logging.info(f"Calibration complete. Baseline pressure: {baseline:.2f} hPa")
    return baseline

def main():
    bmp280 = BMP280(bus_id=1, address=0x76)
    if not bmp280.begin():
        logging.error("BMP280 initialization failed. Exiting.")
        sys.exit(1)

    try:
        baseline = calibrate_sensor(bmp280)
        if not baseline:
            logging.error("Calibration failed. Using default sea level pressure.")
            bmp280.sea_level_pressure = 1013.25
            baseline = bmp280.sea_level_pressure
    except CalibrationError as e:
        logging.error(f"Calibration error: {e}")
        bmp280.sea_level_pressure = 1013.25
        baseline = bmp280.sea_level_pressure
    except Exception as e:
        logging.error(f"Unexpected error during calibration: {e}")
        bmp280.sea_level_pressure = 1013.25
        baseline = bmp280.sea_level_pressure

    try:
        while bmp280._running:
            try:
                altitude = bmp280.get_altitude()
                print(f"Relative altitude: {altitude:.2f} meters")
            except OSError as e:
                logging.error(f"Error reading altitude: {e}")
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    finally:
        bmp280.cleanup()

if __name__ == "__main__":
    main()

