import RPi.GPIO as GPIO
import time

# BCM GPIO4 (physical pin 7) is the DHT22 data line
DHT_PIN = 4

# DHT22 timing (seconds)
START_SIGNAL_LOW = 0.018
RESPONSE_DELAY = 0.0001
RESPONSE_LOW = 0.00008
RESPONSE_HIGH = 0.00008
DATA_DELAY = 0.00005
DATA_BIT_LOW = 0.0001
DATA_BIT_HIGH = 0.0001
MAX_RETRIES = 3
RETRY_DELAY = 2.0
LOOP_DELAY = 5.0

_running = True


def _signal_start():
    GPIO.output(DHT_PIN, GPIO.LOW)
    time.sleep(START_SIGNAL_LOW)
    GPIO.output(DHT_PIN, GPIO.HIGH)
    time.sleep(RESPONSE_DELAY)


def _wait_for_response():
    deadline = time.monotonic() + 0.1
    while GPIO.input(DHT_PIN) == GPIO.HIGH:
        if time.monotonic() > deadline:
            raise TimeoutError("DHT22 not responding (stuck high)")
    time.sleep(RESPONSE_DELAY)


def _read_data():
    deadline = time.monotonic() + 0.1
    while GPIO.input(DHT_PIN) == GPIO.LOW:
        if time.monotonic() > deadline:
            raise TimeoutError("DHT22 not responding (stuck low)")
    time.sleep(RESPONSE_DELAY)

    data = []
    for _ in range(40):
        deadline = time.monotonic() + 0.1
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            if time.monotonic() > deadline:
                raise TimeoutError("DHT22 data bit timeout (stuck high)")
        time.sleep(DATA_DELAY)
        deadline = time.monotonic() + 0.1
        while GPIO.input(DHT_PIN) == GPIO.LOW:
            if time.monotonic() > deadline:
                raise TimeoutError("DHT22 data bit timeout (stuck low)")
        time.sleep(DATA_BIT_HIGH)

    return data


def _calculate_checksum(data):
    return (data[0] + data[1] + data[2] + data[3]) & 0xFF


def _validate_checksum(data, checksum):
    return data[4] == checksum


def read_dht22():
    """Read temperature and humidity from DHT22 with retry logic."""
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            _signal_start()
            _wait_for_response()
            data = _read_data()

            if len(data) < 5:
                raise TimeoutError("Incomplete data received from DHT22")

            checksum = data[4]
            if not _validate_checksum(data, checksum):
                raise ValueError("Checksum mismatch")

            humidity = data[0] * 256 + data[1]
            temperature = data[2] * 256 + data[3]

            return temperature, humidity

        except (TimeoutError, ValueError, RuntimeError) as e:
            print(f"Attempt {attempt}/{MAX_RETRIES}: {e}")
            if attempt < MAX_RETRIES:
                time.sleep(RETRY_DELAY)
            else:
                print("Error reading DHT22 sensor. Check wiring and sensor.")
                time.sleep(RETRY_DELAY)
                return None, None

    return None, None


def main():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.OUT, initial=GPIO.HIGH)

    try:
        while _running:
            temperature, humidity = read_dht22()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C")
                print(f"Humidity: {humidity:.1f}%")
                time.sleep(LOOP_DELAY)
            else:
                print("Failed to read DHT22 sensor.")
                time.sleep(RETRY_DELAY)
    finally:
        GPIO.cleanup()


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        GPIO.cleanup()

