import serial
import serial.tools.list_ports
import numpy as np
import matplotlib.pyplot as plt
import matplotlib.animation as animation
import threading
import queue
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyS0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1
IMAGE_WIDTH = 32
IMAGE_HEIGHT = 24
DATA_POINTS = IMAGE_HEIGHT * IMAGE_WIDTH
SERIAL_TIMEOUT_MS = SERIAL_TIMEOUT * 1000

stop_event = threading.Event()
frame_queue = queue.Queue()


def open_serial_port():
    """Open the serial port; return the Serial object or None on failure."""
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
        print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        return None


def read_thermal_data(ser):
    """Read one line from the serial port and parse it into a 24x32 numpy array."""
    try:
        raw = ser.readline()
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None
    except Exception as e:
        print(f"Unexpected serial read error: {e}")
        return None

    if not raw:
        return None

    try:
        data = raw.decode('ascii', errors='replace').strip()
    except Exception as e:
        print(f"Decode error: {e}")
        return None

    if not data:
        return None

    try:
        values = [int(x) for x in data.split(',')]
    except ValueError as e:
        print(f"ValueError parsing data: {e}")
        return None

    if len(values) != DATA_POINTS:
        print(f"Data has {len(values)} points, expected {DATA_POINTS}.")
        return None

    try:
        return np.array(values).reshape((IMAGE_HEIGHT, IMAGE_WIDTH))
    except Exception as e:
        print(f"Error reshaping data: {e}")
        return None


def update_plot(frame, im, ax, ser, frame_queue, stop_event):
    """Animate the heatmap; return the next frame object."""
    try:
        frame_val = frame_queue.get(timeout=0.1)
    except queue.Empty:
        return frame

    if frame_val is None:
        return frame

    try:
        frame_img = plt.imshow(frame_val, cmap='inferno', interpolation='nearest', vmin=0, vmax=100)
        return animation.ArtistAnimation(
            [frame_img], interval=100, blit=False, cache_frame_data=False
        )
    except Exception as e:
        print(f"Plotting error: {e}")
        return frame


def main():
    ser = open_serial_port()
    if ser is None:
        sys.exit(1)

    plt.ion()
    fig, ax = plt.subplots()
    im = ax.imshow(np.zeros((IMAGE_HEIGHT, IMAGE_WIDTH)), cmap='inferno', interpolation='nearest', vmin=0, vmax=100)
    ax.set_title('Thermal Imaging - Live Data')
    ax.set_xlabel('X Pixel')
    ax.set_ylabel('Y Pixel')
    fig.colorbar(im, ax=ax, label='Temperature (°C)')
    frame, ani = animation.FuncAnimation(
        fig, update_plot, frame_count=1, fargs=(frame, im, ax, ser, frame_queue, stop_event)
    )

    def signal_handler(signum, frame):
        print("\nSignal received, shutting down...")
        stop_event.set()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    reader_thread = threading.Thread(
        target=read_thermal_data, args=(ser,), daemon=True, name='SerialReader'
    )
    reader_thread.start()

    try:
        while not stop_event.is_set():
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("\nKeyboardInterrupt received, exiting...")
    finally:
        stop_event.set()
        reader_thread.join(timeout=5)
        if reader_thread.is_alive():
            print("Warning: serial thread did not exit cleanly.")
        try:
            ser.close()
            print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
        plt.close('all')
        print("Resources released.")


if __name__ == '__main__':
    main()

