import time
import signal
import sys
import board
import adafruit_dht

# Global sensor handle for cleanup
sensor = None

def cleanup(signum=None, frame=None):
    """Release sensor resources on exit."""
    global sensor
    if sensor is not None:
        try:
            sensor.exit()
        except Exception:
            pass
        sensor = None
    if signum is not None:
        sys.exit(0)

# Register signal handlers for graceful shutdown
signal.signal(signal.SIGTERM, cleanup)
signal.signal(signal.SIGINT, cleanup)

try:
    # Initialize DHT11 on GPIO4 (board.D4)
    sensor = adafruit_dht.DHT11(board.D4, use_pulseio=False)
except Exception as e:
    print(f"Failed to initialize DHT11 on GPIO4: {e}")
    sys.exit(1)

print("DHT11 sensor initialized. Reading every 5 seconds. Press Ctrl+C to stop.")

while True:
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
        else:
            print("Sensor returned None values.")
    except RuntimeError as e:
        # Common DHT timing errors; log and continue
        print(f"Read error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    time.sleep(5)

cleanup()

