import time
import board
import busio
import adafruit_bmp280

# Constants
I2C_ADDRESS = 0x76  # Default I2C address for BMP280 (0x77 on some breakouts)
BASELINE_DURATION = 10  # Seconds to collect baseline pressure
BASELINE_INTERVAL = 1  # Seconds between baseline readings
DISPLAY_INTERVAL = 1  # Seconds between altitude displays


def initialize_i2c():
    """Initialize the I2C bus on board.SCL (GPIO3) and board.SDA (GPIO2)."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_bmp280(i2c_bus):
    """Initialize the BMP280 sensor on the I2C bus."""
    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c_bus, address=I2C_ADDRESS)
        return sensor
    except ValueError as e:
        print(f"BMP280 not found at I2C address 0x{I2C_ADDRESS:02X}: {e}")
        return None
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None


def collect_baseline_pressure(sensor, duration=BASELINE_DURATION, interval=BASELINE_INTERVAL):
    """Collect baseline pressure readings over a specified duration."""
    print(f"Collecting baseline pressure for {duration} seconds. Keep the sensor still.")
    readings = []
    start_time = time.monotonic()
    consecutive_failures = 0

    while time.monotonic() - start_time < duration:
        try:
            pressure = sensor.pressure
            readings.append(pressure)
            print(f"  Baseline reading: {pressure:.2f} hPa")
        except OSError as e:
            print(f"  Error reading pressure: {e}")
        except Exception as e:
            print(f"  Unexpected error reading pressure: {e}")

        elapsed = time.monotonic() - start_time
        if elapsed < interval:
            time.sleep(interval)

    if not readings:
        print("Error: No pressure readings collected. Exiting.")
        return None

    return readings


def calculate_average_pressure(readings):
    """Calculate the average pressure, excluding the first two readings."""
    if len(readings) < 3:
        return None
    return sum(readings[1:]) / len(readings[1:])


def calculate_altitude(pressure, baseline_pressure):
    """Calculate relative altitude from pressure, using baseline pressure."""
    if baseline_pressure is None:
        return None
    return 44330 * (1.0 - (pressure / baseline_pressure) ** (1.0 / 5.255))


def main():
    """Main function to initialize sensor, collect baseline, and display altitude."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    bmp280 = initialize_bmp280(i2c_bus)
    if bmp280 is None:
        return

    baseline_readings = collect_baseline_pressure(bmp280)
    if baseline_readings is None:
        return

    baseline_pressure = calculate_average_pressure(baseline_readings)
    if baseline_pressure is None:
        return

    try:
        while True:
            try:
                pressure = bmp280.pressure
                altitude = calculate_altitude(pressure, baseline_pressure)
                print(f"Relative altitude: {altitude:.2f} meters")
            except OSError as e:
                print(f"Error reading pressure: {e}")
            except Exception as e:
                print(f"Unexpected error reading pressure: {e}")

            time.sleep(DISPLAY_INTERVAL)

    except KeyboardInterrupt:
        print("\nExiting program.")


if __name__ == "__main__":
    main()

