import time
import logging
import signal
import sys
import board
import adafruit_dht

# Configure logging
logging.basicConfig(
    filename='wildlife_monitoring.log',
    level=logging.ERROR,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants
DHT22_PINS = [board.D4, board.D17]
ANOMALY_TEMP_HIGH = 35.0
ANOMALY_TEMP_LOW = 5.0
ANOMALY_HUMIDITY_HIGH = 90.0
READ_INTERVAL = 60  # seconds
MAX_RETRIES = 3
RETRY_DELAY = 2  # seconds

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False

def read_dht22(pin):
    """
    Reads temperature and humidity from a DHT22 sensor with retry logic.
    Returns (temperature, humidity) or (None, None) on failure.
    """
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = pin.temperature
            humidity = pin.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
            else:
                logging.error(
                    f"DHT22 on pin {pin} returned None (attempt {attempt}/{MAX_RETRIES})"
                )
        except RuntimeError as e:
            logging.error(
                f"DHT22 on pin {pin} read error (attempt {attempt}/{MAX_RETRIES}): {e}"
            )
        except Exception as e:
            logging.error(
                f"DHT22 on pin {pin} unexpected error (attempt {attempt}/{MAX_RETRIES}): {e}"
            )
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)
    return None, None

def check_anomalies(temperature, humidity, pin):
    """
    Checks for temperature and humidity anomalies and logs them.
    """
    if temperature is None or humidity is None:
        return

    if temperature > ANOMALY_TEMP_HIGH:
        logging.error(
            f"Temperature anomaly detected on pin {pin}: {temperature:.2f}°C "
            f"(Threshold: {ANOMALY_TEMP_HIGH:.2f}°C)"
        )
    elif temperature < ANOMALY_TEMP_LOW:
        logging.error(
            f"Temperature anomaly detected on pin {pin}: {temperature:.2f}°C "
            f"(Threshold: {ANOMALY_TEMP_LOW:.2f}°C)"
        )

    if humidity > ANOMALY_HUMIDITY_HIGH:
        logging.error(
            f"Humidity anomaly detected on pin {pin}: {humidity:.2f}% "
            f"(Threshold: {ANOMALY_HUMIDITY_HIGH:.2f}%)"
        )

def main():
    """
    Main function to read sensor data, check for anomalies, and log them.
    """
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    sensors = []
    try:
        for pin in DHT22_PINS:
            sensor = adafruit_dht.DHT22(pin, use_pulseio=False)
            sensors.append(sensor)
            logging.info(f"DHT22 sensor initialized on pin {pin}")

        while _running:
            for i, sensor in enumerate(sensors):
                temperature, humidity = read_dht22(sensor)

                if temperature is not None and humidity is not None:
                    logging.info(
                        f"Sensor {i+1}: Temperature={temperature:.2f}°C, Humidity={humidity:.2f}%"
                    )
                    check_anomalies(temperature, humidity, DHT22_PINS[i])
                else:
                    logging.error(
                        f"Sensor {i+1}: Failed to read data after {MAX_RETRIES} attempts"
                    )

            # Sleep in small increments to allow signal handler to interrupt promptly
            slept = 0
            while _running and slept < READ_INTERVAL:
                time.sleep(1)
                slept += 1

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # adafruit_dht does not require explicit cleanup, but we close sensors
        for sensor in sensors:
            try:
                sensor.exit()
            except Exception:
                pass
        logging.info("Program terminated gracefully.")
        logging.shutdown()

if __name__ == "__main__":
    main()

