import time
import signal
import sys
import requests
import adafruit_dht

# --- Configuration -----------------------------------------------------------
DHT_PIN = 4  # BCM GPIO4 (physical pin 7)
SERVER_URL = 'http://127.0.0.1:5000/data'
READ_INTERVAL = 5  # seconds between readings

# --- Globals for cleanup -----------------------------------------------------
_running = True
_sensor = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _cleanup():
    """Release sensor resources."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _read_sensor():
    """Return (temperature, humidity) or (None, None) on failure."""
    try:
        temperature = _sensor.temperature
        humidity = _sensor.humidity
        if temperature is None or humidity is None:
            return None, None
        return temperature, humidity
    except RuntimeError as e:
        # DHT11 checksum / timing errors are common; retry next cycle.
        print(f"Sensor read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected sensor error: {e}")
        return None, None


def _send_data(temperature, humidity):
    """POST temperature/humidity to the server; print status code."""
    payload = {'temperature': temperature, 'humidity': humidity}
    try:
        response = requests.post(
            SERVER_URL,
            json=payload,
            timeout=10,
        )
        print(f"Data sent. Status code: {response.status_code}")
    except requests.exceptions.ConnectionError as e:
        print(f"Connection error: {e}")
    except requests.exceptions.Timeout:
        print("Request timed out.")
    except requests.exceptions.RequestException as e:
        print(f"Request error: {e}")


def main():
    global _sensor

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT11 sensor on GPIO4
    try:
        _sensor = adafruit_dht.DHT11(DHT_PIN, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 on GPIO4: {e}")
        sys.exit(1)

    print("Starting DHT11 readings. Press Ctrl+C to stop.")

    try:
        while _running:
            temperature, humidity = _read_sensor()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f} C  Humidity: {humidity:.1f} %")
                _send_data(temperature, humidity)
            else:
                print("Skipping transmission due to invalid sensor data.")
            # Sleep in small increments so signals are caught promptly
            slept = 0
            while _running and slept < READ_INTERVAL:
                time.sleep(0.2)
                slept += 0.2
    finally:
        _cleanup()
        print("Program terminated.")


if __name__ == "__main__":
    main()

