import subprocess
import time
import signal
import sys
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

FAN_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5

TEMP_TABLE = [
    (70, 100),
    (60, 85),
    (50, 70),
    (40, 50),
    (32, 25),
    (25, 15),
]

fan = None
running = True


def get_cpu_temp():
    """Read CPU temperature in degrees Celsius from the kernel thermal zone."""
    try:
        with open('/sys/class/thermal/thermal_zone0/temp', 'r') as f:
            return float(f.read().strip()) / 1000.0
    except (OSError, ValueError) as e:
        logger.error("Failed to read CPU temperature: %s", e)
        return None


def calculate_fan_speed(temp):
    for threshold, speed in TEMP_TABLE:
        if temp > threshold:
            return speed
    return 0


def cleanup(signum=None, frame=None):
    global running
    running = False
    if fan is not None:
        try:
            fan.value = 0
            fan.close()
        except Exception:
            pass
    if signum is not None:
        logger.info("Received signal %s, exiting.", signum)
        sys.exit(0)


def main():
    global fan
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        logger.error("Failed to initialize PWM on GPIO%d: %s", FAN_PIN, e)
        sys.exit(1)

    try:
        while running:
            temp = get_cpu_temp()
            if temp is not None:
                speed = calculate_fan_speed(temp)
                fan.value = speed / 100.0
                logger.info("Temp: %.1f°C -> Fan speed: %d%%", temp, speed)
            else:
                logger.warning("Temperature read failed; maintaining current fan speed.")
            for _ in range(CHECK_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

