import config
import time
import signal
import sys
import paho.mqtt.client as mqtt
import adafruit_dht
import board

DEGREE_CELSIUS = "\u00B0C"

running = True

def signal_handler(signum, frame):
    global running
    running = False

def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        print("Connected to MQTT broker")
    else:
        print(f"Failed to connect to MQTT broker, reason code: {reason_code}")

def on_disconnect(client, userdata, flags, reason_code, properties):
    print(f"Disconnected from MQTT broker, reason code: {reason_code}")

def on_publish(client, userdata, mid, reason_code, properties):
    pass

def read_dht22(sensor):
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return temperature, humidity
    except RuntimeError as e:
        print(f"DHT22 read error: {e}")
        return None, None
    except Exception as e:
        print(f"Unexpected DHT22 error: {e}")
        return None, None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT22 sensor: {e}")
        sys.exit(1)

    client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        client_id=config.mqttclientid
    )
    client.username_pw_set(config.mqttusername, config.mqttpassword)
    client.on_connect = on_connect
    client.on_disconnect = on_disconnect
    client.on_publish = on_publish

    try:
        client.connect(config.mqttbroker, config.mqttport, keepalive=60)
    except Exception as e:
        print(f"Failed to connect to MQTT broker: {e}")
        sys.exit(1)

    client.loop_start()

    try:
        while running:
            temperature, humidity = read_dht22(sensor)

            if temperature is not None and humidity is not None:
                temp_topic = f"homie/{config.homieclientid}/{config.homienodes}/temperature"
                hum_topic = f"homie/{config.homieclientid}/{config.homienodes}/humidity"
                info = f"Temp: {temperature:.1f}{DEGREE_CELSIUS}, Humidity: {humidity:.1f}%"

                try:
                    client.publish(temp_topic, info, qos=1)
                    client.publish(hum_topic, info, qos=1)
                except Exception as e:
                    print(f"MQTT publish error: {e}")

            time.sleep(config.publishtime)
    finally:
        client.loop_stop()
        client.disconnect()
        try:
            sensor.exit()
        except Exception:
            pass
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

