import serial
import time
import signal
import sys
import numpy as np
import matplotlib.pyplot as plt

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1.0
FRAME_WIDTH = 24
FRAME_HEIGHT = 32
EXPECTED_PIXELS = FRAME_WIDTH * FRAME_HEIGHT
UPDATE_INTERVAL = 0.1

running = True
serial_connection = None
figure = None


def signal_handler(signum, frame):
    global running
    running = False


def open_serial_port():
    try:
        conn = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
        if not conn.is_open:
            conn.open()
        print(f"Serial port {SERIAL_PORT} opened at {BAUD_RATE} baud.")
        return conn
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error opening serial port: {e}")
        return None


def read_thermal_frame(conn):
    try:
        raw = conn.readline()
    except serial.SerialException as e:
        print(f"Serial I/O error while reading: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error reading serial data: {e}")
        return None

    if not raw:
        return None

    try:
        text = raw.decode('ascii', errors='replace').strip()
    except Exception as e:
        print(f"Error decoding serial data: {e}")
        return None

    if not text:
        return None

    try:
        tokens = [t.strip() for t in text.split(',') if t.strip()]
    except Exception as e:
        print(f"Error parsing comma-separated tokens: {e}")
        return None

    if len(tokens) != EXPECTED_PIXELS:
        print(f"Expected {EXPECTED_PIXELS} tokens, got {len(tokens)}. Skipping frame.")
        return None

    try:
        values = [int(token) for token in tokens]
    except ValueError as e:
        print(f"Error converting tokens to integers: {e}")
        return None

    if len(values) != EXPECTED_PIXELS:
        print(f"Expected {EXPECTED_PIXELS} integer values, got {len(values)}. Skipping frame.")
        return None

    return values


def display_thermal_image(heatmap):
    plt.clf()
    plt.imshow(heatmap, cmap='inferno', interpolation='nearest')
    plt.colorbar(label='Temperature (°C)')
    plt.title('Thermal Imaging Data')
    plt.pause(0.001)
    plt.gcf().canvas.draw_idle()


def main():
    global serial_connection, figure

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = open_serial_port()
    if serial_connection is None:
        sys.exit(1)

    try:
        figure, ax = plt.subplots(figsize=(8, 6))
        heatmap = ax.imshow(np.zeros((FRAME_HEIGHT, FRAME_WIDTH)), cmap='inferno', interpolation='nearest', vmin=20, vmax=40)
        figure.canvas.manager.set_window_title('Thermal Imaging')
        plt.show(block=False)

        while running:
            frame_data = read_thermal_frame(serial_connection)
            if frame_data is not None:
                heatmap.set_data(frame_data)
                figure.canvas.draw_idle()
                plt.pause(UPDATE_INTERVAL)

    except Exception as e:
        print(f"Runtime error: {e}")

    finally:
        if serial_connection is not None and serial_connection.is_open:
            try:
                serial_connection.close()
                print("Serial port closed.")
            except Exception as e:
                print(f"Error closing serial port: {e}")
        if figure is not None:
            try:
                plt.close('all')
                print("Matplotlib figures closed.")
            except Exception as e:
                print(f"Error closing matplotlib figures: {e}")


if __name__ == '__main__':
    main()

