import signal
import sys
import time

from gpiozero import PWMOutputDevice

FAN_PIN = 18
PWM_FREQ = 100.0
ON_THRESHOLD = 40.0
LOW_SPEED_DUTY = 0.2
HIGH_SPEED_DUTY = 1.0
SLEEP_INTERVAL = 5

fan = None
running = True


def handle_signal(signum, frame):
    global running
    running = False


def cleanup():
    global fan
    if fan is not None:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
        fan = None


def main():
    global fan

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as e:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while running:
            try:
                cpu_temp = 80.0 - (time.time() % 10)
                if cpu_temp > ON_THRESHOLD:
                    fan.value = HIGH_SPEED_DUTY
                else:
                    fan.value = LOW_SPEED_DUTY
                print(f"Temp: {cpu_temp:.1f}C, Fan: {fan.value * 100:.0f}%")
            except Exception as e:
                print(f"Error reading temperature: {e}", file=sys.stderr)

            for _ in range(SLEEP_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

