import serial
import time
import signal
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def parse_sensor_data(data_string):
    """Parse 'temperature,humidity' string into floats."""
    if not data_string:
        return None, None
    parts = data_string.split(',')
    if len(parts) != 2:
        return None, None
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
    except ValueError:
        return None, None
    return temperature, humidity

def check_alerts(temperature, humidity):
    """Return True if temperature or humidity exceeds thresholds."""
    return temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = None
    try:
        serial_connection = serial.Serial(
            SERIAL_PORT,
            BAUD_RATE,
            timeout=READ_TIMEOUT
        )
        print(f"Connected to {SERIAL_PORT} at {BAUD_RATE} baud.")

        while running:
            try:
                raw_bytes = serial_connection.readline()
                if not raw_bytes:
                    continue

                data_string = raw_bytes.decode('ascii', errors='replace').strip()
                if not data_string:
                    continue

                temperature, humidity = parse_sensor_data(data_string)
                if temperature is None or humidity is None:
                    print(f"Warning: could not parse '{data_string}'. Skipping.")
                    continue

                if check_alerts(temperature, humidity):
                    print(f"ALERT: Temperature {temperature:.1f}°C, Humidity {humidity:.1f}% exceeds thresholds.")

                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")

            except serial.SerialException as e:
                print(f"Serial communication error: {e}")
                break
            except Exception as e:
                print(f"Unexpected error during read/parse: {e}")

            time.sleep(1)

    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
    except Exception as e:
        print(f"Unexpected initialization error: {e}")
    finally:
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

