import time
import logging
import random
from gpiozero import LED

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# GPIO pin for the LED (simulated air quality indicator)
LED_PIN = 17

# Initialize the LED (real GPIO resource)
try:
    led = LED(LED_PIN)
    logging.info(f"LED initialized on GPIO{LED_PIN}")
except Exception as e:
    logging.error(f"Failed to initialize LED on GPIO{LED_PIN}: {e}")
    raise SystemExit(1)

def get_temperature():
    """Simulate temperature reading between 20.0 and 30.0 degrees Celsius."""
    return round(random.uniform(20.0, 30.0), 2)

def get_humidity():
    """Simulate humidity reading between 40.0 and 60.0 percent."""
    return round(random.uniform(40.0, 60.0), 2)

def get_ppm():
    """Simulate particulate matter (PPM) reading between 0 and 800."""
    return random.randint(0, 800)

def main():
    logging.info("Air quality monitor started.")
    try:
        while True:
            temperature = get_temperature()
            humidity = get_humidity()
            ppm = get_ppm()

            logging.info(f"Temperature: {temperature}°C, Humidity: {humidity}%, PPM: {ppm}")

            if ppm > 500:
                logging.warning(
                    "ALERT! PPM level exceeded threshold. Temperature: {temperature}°C, Humidity: {humidity}%, PPM: {ppm}"
