import signal
import sys
import time

from gpiozero import DigitalInputDevice
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# GPIO pins (BCM numbering) for the three digital input sensors
SENSOR_PINS = [17, 27, 22]

# Polling interval in seconds
POLL_INTERVAL = 1.0

# Global list of input devices for cleanup
_input_devices = []


def cleanup():
    """Close all GPIO devices to release resources."""
    for dev in _input_devices:
        try:
            dev.close()
        except Exception:
            pass
    _input_devices.clear()


def handle_signal(signum, frame):
    """Signal handler for graceful shutdown."""
    print(f"\nReceived signal {signum}, exiting gracefully...")
    cleanup()
    sys.exit(0)


def main():
    global _input_devices

    # Register signal handlers for clean exit
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    # Initialize GPIO devices with pull-up resistors for defined idle states
    try:
        for pin in SENSOR_PINS:
            dev = DigitalInputDevice(pin, pull_up=True, bounce_time=None)
            _input_devices.append(dev)
    except (GPIOZeroError, GPIODeviceError) as e:
