import sys
import time
import threading
import signal
import RPi.GPIO as GPIO

# Constants
GPIO.setmode(GPIO.BCM)
DOG = None

# Global variables
log_file = None
receive_thread = None
server_running = False
help_messages = {
    "start": "Starts the data logging server.",
    "stop": "Stops the data logging server.",
    "help": "Shows help information.",
    "display": "Displays the contents of the log file.",
    "send": "Sends data using DOG.send()",
    "write": "Writes data directly to the log file.",
    "exit": "Stops the server and exits."
}

def initialize_gpio():
    """Initializes GPIO settings."""
    global DOG
    try:
        GPIO.setwarnings(False)
        GPIO.setmode(GPIO.BCM)
        DOG = GPIO
        print("GPIO initialized successfully.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals."""
    print("\nExiting program...")
    cleanup()
    sys.exit(0)

def cleanup():
    """Cleans up GPIO resources."""
    global DOG
    if DOG is not None:
        try:
            DOG.cleanup()
            print("GPIO cleaned up.")
        except Exception as e:
            print(f"Error during GPIO cleanup: {e}")
    sys.exit(0)

def start_server(filename):
    """Starts the data logging server."""
    global log_file, server_running, receive_thread

    if server_running:
        print("Server is already running.")
        return

    try:
        log_file = open(filename, 'a')
        print(f"Server started. Logging to: {filename}")
        server_running = True
    except IOError as e:
        print(f"Error opening log file: {e}")
        return
    except Exception as e:
        print(f"Unexpected error starting server: {e}")
        return

    receive_thread = threading.Thread(target=receive_data, daemon=True)
    receive_thread.start()

def receive_data():
    """Receives data and logs it to the file."""
    while server_running:
        try:
            data = DOG.receive()
            if data is not None:
                try:
                    log_file.write(data + '\n')
                    log_file.flush()
                except IOError as e:
                    print(f"Error writing to log file: {e}")
                    server_running = False
                    break
        except Exception as e:
            print(f"Error receiving data: {e}")
            server_running = False
            break
        time.sleep(0.1)

def stop_server():
    """Stops the data logging server."""
    global server_running, receive_thread

    if not server_running:
        print("Server is not running.")
        return

    server_running = False
    if receive_thread is not None and receive_thread.is_alive():
        receive_thread.join(timeout=1.0)
    try:
        log_file.close()
    except Exception as e:
        print(f"Error closing log file: {e}")
    cleanup()

def send_data(data):
    """Sends data using DOG.send()."""
    if not server_running:
        print("Server is not running. Start the server first.")
        return
    try:
        DOG.send(data)
        print(f"Sent: {data}")
    except Exception as e:
        print(f"Error sending data: {e}")

def write_data(data):
    """Writes data directly to the log file."""
    if not server_running:
        print("Server is not running. Start the server first.")
        return
    try:
        log_file.write(data + '\n')
        log_file.flush()
        print(f"Wrote to log file: {data}")
    except IOError as e:
        print(f"Error writing to log file: {e}")
    except Exception as e:
        print(f"Unexpected error writing to log file: {e}")

def display_log():
    """Displays the contents of the log file."""
    if not server_running:
        print("Server is not running. Start the server first.")
        return
    try:
        with open(log_file, 'r') as f:
            print(f.read())
    except IOError as e:
        print(f"Error reading log file: {e}")
    except Exception as e:
        print(f"Unexpected error displaying log file: {e}")

def help_command(command):
    """Displays help information."""
    if not server_running:
        print("Server is not running. Start the server first.")
        return
    if command in help_messages:
        print(help_messages[command])
    else:
        print("Unknown command. Available commands: start, stop, help, display, send, write, exit")

def main():
    """Main function to handle user commands."""
    global server_running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio()

    while True:
        try:
            command = input("JAYES@ROVER53:\t").strip().lower()
            args = command.split()

            if not args:
                continue

            if args[0] in ("start", "stop", "help", "display", "send", "write", "exit"):
                help_command(args[0])
            elif args[0] == "help":
                help_command(args[1] if len(args) > 1 else None)
            elif args[0] == "start":
                if len(args) == 2:
                    filename = args[1]
                    start_server(filename)
                else:
                    print("Usage: start <filename>")
            elif args[0] == "stop":
                stop_server()
            elif args[0] == "display":
                display_log()
            elif args[0] == "send":
                if len(args) == 2:
                    send_data(args[1])
                else:
                    print("Usage: send <data>")
            elif args[0] == "write":
                if len(args) == 2:
                    write_data(args[1])
                else:
                    print("Usage: write <data>")
            elif args[0] == "exit":
                stop_server()
                sys.exit(0)
            else:
                print("Unknown command. Available commands: start, stop, help, display, send, write, exit")

        except EOFError:
            print("\nEOF received. Exiting.")
            stop_server()
            sys.exit(0)
        except Exception as e:
            print(f"An unexpected error occurred: {e}")
            stop_server()
            sys.exit(1)

if __name__ == "__main__":
    main()

