import time
import signal
import sys
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

LED_PIN = 18
PWM_FREQ = 1000
TSL2561_ADDR = 0x39
INTEG_TIME_MS = 402
GAIN = adafruit_tsl2561.GAIN_AUTO

running = True
pwm = None
i2c = None

def cleanup():
    global pwm, i2c
    if pwm is not None:
        try:
            pwm.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass

def signal_handler(signum, frame):
    global running
    running = False

def main():
    global pwm, i2c

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LED_PIN, GPIO.OUT)
        pwm = GPIO.PWM(LED_PIN, PWM_FREQ)
        pwm.start(0)
    except Exception as e:
        print(f"Error initializing PWM on GPIO {LED_PIN}: {e}")
        cleanup()
        sys.exit(1)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        cleanup()
        sys.exit(1)

    try:
        sensor = adafruit_tsl2561.TSL2561(i2c, address=TSL2561_ADDR)
        sensor.integration_time = INTEG_TIME_MS
        sensor.gain = GAIN
    except ValueError as e:
        print(f"TSL2561 not found at address 0x{TSL2561_ADDR:02X}: {e}")
        cleanup()
        sys.exit(1)
    except Exception as e:
        print(f"Error initializing TSL2561: {e}")
        cleanup()
        sys.exit(1)

    try:
        while running:
            try:
                lux = sensor.lux
                if lux is None:
                    print("Warning: sensor returned None for lux")
                else:
                    brightness = min(100.0, max(0.0, (lux / 1000.0) * 100.0))
                    pwm.ChangeDutyCycle(brightness)
                    print(f"Lux: {lux:.2f}  |  Brightness: {brightness:.1f}%")
            except OSError as e:
                print(f"I2C bus error reading TSL2561: {e}")
            except Exception as e:
                print(f"Unexpected error reading sensor: {e}")

            time.sleep(1)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

