import RPi.GPIO as GPIO
import time
import sys

# GPIO pins for the two IR sensors (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Line-following states
STATE_FORWARD = 0
STATE_TURN_LEFT = 1
STATE_TURN_RIGHT = 2
STATE_SEARCH = 3

# Sensor thresholds: 0 = black line detected, 1 = white surface
BLACK_THRESHOLD = 0
WHITE_THRESHOLD = 1

# Sampling parameters
SAMPLE_COUNT = 10
SAMPLE_INTERVAL = 0.5  # seconds


def setup_gpio():
    """Configure the GPIO pins for the IR sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as e:
        print(f"GPIO setup failed: {e}", file=sys.stderr)
        sys.exit(1)


def read_sensors():
