import time
import board
import busio
import adafruit_fingerprint

# Constants
I2C_ADDRESS = 0x26
ATTEMPT_DELAY = 1  # seconds


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        # Lock the bus to confirm it is not already in use
        while not i2c_bus.try_lock():
            pass
        i2c_bus.unlock()
        return i2c_bus
    except ValueError as e:
        print(f"I2C bus initialization error (bus may be locked): {e}")
        return None
    except Exception as e:
        print(f"I2C initialization error: {e}")
        return None


def initialize_fingerprint_sensor(i2c_bus):
    """Initialize the Adafruit Fingerprint sensor at the given I2C address."""
    try:
        sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus, addr=I2C_ADDRESS)
        return sensor
    except ValueError as e:
        print(f"Fingerprint sensor initialization error (sensor not found or wrong address): {e}")
        return None
    except RuntimeError as e:
        print(f"Fingerprint sensor initialization error (I2C communication failure): {e}")
        return None
    except Exception as e:
        print(f"Fingerprint sensor initialization error: {e}")
        return None


def authenticate(user_id, fingerprint_sensor):
    """Acquire a fingerprint image, convert it to a template, and search the database."""
    print("Waiting for fingerprint...")
    try:
        image = fingerprint_sensor.get_image()
        if image is None:
            print("No fingerprint detected.")
            return False

        print("Converting image...")
        template = fingerprint_sensor.image_2_tz(1, image)

        print("Searching database...")
        match = fingerprint_sensor.finger_search(template)

        if match:
            print(f"Access Granted for user {user_id} with confidence {match.confidence}.")
            return True
        else:
            print(f"Access Denied for user {user_id}.")
            return False

    except RuntimeError as e:
        print(f"Fingerprint sensor error during authentication: {e}")
        return False
    except Exception as e:
        print(f"An unexpected error occurred during authentication: {e}")
        return False


def main():
    """Main function to run the fingerprint authentication loop."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        print("Exiting program due to I2C initialization failure.")
        return

    fingerprint_sensor = initialize_fingerprint_sensor(i2c_bus)
    if fingerprint_sensor is None:
        print("Exiting program due to fingerprint sensor initialization failure.")
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        return

    try:
        while True:
            authenticate("User1", fingerprint_sensor)
            time.sleep(ATTEMPT_DELAY)

    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        try:
            i2c_bus.deinit()
            print("I2C bus deinitialized.")
        except Exception:
            pass
        print("Exiting program.")


if __name__ == "__main__":
    main()

