import signal
import sys
from gpiozero import PWMOutputDevice

FAN_PIN = 12
PWM_FREQ = 25000  # 25 kHz, standard for 4-wire PWM fans

fan = None
running = True

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.value = 0  # 0% duty cycle
            fan.close()
        except Exception:
            pass
        fan = None

def handle_signal(signum, frame):
    global running
    running = False

def main():
    global fan
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
    except Exception as e:
        print(f"Warning: could not initialize PWM on GPIO{FAN_PIN}: {e}", file=sys.stderr)
        print("Falling back to software PWM (may not be hardware PWM).", file=sys.stderr)
        try:
            fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
        except Exception as e2:
            print(f"Warning: could not initialize even with fallback: {e2}", file=sys.stderr)
            print("Continuing anyway (no hardware PWM available).", file=sys.stderr)
        fan = None

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    print(f"PWM fan controller on GPIO{FAN_PIN} @ {PWM_FREQ} Hz")
    print("Enter a speed 0-100 (q to quit).")

    while running:
        try:
            raw = input("Fan speed: ").strip()
        except EOFError:
            break
        except KeyboardInterrupt:
            break

        if not raw:
            continue

        try:
            speed = float(raw)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")
            continue

        if not 0 <= speed <= 100:
            print("Invalid input. Speed must be between 0 and 100.")
            continue

        if fan is not None:
            try:
                fan.value = speed / 100.0
            except Exception as e:
                print(f"Warning: failed to update PWM duty cycle: {e}", file=sys.stderr)

    cleanup()
    print("Fan stopped. Goodbye.")

if __name__ == "__main__":
    main()

