import signal
import sys
import time

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

LED_PIN = 17
led = None

def cleanup(signum=None, frame=None):
    """Turn off the LED and release resources on exit."""
    global led
    if led is not None:
        try:
            led.off()
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        print("\nExiting gracefully.")
        sys.exit(0)

def main():
    global led
    try:
        led = LED(LED_PIN)
    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error: Could not initialize GPIO{LED_PIN}. Is this running on a Raspberry Pi? ({e})")
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error during GPIO setup: {e}")
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    print(f"Blinking LED on GPIO{LED_PIN} at 1 Hz. Press Ctrl+C to stop.")

    try:
        while True:
            led.on()
            time.sleep(1)
            led.off()
            time.sleep(1)
    except Exception as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

