import time
import signal
import sys
import board
import busio
import adafruit_tsl2561
from gpiozero import PWMLED

LED_PIN = 18
PWM_FREQUENCY = 1000
I2C_ADDRESS = 0x39
LUX_SCALE = 10
RETRY_DELAY = 2
LOOP_DELAY = 1

running = True
led = None
sensor = None


def handle_signal(signum, frame):
    global running
    running = False


def read_lux_with_retry():
    for attempt in range(3):
        try:
            return sensor.lux
        except (OSError, ValueError) as e:
            print(f"Sensor read error (attempt {attempt + 1}/3): {e}")
            if attempt < 2:
                time.sleep(RETRY_DELAY)
    return None


def lux_to_brightness(lux):
    return max(0, min(100, lux / LUX_SCALE))


def cleanup():
    global led, sensor
    if led is not None:
        try:
            led.value = 0
            led.close()
        except Exception:
            pass
    if sensor is not None:
        try:
            sensor.deinit()
        except Exception:
            pass


def main():
    global led, sensor

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_tsl2561.TSL2561(i2c, address=I2C_ADDRESS)
    except (OSError, ValueError) as e:
        print(f"Failed to initialize TSL2561 at 0x{I2C_ADDRESS:02X}: {e}")
        sys.exit(1)

    try:
        led = PWMLED(LED_PIN, frequency=PWM_FREQUENCY)
        led.value = 0
    except Exception as e:
        print(f"Failed to initialize PWMLED on GPIO{LED_PIN}: {e}")
        sys.exit(1)

    print("TSL2561 light-to-LED brightness controller running. Press Ctrl+C to exit.")

    while running:
        lux = read_lux_with_retry()
        if lux is not None:
            brightness = lux_to_brightness(lux)
            led.value = brightness / 100.0
            print(f"Lux: {lux:.2f}  ->  Brightness: {brightness}%")
        else:
            print("Sensor read failed after retries; setting LED to 0%.")
            led.value = 0

        time.sleep(LOOP_DELAY)

    cleanup()
    print("Exited cleanly.")


if __name__ == "__main__":
    main()

