import argparse
import json
import logging
import random
import signal
import sys
import time
from typing import Dict, List, Optional

import numpy as np
import smbus2
import tflite_runtime.interpreter as tflite

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('predictive_maintenance.log'),
        logging.StreamHandler(sys.stdout),
    ],
)
logger = logging.getLogger(__name__)

DEFAULT_CONFIG = {
    'bus_number': '1',
    'vibration_address': '0x1D',
    'current_address': '0x40',
    'vibration_scale_factor': '0.001',
    'shunt_resistance': '0.1',
    'failure_probability_threshold': '0.8',
    'alert_endpoint': 'http://example.com/alerts',
    'model_path': 'model.tflite',
    'log_file': 'predictive_maintenance.log',
}


class SensorReadError(Exception):
    pass


class ConfigurationError(Exception):
    pass


def load_config(config_file: str) -> Dict[str, str]:
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logger.warning(f"Config file not found: {config_file}. Using defaults.")
        return {}
    except json.JSONDecodeError as e:
        logger.error(f"Invalid JSON in config file: {config_file}: {e}. Using defaults.")
        return {}


def initialize_logging(log_file: str) -> None:
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(levelname)s - %(message)s',
        handlers=[
            logging.FileHandler(log_file),
            logging.StreamHandler(sys.stdout),
        ],
    )
    logger = logging.getLogger(__name__)
    logger.info("Logging initialized.")


def read_vibration_data(bus: smbus2.SMBus, address: int) -> Optional[List[float]]:
    try:
        data = bus.read_i2c_block_data(address, 0x00, 3)
        x = int.from_bytes(data[0:2], byteorder='big', signed=True) * 0.001
        y = int.from_bytes(data[2:4], byteorder='big', signed=True) * 0.001
        z = int.from_bytes(data[4:6], byteorder='big', signed=True) * 0.001
        return [x, y, z]
    except Exception as e:
        logger.error(f"Error reading vibration data: {e}")
        raise SensorReadError(f"Failed to read vibration data: {e}")


def read_current_data(bus: smbus2.SMBus, address: int) -> Optional[float]:
    try:
        data = bus.read_i2c_block_data(address, 0x01, 2)
        raw = int.from_bytes(data[0:2], byteorder='big', signed=True)
        shunt_resistance = float(config['shunt_resistance'])
        current = raw * 0.00001 * shunt_resistance
        return current
    except Exception as e:
        logger.error(f"Error reading current data: {e}")
        raise SensorReadError(f"Failed to read current data: {e}")


def preprocess_data(vibration_data: List[float], current_data: float) -> np.ndarray:
    x_data = np.array(vibration_data, dtype=np.float32)
    y_data = np.array(vibration_data, dtype=np.float32)
    z_data = np.array(vibration_data, dtype=np.float32)
    current_data = float(current_data)
    return np.array([x_data, y_data, z_data, current_data], dtype=np.float32)


def predict_failure_probability(interpreter: tflite.Interpreter, data: np.ndarray) -> float:
    input_details = interpreter.get_input_details()
    output_details = interpreter.get_output_details()
    interpreter.set_tensor(input_details[0]['index'], data)
    interpreter.invoke()
    return float(interpreter.get_tensor(output_details[0]['index'])[0][0])


def send_alert(alert_endpoint: str, failure_probability: float) -> None:
    alert_message = {
        'failure_probability': failure_probability,
        'timestamp': time.strftime('%Y-%m-%d %H:%M:%S'),
    }
    try:
        import urllib.request
        headers = {'Content-Type': 'application/json'}
        req = urllib.request.Request(
            alert_endpoint,
            data=json.dumps(alert_message).encode('utf-8'),
            headers=headers,
            method='POST',
        )
        with urllib.request.urlopen(req, timeout=10) as response:
            if response.getcode() == 200:
                logger.info("Alert sent successfully.")
            else:
                logger.error(f"Failed to send alert. HTTP status: {response.getcode()}")
    except Exception as e:
        logger.error(f"Error sending alert: {e}")


def signal_handler(sig, frame):
    logger.info("SIGINT received. Exiting gracefully.")
    sys.exit(0)


def main():
    parser = argparse.ArgumentParser(description="Predictive Maintenance System for Raspberry Pi")
    parser.add_argument('--simulate', action='store_true', help='Simulate sensor data')
    parser.add_argument('--config', default='config.json', help='Path to JSON configuration file')
    args = parser.parse_args()

    try:
        config = load_config(args.config)
    except ConfigurationError as e:
        logger.error(f"Configuration error: {e}")
        sys.exit(1)

    initialize_logging(config['log_file'])
    signal.signal(signal.SIGINT, signal_handler)

    try:
        bus = smbus2.SMBus(int(config['bus_number']))
    except Exception as e:
        logger.error(f"Failed to open I2C bus {config['bus_number']}: {e}")
        sys.exit(1)

    try:
        interpreter = tflite.Interpreter(model_path=config['model_path'])
        interpreter.allocate_tensors()
    except Exception as e:
        logger.error(f"Failed to load TFLite model: {e}")
        bus.close()
        sys.exit(1)

    vibration_window = []
    current_window = []

    try:
        while True:
            if args.simulate:
                x = random.uniform(-0.5, 0.5)
                y = random.uniform(-0.5, 0.5)
                z = random.uniform(-0.5, 0.5)
                current = random.uniform(0, 1)
            else:
                try:
                    x, y, z = read_vibration_data(bus, config['vibration_address'])
                    current = read_current_data(bus, config['current_address'])
                except SensorReadError as e:
                    logger.error(f"Sensor read failed. Re-opening I2C bus: {e}")
                    try:
                        bus.close()
                    except Exception:
                        pass
                    try:
                        bus = smbus2.SMBus(int(config['bus_number']))
                        logger.info("I2C bus re-opened successfully.")
                    except Exception as e2:
                        logger.error(f"Failed to re-open I2C bus: {e2}")
                        time.sleep(1)
                        continue

            vibration_window.append(x)
            vibration_window.append(y)
            vibration_window.append(z)
            current_window.append(current)

            if len(vibration_window) > 5:
                vibration_window.pop(0)
            if len(current_window) > 5:
                current_window.pop(0)

            vibration_avg = sum(vibration_window) / len(vibration_window)
            current_avg = sum(current_window) / len(current_window)

            data = preprocess_data([vibration_avg, vibration_avg, vibration_avg, current_avg])
            failure_probability = predict_failure_probability(interpreter, data)

            if failure_probability > config['failure_probability_threshold']:
                logger.warning(f"Predicted failure probability: {failure_probability:.4f}")
                send_alert(config['alert_endpoint'], failure_probability)

            time.sleep(1)

    except Exception as e:
        logger.error(f"An unexpected error occurred: {e}")
    finally:
        try:
            bus.close()
        except Exception:
            pass
        logger.info("Program terminated.")


if __name__ == "__main__":
    main()

