import random
import signal
import sys
import time

from gpiozero import DigitalOutputDevice, DigitalInputDevice
from gpiozero.exc import GPIOZeroError

PUMP_PIN = 18
SENSOR_PIN = 17
NUM_READINGS = 5
DELAY_SECONDS = 2
LOW_THRESHOLD = 20
HIGH_THRESHOLD = 80

pump = None
sensor = None
running = True


def handle_signal(signum, frame):
    global running
    print(f"\nReceived signal {signum}, shutting down gracefully...")
    running = False


def cleanup():
    global pump, sensor
    if pump is not None:
        try:
            pump.off()
            pump.close()
        except Exception:
            pass
    if sensor is not None:
        try:
            sensor.close()
        except Exception:
            pass
    print("GPIO cleanup completed.")


def main():
    global pump, sensor

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    try:
        pump = DigitalOutputDevice(PUMP_PIN)
        sensor = DigitalInputDevice(SENSOR_PIN, pull_up=True)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO: {e}")
        cleanup()
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not running:
                break

            level = random.randint(0, 100)
            print(f"Reading {i + 1}/{NUM_READINGS}: Water level = {level}%")

            if level < LOW_THRESHOLD:
                pump.on()
                print("  -> Pump ON: Water level too low")
            elif level > HIGH_THRESHOLD:
                pump.off()
                print("  -> Pump OFF: Water level sufficient")
            else:
                state = "ON" if pump.is_active else "OFF"
                print("  -> Pump maintains state: level within range")

            try:
                input_state = int(sensor.value)
            except Exception:
                input_state = "Error reading sensor"

            print(f"  -> Sensor input state = {input_state}")

            if i < NUM_READINGS - 1 and running:
                time.sleep(DELAY_SECONDS)

    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

