import random
import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, GPIODeviceError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

PUMP_PIN = 17
MOISTURE_THRESHOLD = 30
ITERATIONS = 5
DELAY_SECONDS = 2

pump = None
running = True


def handle_signal(signum, frame):
    """Graceful shutdown on SIGTERM (e.g., systemd stop)."""
    global running
    running = False


def read_moisture_level():
    """Simulate a soil-moisture sensor reading between 0 and 100 inclusive."""
    return random.randint(0, 100)


def control_water_pump(moisture_level, pump):
    """Drive the pump based on the moisture reading."""
    if moisture_level < MOISTURE_THRESHOLD:
