    """Initialize GPIO pins for both stepper motors."""
    try:
        GPIO.setup(BED_HEAD_IN1, GPIO.OUT)
        GPIO.setup(BED_HEAD_IN2, GPIO.OUT)
        GPIO.setup(BED_HEAD_IN3, GPIO.OUT)
        GPIO.setup(BED_HEAD_IN4, GPIO.OUT)
        GPIO.setup(BED_FOOT_IN1, GPIO.OUT)
        GPIO.setup(BED_FOOT_IN2, GPIO.OUT)
        GPIO.setup(BED_FOOT_IN3, GPIO.OUT)
        GPIO.setup(BED_FOOT_IN4, GPIO.OUT)
    except Exception as e:
        print(f"Error setting up GPIO pins: {e}")
        GPIO.cleanup()
        sys.exit(1)

def set_motor_pins():
    """Set all four pins to LOW state."""
    try:
        GPIO.output(BED_HEAD_IN1, GPIO.LOW)
        GPIO.output(BED_HEAD_IN2, GPIO.LOW)
        GPIO.output(BED_HEAD_IN3, GPIO.LOW)
        GPIO.output(BED_HEAD_IN4, GPIO.LOW)
        GPIO.output(BED_FOOT_IN1, GPIO.LOW)
        GPIO.output(BED_FOOT_IN2, GPIO.LOW)
        GPIO.output(BED_FOOT_IN3, GPIO.LOW)
        GPIO.output(BED_FOOT_IN4, GPIO.LOW)
    except Exception as e:
        print(f"Error setting GPIO pins: {e}")

def step_motor(motor_number, step_sequence):
    """Rotate a stepper motor by one step using the given sequence."""
    try:
        for step in step_sequence:
