    """Run the automated medication schedule."""
    try:
        print("Starting medication schedule...")
        move_motor(1, head_angle)
        move_motor(2, foot_angle)
        dispense_medication(1, dose_A)
        dispense_medication(2, dose_B)
        heart_rate = read_heart_rate()
        spo2 = read_spo2()
        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2}%")
    except Exception as e:
        print(f"Error in run_schedule: {e}")

def cleanup():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error during GPIO cleanup: {e}")

def main():
    """Main function to run the medication schedule."""
    setup_motor_pins()
    try:
        while True:
            run_schedule(15, 10, 5, 3, 120)
    except KeyboardInterrupt:
        print("\nSchedule interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

