DOOR_LOCK_PIN = 27
UNLOCK_DURATION = 5.0
LOOP_DELAY = 0.1

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        lock = OutputDevice(DOOR_LOCK_PIN, active_high=True, initial_value=False)
    except (GPIOZeroError, GPIODeviceError) as exc:
        print(f"Error: Failed to initialize GPIO {DOOR_LOCK_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Error: Unexpected failure initializing GPIO {DOOR_LOCK_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        print(f"Door lock initialized on GPIO {DOOR_LOCK_PIN} (active-HIGH).")
        print("Press Ctrl+C to exit.")

        while _running:
            try:
                authorization = True
            except Exception as exc:
                print(f"Warning: Failed to simulate authorization: {exc}", file=sys.stderr)
                authorization = False

            if authorization:
                print("Authorization granted: unlocking door...")
                try:
                    lock.on()
                    time.sleep(UNLOCK_DURATION)
                    lock.off()
                    print("Door relocked.")
                except (GPIOZeroError, GPIODeviceError) as exc:
                    print(f"Warning: Failed to control GPIO {DOOR_LOCK_PIN}: {exc}", file=sys.stderr)
