#!/usr/bin/env python3
"""
Automated Chicken Coop Door Controller
Controls a relay on GPIO 17 to open/close a chicken coop door based on sunrise/sunset.
Uses RPi.GPIO with BCM numbering, robust error handling, and clean resource release.
"""

import RPi.GPIO as GPIO
import time
import datetime

# GPIO pin for relay (BCM numbering)
RELAY_PIN = 17

# Sunrise and sunset times as datetime.time objects
sunrise_time = datetime.time(7, 0, 0)
sunset_time = datetime.time(19, 0, 0)

def setup_gpio():
    """Initialize GPIO with error handling."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.HIGH)  # Door closed initially
    except RuntimeError as e:
        print(f"GPIO setup failed: {e}")
        raise

def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception:
        pass  # Ignore cleanup errors

def main():
    setup_gpio()
    try:
        while True:
            current_time = datetime.datetime.now().time()
            if sunrise_time <= current_time <= sunset_time:
                GPIO.output(RELAY_PIN, GPIO.LOW)  # Door open
                print("Door opened")
            else:
                GPIO.output(RELAY_PIN, GPIO.HIGH)  # Door closed
                print("Door closed")
            time.sleep(60)
    except KeyboardInterrupt:
        print("\nExiting program")
    except RuntimeError as e:
        print(f"Runtime error: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

