#!/usr/bin/python3
"""
Motor control class for a DC motor driven by a pigpio PWM pin on a
Raspberry Pi (e.g. L298N motor driver).

Wiring:
  - pigpio PWM output pin (e.g. GPIO 18) -> L298N PWM input
  - pigpio GND / VCC as required by the driver

Requires: pigpio daemon (pigpiod) running and the pigpio Python module
installed (pip install pigpio).
"""

import pigpio


class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass


class Motor:
    """
    Controls a DC motor via pigpio hardware PWM.

    Attributes:
        pi (pigpio.pi): Connected pigpio instance.
        pin (int): BCM GPIO pin number connected to the motor driver PWM input.
    """

    def __init__(self, pi, pin):
        if not isinstance(pi, pigpio.pi):
            raise TypeError("pi must be a pigpio.pi instance")
        if not isinstance(pin, int):
            raise TypeError("pin must be an int (BCM GPIO number)")
        if not pi.connected:
            raise MotorError("pigpio daemon is not connected")

        self.pi = pi
        self.pin = pin
        self._closed = False

        # Configure the pin as an output and set a safe default frequency/duty.
        try:
            self.pi.set_mode(self.pin, pigpio.OUTPUT)
            self.pi.set_PWM_frequency(self.pin, 1000)   # 1 kHz default
            self.pi.set_PWM_dutycycle(self.pin, 0)
        except pigpio.error as e:
            raise MotorError(f"Failed to initialize motor on GPIO {self.pin}: {e}")

    def set_frequency(self, freq):
        """Sets the PWM frequency in Hz."""
        if not isinstance(freq, (int, float)):
            raise TypeError("freq must be numeric")
        if not 1 <= freq <= 40000:
            raise ValueError("Frequency must be between 1 and 40000 Hz")
        if not self.pi.connected:
            raise MotorError("pigpio daemon is not connected")

        try:
            self.pi.set_PWM_frequency(self.pin, int(freq))
        except pigpio.error as e:
            raise MotorError(f"Failed to set PWM frequency to {freq} Hz: {e}")

    def set_duty_cycle(self, duty):
        """
        Sets the motor duty cycle (0-255).

        Args:
            duty (int): Duty cycle value (0-255).

        Raises:
            MotorError: If duty is out of range, pigpio call fails, or
                         pigpio is disconnected.
        """
        if not isinstance(duty, int):
            raise TypeError("duty must be an int")
        if not 0 <= duty <= 255:
            raise ValueError("Duty cycle must be between 0 and 255")
        if not self.pi.connected:
            raise MotorError("pigpio daemon is not connected")

        try:
            self.pi.set_PWM_dutycycle(self.pin, int(duty))
        except pigpio.error as e:
            raise MotorError(f"Failed to set PWM duty cycle to {duty}: {e}")

    def stop(self):
        """Stops the motor by setting duty cycle to 0."""
        if self._closed:
            return
        try:
            self.set_duty_cycle(0)
        except MotorError as e:
            print(f"Warning: could not stop motor: {e}", file=sys.stderr)

    def close(self):
        """Releases the motor resource (sets duty cycle to 0 and closes pin)."""
        if self._closed:
            return
        try:
            self.stop()
        except MotorError as e:
            print(f"Warning: stop() failed during close(): {e}", file=sys.stderr)
        finally:
            try:
                self.pi.set_mode(self.pin, pigpio.INPUT)
            except pigpio.error:
                pass
            self._closed = True

    def __del__(self):
        """Best-effort cleanup on object destruction."""
        try:
            self.close()
        except Exception:
            pass


if __name__ == "__main__":
    pi = pigpio.pi()
    if not pi.connected:
        print("Error: could not connect to pigpio daemon. Is pigpiod running?", file=sys.stderr)
        pi.stop()
        raise SystemExit(1)

    motor = Motor(pi, 18)
    try:
        motor.set_frequency(2000)
        motor.set_duty_cycle(128)
        motor.stop()
    finally:
        motor.close()
        pi.stop()

