import serial
import time
import signal
import sys
from gpiozero import PWMOutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERVO_PIN = 17
PWM_FREQUENCY = 50

running = True

def signal_handler(sig, frame):
    global running
    running = False

def angle_to_duty_cycle(angle):
    return angle / 18.0 + 2.0

def move_servo(servo, angle):
    duty = angle_to_duty_cycle(angle)
    try:
        servo.value = duty / 100.0
        time.sleep(1)
        servo.value = 0
    except Exception as e:
        print(f"Error moving servo: {e}")

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

    try:
        servo = PWMOutputDevice(SERVO_PIN, frequency=PWM_FREQUENCY, initial_value=0)
    except Exception as e:
        print(f"Error initializing servo on GPIO {SERVO_PIN}: {e}")
        serial_connection.close()
        sys.exit(1)

    try:
        while running:
            try:
                raw = serial_connection.readline()
                if raw:
                    command = raw.decode('ascii', errors='replace').strip()
                    if command:
                        try:
                            angle = int(command)
                            if 0 <= angle <= 180:
                                move_servo(servo, angle)
                            else:
                                print(f"Invalid angle: {angle}. Must be between 0 and 180.")
                        except ValueError:
                            print(f"Invalid input: {command}. Please enter an integer.")
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
                time.sleep(0.1)
            except Exception as e:
                print(f"Unexpected error: {e}")
    finally:
        try:
            servo.value = 0
            servo.close()
        except Exception:
            pass
        try:
            serial_connection.close()
        except Exception:
            pass
        print("Resources released. Exiting.")

if __name__ == "__main__":
    main()

