import signal
import sys
import logging
from typing import Optional

import serial
from minimalmodbus.client import ModbusSerialClient

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class ServoMotor:
    """Robust Modbus RTU servo motor driver for Raspberry Pi."""

    _REGISTERS = {
        "operation_mode": 0x3500,
        "write_position_command": 0x4000,
        "write_velocity_command": 0x6F00,
        "read_position_feedback": 0x3700,
        "read_velocity_feedback": 0x3B00,
        "start": 0x3100,
        "stop": 0x3000,
        "status": 0x3000,
    }

    def __init__(self, port: str = "/dev/serial0", baudrate: int = 115200, slave_addr: int = 1):
        self.slave_addr = slave_addr
        self.client: Optional[ModbusSerialClient] = None
        self._running = False

        try:
            self.client = ModbusSerialClient(
                port=port,
                baudrate=baudrate,
                bytesize=8,
                parity="N",
                stopbits=1,
                timeout=1.0,
            )
        except serial.SerialException as exc:
            logger.error("Failed to open serial port %s: %s", port, exc)
            raise

        try:
            self.client.connect()
        except serial.SerialException as exc:
            logger.error("Failed to connect to Modbus device on %s: %s", port, exc)
            self.client.close()
            self.client = None
            raise

        logger.info("Connected to Modbus device on %s (slave %d)", port, slave_addr)

    def close(self):
        """Release serial resources."""
        if self.client is not None:
            try:
                self.client.close()
            except Exception as exc:
                logger.warning("Error closing Modbus client: %s", exc)
            finally:
                self.client = None

    def _write_register(self, register: int, value: int) -> None:
        if self.client is None:
            raise RuntimeError("Modbus client is not initialized")
        try:
            self.client.write_register(register, value)
        except Exception as exc:
            logger.error("Modbus write error (reg 0x%04X): %s", register, exc)
            raise

    def _read_registers(self, register: int, count: int) -> Optional[list]:
        if self.client is None:
            raise RuntimeError("Modbus client is not initialized")
        try:
            return self.client.read_registers(register, count)
        except Exception as exc:
            logger.error("Modbus read error (reg 0x%04X): %s", register, exc)
            return None

    def set_operation_mode(self, mode: int) -> None:
        if not (0 <= mode <= 3):
            raise ValueError("operation_mode must be 0-3")
        self._write_register(self._REGISTERS["operation_mode"], mode)

    def write_position_command(self, value: int) -> None:
        if not (0 <= value <= 3):
            raise ValueError("write_position_command value must be 0-3")
        self._write_register(self._REGISTERS["write_position_command"], value)

    def write_velocity_command(self, value: int) -> None:
        if not (0 <= value <= 3):
            raise ValueError("write_velocity_command value must be 0-3")
        self._write_register(self._REGISTERS["write_velocity_command"], value)

    def read_position_feedback(self) -> Optional[list]:
        return self._read_registers(self._REGISTERS["read_position_feedback"], 2)

    def read_velocity_feedback(self) -> Optional[list]:
        return self._read_registers(self._REGISTERS["read_velocity_feedback"], 2)

    def start(self) -> None:
        self._write_register(self._REGISTERS["start"], 0x000F)

    def stop(self) -> None:
        self._write_register(self._REGISTERS["stop"], 0x0006)

    def read_status(self) -> Optional[int]:
        return self._read_registers(self._REGISTERS["status"], 1)[0]

    def run(self, operation_mode: int, position: int, velocity: int) -> None:
        if not (0 <= operation_mode <= 3):
            raise ValueError("operation_mode must be 0-3")
        if not (0 <= position <= 3):
            raise ValueError("position must be 0-3")
        if not (0 <= velocity <= 3):
            raise ValueError("velocity must be 0-3")

        self.set_operation_mode(operation_mode)
        self.write_position_command(position)
        self.write_velocity_command(velocity)
        self.start()

    def stop_running(self) -> None:
        self.stop()

    def is_running(self) -> bool:
        return self.read_status() == 0x000F

    def stop_if_running(self) -> None:
        if self.is_running():
            self.stop()


def _signal_handler(signum, frame, motor: Optional[ServoMotor] = None):
    logger.info("Signal %d received, shutting down", signum)
    if motor is not None:
        motor.stop_running()
    sys.exit(0)


def main():
    motor = None
    try:
        motor = ServoMotor(port="/dev/serial0", baudrate=115200, slave_addr=1)
        signal.signal(signal.SIGINT, lambda s, f: _signal_handler(s, f, motor))
        signal.signal(signal.SIGTERM, lambda s, f: _signal_handler(s, f, motor))

        motor.run(operation_mode=0, position=1, velocity=2)
        logger.info("Position feedback: %s", motor.read_position_feedback())
        logger.info("Velocity feedback: %s", motor.read_velocity_feedback())
        logger.info("Status: %s", motor.read_status())

    except Exception as exc:
        logger.error("Servo motor error: %s", exc)
    finally:
        if motor is not None:
            motor.close()


if __name__ == "__main__":
    main()

