import time
import signal
import sys
import board
import busio
from adafruit_servokit import ServoKit

# Constants for servo channels
BASE = 0
DROP = 1
SEEK = 2
GRAB = 4

# Constants for servo angles
GRAB_ANGLE = 90
DROP_Metal = 135
DROP_Plastic = 180
DROP_Paper = 90
PICK_ANGLE = 90
SEEK_ANGLE = 90
RETURN_ANGLE = 90

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _clamp(value, lo, hi):
    return max(lo, min(hi, value))

def move_servo(kit, channel, target_angle, step_size=5, delay=0.04):
    """Moves a servo to a target angle in steps."""
    if not 0 <= channel < 16:
        print(f"Error: Invalid servo channel {channel}. Must be 0-15.")
        return
    if not 0 <= target_angle <= 180:
        print(f"Error: Invalid target angle {target_angle}. Must be 0-180.")
        return
    try:
        current_angle = kit.servo[channel].angle
        if current_angle is None:
            current_angle = 0
        current_angle = int(round(current_angle))
        target_angle = int(round(target_angle))
        if current_angle == target_angle:
            return
        step = step_size if target_angle > current_angle else -step_size
        angle = current_angle
        while _running and angle != target_angle:
            angle += step
            if not 0 <= angle <= 180:
                angle = 0 if angle > 180 else 180
            kit.servo[channel].angle = angle
            time.sleep(delay)
        kit.servo[channel].angle = target_angle
    except Exception as e:
        print(f"Error moving servo {channel}: {e}")

def seek(angle):
    move_servo(kit, SEEK, angle)

def deseek(angle):
    move_servo(kit, SEEK, angle)

def drop(angle):
    move_servo(kit, DROP, angle)

def pick(angle):
    move_servo(kit, GRAB, angle)

def grab(angle):
    move_servo(kit, GRAB, angle)

def release(angle):
    move_servo(kit, GRAB, angle)

def collect_object_steps(seek_angle):
    """Performs steps to collect an object."""
    seek(seek_angle)
    pick(PICK_ANGLE)
    drop(DROP_Plastic)
    raise(PICK_ANGLE)
    return_to_base()

def drop_object_steps(drop_angle, step_size=2, delay=0.01):
    """Performs steps to drop an object."""
    drop(drop_angle, step_size, delay)
    release(120)
    drop(drop_angle, step_size, delay)
    return_to_base()

def return_to_base():
    move_servo(kit, BASE, RETURN_ANGLE)

def get_pos_x(x_center):
    """Calculates the x-position based on object center."""
    if x_center < 160:
        return 90
    elif x_center < 240:
        return 67
    elif x_center < 320:
        return 45
    else:
        return 22

def get_pos_y(y_center):
    """Calculates the y-position based on object center."""
    if y_center < 80:
        return 22
    elif y_center < 120:
        return 45
    elif y_center < 160:
        return 67
    else:
        return 90

def collect_object(x_center, y_center, drop_angle):
    """Collects an object at the specified coordinates and drops it."""
    try:
        pos_x = get_pos_x(x_center)
        pos_y = get_pos_y(y_center)
        move_servo(kit, BASE, pos_x)
        collect_object_steps(seek_angle)
        drop_object_steps(drop_angle)
    except Exception as e:
        print(f"Error during object collection: {e}")
    finally:
        move_servo(kit, BASE, RETURN_ANGLE)

def main():
    """Main function to demonstrate servo control."""
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        kit = ServoKit(channels=16, i2c=i2c, address=0x40)
    except Exception as e:
        print(f"Failed to initialize ServoKit: {e}")
        sys.exit(1)

    try:
        while _running:
            time.sleep(0.1)
    finally:
        for ch in range(BASE, BASE + 4):
            try:
                kit.servo[ch].angle = None
            except Exception:
                pass
        try:
            i2c.deinit()
        except Exception:
            pass

if __name__ == "__main__":
    main()

