import signal
import sys
import time

import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# --- Configuration -----------------------------------------------------------
I2C_ADDRESS = 0x36
DRY_SOIL_THRESHOLD = 500
PUMP_GPIO_PIN = 17
READ_INTERVAL_SEC = 10
PUMP_OFF_ON_ERROR = True

# --- Globals for cleanup -----------------------------------------------------
_running = True
_i2c = None
_sensor = None
_pump_off = False


def _cleanup():
    """Turn the pump off and release GPIO resources."""
    global _pump_off, _i2c, _sensor
    if _pump_off:
        return
    _pump_off = True
    try:
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
    except Exception:
        pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    if _i2c is not None:
        try:
            _i2c.deinit()
        except Exception:
            pass
        _i2c = None
    if _sensor is not None:
        try:
            _sensor = None
        except Exception:
            pass


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
