import signal
import sys
import logging
from flask import Flask, request, jsonify

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError, DeviceClosed
except ImportError:
    logging.error("gpiozero is not installed. Install with: pip install gpiozero")
    sys.exit(1)

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
app = Flask(__name__)

RELAY_PIN = 23
relay = None

def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        try:
            relay.close()
            logging.info("GPIO cleanup completed.")
        except DeviceClosed:
            pass
        except GPIOZeroError as e:
            logging.error(f"GPIO cleanup error: {e}")
        finally:
            relay = None
    if signum is not None:
        sys.exit(0)

signal.signal(signal.SIGINT, cleanup)
signal.signal(signal.SIGTERM, cleanup)

try:
    relay = OutputDevice(RELAY_PIN)
    logging.info(f"Relay initialized on GPIO{RELAY_PIN}.")
except GPIOZeroError as e:
    logging.error(f"Failed to initialize GPIO{RELAY_PIN}: {e}")
    sys.exit(1)

@app.route('/relay', methods=['POST'])
def relay_control():
    try:
        request_data = request.get_json(silent=True)
        if not request_data or 'state' not in request_data:
            return jsonify({'error': 'Invalid request: Missing or malformed JSON, or missing "state" key'}), 400

        relay_state = request_data['state']
        if relay_state not in ('on', 'off'):
            return jsonify({'error': 'Invalid request: "state" must be "on" or "off"'}), 400

        try:
            relay.on() if relay_state == 'on' else relay.off()
            logging.info(f"Relay set to {'ON' if relay_state == 'on' else 'OFF'}")
            return jsonify({'status': 'Relay state changed'}), 200
        except DeviceClosed:
            logging.error("Relay device was closed unexpectedly.")
            return jsonify({'error': 'Device closed during operation'}), 500
        except GPIOZeroError as e:
            logging.error(f"GPIO error while setting relay state: {e}")
            return jsonify({'error': 'GPIO error'}), 500

    except Exception as e:
        logging.error(f"Unexpected error in relay_control: {e}")
        return jsonify({'error': 'Internal server error'}), 500

if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000)
    finally:
        cleanup()

