#!/usr/bin/env python3
"""
Automated Chicken Coop Door Controller
Controls a relay on GPIO17 (BCM) to open/close a door at sunrise/sunset.
"""

import RPi.GPIO as GPIO
import time
import datetime
import sys

# GPIO pin for the relay (BCM numbering)
RELAY_PIN = 17

def setup_gpio():
    """Initialize GPIO mode and relay pin."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

def open_door():
    """Set relay LOW to open the door."""
    try:
        GPIO.output(RELAY_PIN, GPIO.LOW)
        print(f"{datetime.datetime.now()} - Door opened")
    except Exception as e:
        print(f"Error opening door: {e}")

def close_door():
    """Set relay HIGH to close the door."""
    try:
        GPIO.output(RELAY_PIN, GPIO.HIGH)
        print(f"{datetime.datetime.now()} - Door closed")
    except Exception as e:
        print(f"Error closing door: {e}")

def main():
    setup_gpio()
    sunrise_time = datetime.time(7, 0)
    sunset_time = datetime.time(19, 0)

    try:
        while True:
            current_time = datetime.datetime.now()
            if current_time.time() >= sunset_time:
                close_door()
            elif current_time.time() <= sunrise_time:
                open_door()
            time.sleep(60)
    except KeyboardInterrupt:
        print("\nExiting program...")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

