import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional, Tuple

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


@dataclass
class GPSReadings:
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    altitude: Optional[float] = None
    satellites: Optional[int] = None


class GPSReader:
    def __init__(self, port: str = '/dev/serial0', baudrate: int = 9600):
        self.port = port
        self.baudrate = baudrate
        self.serial_connection: Optional[serial.Serial] = None
        self._closed = False

    def connect(self) -> None:
        try:
            self.serial_connection = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=1.0,
            )
            logger.info("Connected to GPS on %s at %d baud", self.port, self.baudrate)
        except serial.SerialException as e:
            logger.error("Failed to open serial port %s: %s", self.port, e)
            raise

    def disconnect(self) -> None:
        if self.serial_connection is not None:
            try:
                if self.serial_connection.is_open:
                    self.serial_connection.close()
                    logger.info("Serial port closed")
            except serial.SerialException as e:
                logger.error("Error closing serial port: %s", e)
            finally:
                self.serial_connection = None
                self._closed = True

    def _read_line(self) -> Optional[str]:
        if self.serial_connection is None or not self.serial_connection.is_open:
            return None
        try:
            return self.serial_connection.readline().decode('ascii', errors='replace').strip()
        except serial.SerialException as e:
            logger.error("Serial read error: %s", e)
            return None
        except Exception as e:
            logger.error("Unexpected read error: %s", e)
            return None

    def _parse_gga(self, line: str) -> Optional[GPSReadings]:
        if not line.startswith('GPGGA'):
            return None
        try:
            parts = line.split(',')
            if len(parts) < 15:
                logger.warning("GPGGA sentence too short: %r", line)
                return None
            talker = parts[0]
            if talker != 'GPGGA':
                logger.warning("Non-GPGGA talker '%s' in sentence: %r", talker, line)
                return None
            if len(parts) < 12:
                logger.warning("GPGGA sentence missing fields: %r", line)
                return None
            lat = parts[2]
            lat_dir = parts[3]
            lon = parts[4]
            lon_dir = parts[5]
            fix_quality = parts[6]
            altitude = parts[9]
            sat = parts[10]
            if not lat or not lon:
                logger.warning("Empty lat/lon in sentence: %r", line)
                return None
            if not fix_quality or fix_quality == '0':
                logger.warning("No GPS fix (Q=0): %r", line)
                return None
            if not altitude:
                logger.warning("No altitude in sentence: %r", line)
                return None
            if not sat:
                logger.warning("No satellites in sentence: %r", line)
                return None
            return GPSReadings(
                latitude=float(lat) + float(lat_dir) / 100.0,
                longitude=float(lon) + float(lon_dir) / 100.0,
                altitude=float(altitude) / 10.0,
                satellites=int(sat),
            )
        except (ValueError, IndexError) as e:
            logger.error("Failed to parse GPGGA sentence '%s': %s", line, e)
            return None

    def get_readings(self) -> Optional[GPSReadings]:
        raw = self._read_line()
        if raw is None:
            return None
        return self._parse_gga(raw)

    def close(self) -> None:
        self.disconnect()


def _signal_handler(signum, frame):
    logger.info("Signal %d received, shutting down...", signum)
    sys.exit(0)


def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    gps = GPSReader(port='/dev/serial0', baudrate=9600)
    try:
        gps.connect()
        while not gps._closed:
            readings = gps.get_readings()
            if readings is not None:
                logger.info("GPS: lat=%.6f lon=%.6f alt=%.1f sat=%d", readings.latitude, readings.longitude, readings.altitude, readings.satellites)
            else:
                logger.debug("No valid GPS fix this cycle")
    except Exception as e:
        logger.error("Fatal error: %s", e)
    finally:
        gps.close()


if __name__ == '__main__':
    main()

