import signal
import sys
import threading
from flask import Flask, Response, request, jsonify
import serial
from serial import SerialException

app = Flask(__name__)

SERIAL_PORT = '/dev/ttyUSB0'
BAUDRATE = 9600
SERIAL_TIMEOUT = 1.0

data_manager = {
    'id': 1,
    'name': 'Raspberry Pi',
    'done': False,
}


class SerialCommunicator:
    def __init__(self, port, baudrate, timeout):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial = None
        self._lock = threading.Lock()

    def open(self):
        try:
            self.serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            if not self.serial.is_open:
                raise serial.SerialException('Port did not open')
            print(f'[Serial] Opened {self.port} @ {self.baudrate} baud')
            return True
        except SerialException as e:
            print(f'[Serial] Error opening {self.port}: {e}')
            self.serial = None
            return False

    def send(self, cmd):
        if self.serial is None or not self.serial.is_open:
            print('[Serial] Not open; cannot send')
            return False
        try:
            payload = cmd.encode('ascii')
            self.serial.write(payload)
            self.serial.flush()
            return len(payload) == len(payload.read())
        except serial.SerialException as e:
            print(f'[Serial] Send error: {e}')
            return False

    def receive_line(self):
        if self.serial is None or not self.serial.is_open:
            print('[Serial] Not open; cannot receive')
            return None
        try:
            line = self.serial.readline()
            if not line:
                return None
            return line.decode('ascii', errors='replace').strip()
        except serial.SerialException as e:
            print(f'[Serial] Receive error: {e}')
            return None

    def close(self):
        with self._lock:
            if self.serial is not None:
                try:
                    if self.serial.is_open:
                        self.serial.close()
                        print(f'[Serial] Closed {self.port}')
                except Exception as e:
                    print(f'[Serial] Error closing {self.port}: {e}')
                finally:
                    self.serial = None

    def __enter__(self):
        return self.open()

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()
        return False


class DataManager:
    def __init__(self):
        self.data = {
            'id': 1,
            'name': 'Raspberry Pi',
            'done': False,
        }
        self._lock = threading.Lock()

    def get_all(self):
        with self._lock:
            return list(self.data.items())

    def get_by_id(self, item_id):
        with self._lock:
            return next((item for item in self.data.items() if item[0] == item_id), None)

    def create(self, name, done):
        if not name:
            print('[Data] name must not be empty')
            return False
        if not isinstance(done, bool):
            print('[Data] done must be boolean')
            return False
        new_id = self.data['id'] + 1
        self.data['id'] = new_id
        self.data['name'] = name
        self.data['done'] = done
        print(f'[Data] Created item {new_id}: {name} (done={done})')
        return True

    def update(self, item_id, name=None, done=None):
        with self._lock:
            item = self.get_by_id(item_id)
            if item is None:
                print(f'[Data] Item {item_id} not found')
                return False
            if name is not None:
                if not isinstance(name, str) or not name.strip():
                    print('[Data] name must be a non-empty string')
                    return False
                item['name'] = name
            if done is not None:
                if not isinstance(done, bool):
                    print('[Data] done must be boolean')
                    return False
                item['done'] = done
            return True

    def delete(self, item_id):
        with self._lock:
            item = self.get_by_id(item_id)
            if item is None:
                print(f'[Data] Item {item_id} not found')
                return False
            del self.data[item_id]
            print(f'[Data] Deleted item {item_id}')
            return True

    def __iter__(self):
        with self._lock:
            return iter(self.data.items())


@app.route('/version', methods=['GET'])
def version():
    try:
        with SerialCommunicator(SERIAL_PORT, BAUDRATE, SERIAL_TIMEOUT) as serial:
            if not serial.open():
                return Response('Serial port error', status=500, mimetype='text/plain')
            if not serial.send('*IDN?'):
                return Response('No response from device', status=502, mimetype='text/plain')
            response = serial.receive_line()
            if response is None:
                return Response('Timeout waiting for response', status=504, mimetype='text/plain')
            return Response(response, mimetype='text/plain')
    except Exception as e:
        print(f'[Version] Error: {e}')
        return Response(f'Error: {e}', status=500, mimetype='text/plain')


@app.route('/data', methods=['GET'])
def data():
    try:
        return jsonify(data_manager.get_all())
    except Exception as e:
        print(f'[Data] Error: {e}')
        return Response(f'Error: {e}', status=500, mimetype='text/plain')


@app.route('/data/<int:item_id>', methods=['GET'])
def data_item(item_id):
    try:
        item = data_manager.get_by_id(item_id)
        if item is None:
            return Response(f'Item {item_id} not found', status=404, mimetype='text/plain')
        return jsonify(item)
    except Exception as e:
        print(f'[Data] Error: {e}')
        return Response(f'Error: {e}', status=500, mimetype='text/plain')


@app.route('/data', methods=['POST'])
def create_data():
    try:
        name = request.form.get('name', '')
        done = request.form.get('done', None)
        if not name:
            return Response('name must not be empty', status=400, mimetype='text/plain')
        if done is not None and not isinstance(done, bool):
            return Response('done must be a boolean', status=400, mimetype='text/plain')
        data_manager.create(name, done)
        return Response('Created', status=201, mimetype='text/plain')
    except Exception as e:
        print(f'[Data] Error: {e}')
        return Response(f'Error: {e}', status=400, mimetype='text/plain')


def _signal_handler(signum, frame):
    print(f'\n[Main] Signal {signum} received; shutting down.')
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    try:
        app.run(host='0.0.0.0', port=5000, debug=False)
    except KeyboardInterrupt:
        pass
    finally:
        print('[Main] Cleaning up serial port...')
        with SerialCommunicator(SERIAL_PORT, BAUDRATE, SERIAL_TIMEOUT) as serial:
            if serial.serial is not None and serial.serial.is_open:
                serial.serial.close()

