    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = None
    try:
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f'Connected to RFID reader on {SERIAL_PORT} at {BAUD_RATE} baud.')

        while running:
            try:
                raw_line = serial_connection.readline()
                if not raw_line:
                    continue

                tag_data = raw_line.decode('ascii', errors='replace').strip()
                if tag_data:
