import serial
import time
import sys

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1.0
LOOP_DELAY = 1.0

def parse_pulse_ox_data(data: str) -> tuple:
    """Parse '<heart_rate>,<spo2>' into (heart_rate, spo2)."""
    parts = data.split(',')
    if len(parts) != 2:
        raise ValueError(f"Expected 2 fields, got {len(parts)}")
    heart_rate, spo2 = parts[0].strip(), parts[1].strip()
    return int(heart_rate), float(spo2)

def main() -> None:
    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=READ_TIMEOUT,
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud. Reading pulse ox data...")

        while True:
            try:
                raw = ser.readline()
            except serial.SerialException as e:
                print(f"Serial read error: {e}", file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                heart_rate, spo2 = parse_pulse_ox_data(line)
                print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")
            except ValueError as e:
                print(f"Invalid data format: {line!r} - {e}", file=sys.stderr)

            time.sleep(LOOP_DELAY)

    except serial.SerialException as e:
        print(f"Failed to open serial port {SERIAL_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == '__main__':
    main()

