    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

def main():
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT) as ser:
            logging.info('Serial port %s opened at %d baud.', SERIAL_PORT, BAUD_RATE)

            while True:
                try:
                    raw = ser.readline()
                    if not raw:
                        continue

                    line = raw.decode('ascii', errors='replace').strip()
                    if not line:
                        continue

                    power = float(line)
                    logging.info('Power: %.2f W', power)
                    print(f'Power: {power:.2f} W')

                except ValueError:
                    logging.warning('Invalid data received: %r', line)

    except serial.SerialException as e:
        logging.error('Serial port error: %s', e)
        sys.exit(1)
    except OSError as e:
        logging.error('OS error opening serial port: %s', e)
        sys.exit(1)
    except KeyboardInterrupt:
        logging.info('Program terminated by user.')
        sys.exit(0)

if __name__ == '__main__':
    main()

