    if not open_serial():
        return Response(
            "Serial port unavailable - cannot query instrument.\n",
            mimetype='text/html',
            status=503,
        )
    try:
        serial_port.write(b'*IDN?\n')
        serial_port.flush()
        time.sleep(0.1)
        response = serial_port.read(4096)
        if not response:
            return Response(
                "No response from instrument (timeout).\n",
                mimetype='text/html',
                status=503,
            )
        return Response(
            response.decode('utf-8', errors='replace').strip(),
            mimetype='text/html',
        )
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return Response(
            "Serial port error - cannot query instrument.\n",
            mimetype='text/html',
            status=503,
        )
    except Exception as e:
        print(f"Unexpected error querying instrument: {e}", file=sys.stderr)
        return Response(
            "Internal server error.\n",
            mimetype='text/html',
            status=500,
        )
    finally:
        if serial_port and serial_port.is_open:
            serial_port.close()


