import serial
import time
import sys

BLUETOOTH_PORT = "/dev/rfcomm4"
BLUETOOTH_BAUDRATE = 38400


def send_command(ser, command):
    """Send a command prefixed with 'X' and terminated with a newline.

    Args:
        ser: An open serial.Serial instance.
        command: The command string to send.

    Raises:
        RuntimeError: If the write operation fails.
    """
    command_with_prefix = "X" + command + "\n"
    try:
        bytes_written = ser.write(command_with_prefix.encode("utf-8"))
        ser.flush()
        if bytes_written != len(command_with_prefix):
            raise RuntimeError(
                f"Incomplete write: expected {len(command_with_prefix)} bytes, "
                f"wrote {bytes_written} bytes."
            )
        print(f"Sent: {command_with_prefix.strip()}")
    except serial.SerialException as e:
        raise RuntimeError(f"Failed to send command '{command}': {e}") from e


def main():
    """Establish the serial connection and continuously prompt for commands."""
    ser = None
    try:
        ser = serial.Serial(
            port=BLUETOOTH_PORT,
            baudrate=BLUETOOTH_BAUDRATE,
            timeout=1.0,
        )
        print(f"Connected to {BLUETOOTH_PORT} at {BLUETOOTH_BAUDRATE} baud.")

        while True:
